window.SU_DANG_DATA = {"source": {"title": "Giáo trình Lịch sử Đảng Cộng sản Việt Nam", "author": "Bộ Giáo dục và Đào tạo", "year": 2021, "publisher": "NXB Chính trị quốc gia Sự thật", "isbn": "9786045765906", "pages": 440, "sha256": "bc108b5153b2ed982a05567d233faed4249ed88b79502314bec3f793b3edb98f"}, "chapters": [{"id": "nm", "label": "Nhập môn", "title": "Đối tượng, chức năng, nhiệm vụ, nội dung và phương pháp nghiên cứu, học tập Lịch sử Đảng Cộng sản Việt Nam", "period": "Nền tảng học tập", "startPage": 11, "endPage": 34, "summary": "Hiểu cách nghiên cứu lịch sử trước khi ghi nhớ các sự kiện. Chương nhập môn trình bày đối tượng, chức năng, nhiệm vụ, phương pháp và yêu cầu học tập.", "sections": [{"id": "nm-doi-tuong", "title": "Đối tượng nghiên cứu", "pages": [13, 17], "summary": "Nghiên cứu sự ra đời, phát triển và hoạt động lãnh đạo của Đảng trong các thời kỳ lịch sử.", "points": ["Sự kiện lịch sử gắn với hoạt động lãnh đạo của Đảng.", "Cương lĩnh, đường lối và quá trình tổ chức thực hiện.", "Công tác xây dựng Đảng về chính trị, tư tưởng, tổ chức và đạo đức."]}, {"id": "nm-chuc-nang", "title": "Chức năng và nhiệm vụ", "pages": [17, 24], "summary": "Nhận thức, giáo dục, dự báo và phê phán gắn với nghiên cứu, tổng kết lịch sử.", "points": ["Nhận thức có hệ thống về sự lãnh đạo và cầm quyền của Đảng.", "Giáo dục truyền thống, tinh thần yêu nước và lý tưởng cách mạng.", "Tổng kết kinh nghiệm, nhận thức quy luật và làm rõ đường lối."]}, {"id": "nm-phuong-phap", "title": "Phương pháp nghiên cứu, học tập", "pages": [24, 29], "summary": "Kết hợp phương pháp lịch sử với phương pháp logic trên cơ sở phương pháp luận khoa học.", "points": ["Lịch sử: tái hiện tiến trình cụ thể, không gian, thời gian, con người.", "Logic: khái quát bản chất, quy luật và khuynh hướng chung.", "Gắn lý luận với thực tiễn; không dừng ở học thuộc mốc thời gian."]}, {"id": "nm-muc-dich", "title": "Mục đích và yêu cầu", "pages": [29, 34], "summary": "Nắm vững tri thức, bản chất và kinh nghiệm lịch sử; thống nhất tính khoa học và tính đảng.", "points": ["Tôn trọng hiện thực lịch sử, tư liệu chính xác và luận cứ khoa học.", "Hiểu ba thời kỳ lớn của lịch sử Đảng trong cấu trúc học phần.", "Vận dụng bài học lịch sử thay vì chỉ ghi nhớ sự kiện."]}], "questions": [{"id": "nm-q001", "section": "nm-doi-tuong", "prompt": "Đối tượng nghiên cứu của khoa học Lịch sử Đảng là gì?", "options": ["Chỉ tiểu sử các cá nhân lãnh đạo", "Chỉ diễn biến các trận đánh", "Chỉ lịch sử kinh tế thế giới", "Sự ra đời, phát triển và hoạt động lãnh đạo của Đảng qua các thời kỳ"], "answer": 3, "explanation": "Sự ra đời, phát triển và hoạt động lãnh đạo của Đảng qua các thời kỳ. Nội dung được trình bày trong chương nhập môn, trang 13.", "page": 13, "evidence": "Đối tượng nghiên cứu của khoa học Lịch sử Đảng là sự ra đời, phát triển và hoạt động lãnh đạo của Đảng qua các thời kỳ lịch sử.", "type": "mcq"}, {"id": "nm-q002", "section": "nm-doi-tuong", "prompt": "Sự kiện lịch sử cần được tái hiện trên cơ sở tư liệu như thế nào?", "options": ["Dựa vào lời truyền miệng chưa kiểm chứng", "Thay tư liệu bằng suy đoán", "Chính xác, trung thực, khách quan", "Chỉ chọn chi tiết thuận lợi"], "answer": 2, "explanation": "Chính xác, trung thực, khách quan. Nội dung được trình bày trong chương nhập môn, trang 14.", "page": 14, "evidence": "Các sự kiện phái được tái hiện trên cơ sở tư liệu lịch sử chính xác, trung thực, khách quan.", "type": "mcq"}, {"id": "nm-q003", "section": "nm-doi-tuong", "prompt": "Xây dựng Đảng về tư tưởng nhằm bảo đảm nền tảng nào?", "options": ["Một hệ thống tín ngưỡng duy nhất", "Chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh", "Chỉ kinh nghiệm cá nhân", "Chỉ các quy định về ngân sách"], "answer": 1, "explanation": "Chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh. Nội dung được trình bày trong chương nhập môn, trang 17.", "page": 17, "evidence": "Xây dựng Đảng về tư tưởng để bảo đắm Đảng lấy chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh làm nền tảng tư tưởng", "type": "mcq"}, {"id": "nm-q004", "section": "nm-doi-tuong", "prompt": "Các mặt xây dựng Đảng được nêu trong chương nhập môn là gì?", "options": ["Chính trị, tư tưởng, tổ chức và đạo đức", "Chỉ quân sự và ngoại giao", "Chỉ tổ chức và tài chính", "Kinh tế, thể thao và nghệ thuật"], "answer": 0, "explanation": "Chính trị, tư tưởng, tổ chức và đạo đức. Nội dung được trình bày trong chương nhập môn, trang 17.", "page": 17, "evidence": "công tác xây dựng Đảng trong các thời kỳ lịch sử về chính trị, tư tưởng, tổ chức và đạo đức.", "type": "mcq"}, {"id": "nm-q005", "section": "nm-chuc-nang", "prompt": "Quy luật ra đời và phát triển của Đảng được giáo trình trình bày là sự kết hợp nào?", "options": ["Chỉ phong trào công nhân với phong trào nông dân", "Chỉ phong trào yêu nước với cải cách hành chính", "Phong trào công nhân với chủ nghĩa thực dân", "Chủ nghĩa Mác - Lênin với phong trào công nhân và phong trào yêu nước Việt Nam"], "answer": 3, "explanation": "Chủ nghĩa Mác - Lênin với phong trào công nhân và phong trào yêu nước Việt Nam. Nội dung được trình bày trong chương nhập môn, trang 18.", "page": 18, "evidence": "sự kết hợp chủ nghĩa Mác - Lênin với phong trào công nhân và phong trào yêu nước Việt Nam.", "type": "mcq"}, {"id": "nm-q006", "section": "nm-chuc-nang", "prompt": "Theo giáo trình, Đảng trở thành Đảng cầm quyền từ sự kiện nào?", "options": ["Phong trào dân chủ 1936–1939", "Đại hội VI năm 1986", "Cách mạng Tháng Tám năm 1945", "Hội nghị thành lập Đảng năm 1930"], "answer": 2, "explanation": "Cách mạng Tháng Tám năm 1945. Nội dung được trình bày trong chương nhập môn, trang 18.", "page": 18, "evidence": "Từ Cách mạng Tháng Tám năm 1945, Đảng trở thành Đảng cầm quyền", "type": "mcq"}, {"id": "nm-q007", "section": "nm-chuc-nang", "prompt": "Nội dung nào thuộc chức năng giáo dục của khoa học Lịch sử Đảng?", "options": ["Chỉ mô tả niên đại mà không rút ý nghĩa", "Giáo dục tinh thần yêu nước, ý thức và niềm tự hào dân tộc", "Chỉ lập bảng thống kê số liệu", "Thay thế mọi môn khoa học xã hội"], "answer": 1, "explanation": "Giáo dục tinh thần yêu nước, ý thức và niềm tự hào dân tộc. Nội dung được trình bày trong chương nhập môn, trang 19.", "page": 19, "evidence": "giáo dục sâu sắc tỉnh thần yêu nước, ý thức, niềm tự hào, tự tôn, ý chí tự lực, tự cường dân tộc.", "type": "mcq"}, {"id": "nm-q008", "section": "nm-chuc-nang", "prompt": "Ngoài nhận thức và giáo dục, khoa học Lịch sử Đảng còn có chức năng nào?", "options": ["Dự báo và phê phán", "Dự toán và kiểm toán", "Điều tra dân số và đo đạc", "Tổ chức sản xuất và phân phối"], "answer": 0, "explanation": "Dự báo và phê phán. Nội dung được trình bày trong chương nhập môn, trang 20.", "page": 20, "evidence": "khoa học lịch sử Đảng còn có chức năng dự báo và phê phán.", "type": "mcq"}, {"id": "nm-q009", "section": "nm-chuc-nang", "prompt": "Chức năng dự báo bắt đầu từ cơ sở nào?", "options": ["Bỏ qua toàn bộ kinh nghiệm lịch sử", "Chỉ dựa vào suy đoán cá nhân", "Tách hiện tại khỏi quá khứ", "Nhận thức quá khứ để hiểu hiện tại và dự báo tương lai"], "answer": 3, "explanation": "Nhận thức quá khứ để hiểu hiện tại và dự báo tương lai. Nội dung được trình bày trong chương nhập môn, trang 20.", "page": 20, "evidence": "Từ nhận thức những gì đã diễn ra trong quá khứ để hiểu rõ hiện tại và dự báo tương lai", "type": "mcq"}, {"id": "nm-q010", "section": "nm-chuc-nang", "prompt": "Theo giáo trình, tự phê bình và phê bình được xác định như thế nào?", "options": ["Là hoạt động không liên quan đến xây dựng Đảng", "Là sự thay thế cho nghiên cứu lịch sử", "Là quy luật phát triển của Đảng", "Là việc chỉ thực hiện khi thành lập Đảng"], "answer": 2, "explanation": "Là quy luật phát triển của Đảng. Nội dung được trình bày trong chương nhập môn, trang 20.", "page": 20, "evidence": "tự phê bình và phê bình là quy luật phát triển của Đảng.", "type": "mcq"}, {"id": "nm-q011", "section": "nm-phuong-phap", "prompt": "Cơ sở phương pháp luận được nhấn mạnh khi nghiên cứu lịch sử Đảng là gì?", "options": ["Chỉ trực giác và cảm xúc", "Chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật lịch sử", "Chủ nghĩa kinh nghiệm thuần túy", "Chỉ phương pháp thực nghiệm vật lý"], "answer": 1, "explanation": "Chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật lịch sử. Nội dung được trình bày trong chương nhập môn, trang 24.", "page": 24, "evidence": "nắm vững chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật lịch sử", "type": "mcq"}, {"id": "nm-q012", "section": "nm-phuong-phap", "prompt": "Theo phương pháp luận được nêu, tiêu chuẩn của chân lý là gì?", "options": ["Thực tiễn và kết quả của hoạt động thực tiễn", "Số người lặp lại một ý kiến", "Uy tín cá nhân thay cho bằng chứng", "Mức độ dễ ghi nhớ của câu chuyện"], "answer": 0, "explanation": "Thực tiễn và kết quả của hoạt động thực tiễn. Nội dung được trình bày trong chương nhập môn, trang 24.", "page": 24, "evidence": "coi thực tiễn và kết quả của hoạt động thực tiễn là tiêu chuẩn của chân lý.", "type": "mcq"}, {"id": "nm-q013", "section": "nm-phuong-phap", "prompt": "Hai phương pháp cơ bản được sử dụng trong nghiên cứu Lịch sử Đảng là gì?", "options": ["Chỉ phương pháp thống kê và điều tra", "Chỉ phương pháp mô phỏng và dự đoán", "Phương pháp thực nghiệm và giải tích", "Phương pháp lịch sử và phương pháp logic"], "answer": 3, "explanation": "Phương pháp lịch sử và phương pháp logic. Nội dung được trình bày trong chương nhập môn, trang 25.", "page": 25, "evidence": "hai phương pháp cơ bản: phương pháp lịch sử và phương pháp logic", "type": "mcq"}, {"id": "nm-q014", "section": "nm-phuong-phap", "prompt": "Phương pháp lịch sử chú trọng điều gì khi tái hiện tiến trình?", "options": ["Chỉ chọn các hiện tượng lặp lại", "Tách sự kiện khỏi không gian và thời gian", "Tính cụ thể, sống động và những bước quanh co của lịch sử", "Xóa bỏ mọi chi tiết cụ thể"], "answer": 2, "explanation": "Tính cụ thể, sống động và những bước quanh co của lịch sử. Nội dung được trình bày trong chương nhập môn, trang 26.", "page": 26, "evidence": "đầy đủ tính cụ thể, sống động, quanh co của chúng.", "type": "mcq"}, {"id": "nm-q015", "section": "nm-phuong-phap", "prompt": "Theo giáo trình, học theo phương pháp lịch sử có đồng nghĩa chỉ học thuộc sự kiện không?", "options": ["Có; phải bỏ qua mối quan hệ giữa các sự kiện", "Không; cần hiểu tính chất, bản chất và kết hợp phương pháp logic", "Có; chỉ cần thuộc niên đại", "Có; không cần phân tích sự kiện"], "answer": 1, "explanation": "Không; cần hiểu tính chất, bản chất và kết hợp phương pháp logic. Nội dung được trình bày trong chương nhập môn, trang 26.", "page": 26, "evidence": "Phương pháp lịch sử không có nghĩa là học thuộc lòng sự kiện, điễn biến lịch sử mà phải hiểu tính chất, bản chất của sự kiện, hiện tượng, do đó không tách rời phương pháp logic.", "type": "mcq"}, {"id": "nm-q016", "section": "nm-phuong-phap", "prompt": "Mục đích nổi bật của phương pháp logic là gì?", "options": ["Vạch ra bản chất, quy luật và khuynh hướng chung", "Chỉ kể lại từng chi tiết riêng lẻ", "Bỏ qua mọi quy luật vận động", "Thay thế tư liệu bằng các giả định"], "answer": 0, "explanation": "Vạch ra bản chất, quy luật và khuynh hướng chung. Nội dung được trình bày trong chương nhập môn, trang 27.", "page": 27, "evidence": "vạch ra bản chất, quy luật, khuynh hướng chung", "type": "mcq"}, {"id": "nm-q017", "section": "nm-phuong-phap", "prompt": "Quan hệ giữa phương pháp lịch sử và phương pháp logic được xác định như thế nào?", "options": ["Đối lập hoàn toàn với nhau", "Chỉ dùng một phương pháp, loại bỏ phương pháp còn lại", "Không có liên hệ trong nghiên cứu", "Có quan hệ mật thiết, không tách rời nhau"], "answer": 3, "explanation": "Có quan hệ mật thiết, không tách rời nhau. Nội dung được trình bày trong chương nhập môn, trang 27.", "page": 27, "evidence": "Phương pháp lịch sử và phương pháp logic có quan hệ mật thiết với nhau", "type": "mcq"}, {"id": "nm-q018", "section": "nm-phuong-phap", "prompt": "Việc vận dụng lý luận vào thực tiễn khi học Lịch sử Đảng đòi hỏi điều gì?", "options": ["Chỉ học các khái niệm trừu tượng", "Không cần nghiên cứu tư tưởng Hồ Chí Minh", "Luôn liên hệ lý luận với thực tiễn Việt Nam", "Tách lý luận khỏi các sự kiện"], "answer": 2, "explanation": "Luôn liên hệ lý luận với thực tiễn Việt Nam. Nội dung được trình bày trong chương nhập môn, trang 29.", "page": 29, "evidence": "luôn luôn liên hệ lý luận với thực tiễn Việt Nam", "type": "mcq"}, {"id": "nm-q019", "section": "nm-muc-dich", "prompt": "Tính khoa học trong nghiên cứu lịch sử đòi hỏi yêu cầu nào?", "options": ["Ưu tiên câu chuyện hấp dẫn hơn tư liệu", "Khách quan, trung thực và dựa trên luận cứ khoa học", "Bỏ qua hiện thực lịch sử", "Chỉ đưa ra nhận định không có bằng chứng"], "answer": 1, "explanation": "Khách quan, trung thực và dựa trên luận cứ khoa học. Nội dung được trình bày trong chương nhập môn, trang 29.", "page": 29, "evidence": "khách quan, trung thực với những đánh giá, kết hợp dựa trên luận cứ khoa học, tôn trọng hiện thực lịch sử.", "type": "mcq"}, {"id": "nm-q020", "section": "nm-muc-dich", "prompt": "Theo giáo trình, tính khoa học và tính đảng có quan hệ ra sao?", "options": ["Thống nhất với nhau", "Loại trừ nhau hoàn toàn", "Chỉ tồn tại riêng rẽ", "Không liên quan đến mục tiêu nghiên cứu"], "answer": 0, "explanation": "Thống nhất với nhau. Nội dung được trình bày trong chương nhập môn, trang 30.", "page": 30, "evidence": "Tính khoa học và tính đẳng là thống nhất", "type": "mcq"}], "mindmap": {"title": "Phương pháp học Lịch sử Đảng", "branches": [{"id": "nm-doi-tuong", "title": "Đối tượng nghiên cứu", "page": 13, "summary": "Nghiên cứu sự ra đời, phát triển và hoạt động lãnh đạo của Đảng trong các thời kỳ lịch sử.", "children": [{"title": "Sự kiện lịch sử gắn với hoạt động lãnh đạo của Đảng.", "page": 13, "note": "Sự kiện lịch sử gắn với hoạt động lãnh đạo của Đảng."}, {"title": "Cương lĩnh, đường lối và quá trình tổ chức thực hiện.", "page": 14, "note": "Cương lĩnh, đường lối và quá trình tổ chức thực hiện."}, {"title": "Công tác xây dựng Đảng về chính trị, tư tưởng, tổ chức và đạo đức.", "page": 17, "note": "Công tác xây dựng Đảng về chính trị, tư tưởng, tổ chức và đạo đức."}]}, {"id": "nm-chuc-nang", "title": "Chức năng và nhiệm vụ", "page": 17, "summary": "Nhận thức, giáo dục, dự báo và phê phán gắn với nghiên cứu, tổng kết lịch sử.", "children": [{"title": "Nhận thức có hệ thống về sự lãnh đạo và cầm quyền của Đảng.", "page": 18, "note": "Nhận thức có hệ thống về sự lãnh đạo và cầm quyền của Đảng."}, {"title": "Giáo dục truyền thống, tinh thần yêu nước và lý tưởng cách mạng.", "page": 19, "note": "Giáo dục truyền thống, tinh thần yêu nước và lý tưởng cách mạng."}, {"title": "Tổng kết kinh nghiệm, nhận thức quy luật và làm rõ đường lối.", "page": 22, "note": "Tổng kết kinh nghiệm, nhận thức quy luật và làm rõ đường lối."}]}, {"id": "nm-phuong-phap", "title": "Phương pháp nghiên cứu, học tập", "page": 24, "summary": "Kết hợp phương pháp lịch sử với phương pháp logic trên cơ sở phương pháp luận khoa học.", "children": [{"title": "Lịch sử", "page": 26, "note": "Lịch sử: tái hiện tiến trình cụ thể, không gian, thời gian, con người."}, {"title": "Logic", "page": 27, "note": "Logic: khái quát bản chất, quy luật và khuynh hướng chung."}, {"title": "Gắn lý luận với thực tiễn; không dừng ở học thuộc mốc thời gian.", "page": 29, "note": "Gắn lý luận với thực tiễn; không dừng ở học thuộc mốc thời gian."}]}, {"id": "nm-muc-dich", "title": "Mục đích và yêu cầu", "page": 29, "summary": "Nắm vững tri thức, bản chất và kinh nghiệm lịch sử; thống nhất tính khoa học và tính đảng.", "children": [{"title": "Tôn trọng hiện thực lịch sử, tư liệu chính xác và luận cứ khoa học.", "page": 29, "note": "Tôn trọng hiện thực lịch sử, tư liệu chính xác và luận cứ khoa học."}, {"title": "Hiểu ba thời kỳ lớn của lịch sử Đảng trong cấu trúc học phần.", "page": 30, "note": "Hiểu ba thời kỳ lớn của lịch sử Đảng trong cấu trúc học phần."}, {"title": "Vận dụng bài học lịch sử thay vì chỉ ghi nhớ sự kiện.", "page": 33, "note": "Vận dụng bài học lịch sử thay vì chỉ ghi nhớ sự kiện."}]}]}, "timeline": [], "reviewPrompts": []}, {"id": "c1", "label": "Chương 1", "title": "Đảng Cộng sản Việt Nam ra đời và lãnh đạo đấu tranh giành chính quyền", "period": "1930–1945", "startPage": 35, "endPage": 126, "summary": "Từ bối cảnh thuộc địa và quá trình Nguyễn Ái Quốc tìm đường cứu nước đến sự thành lập Đảng và Cương lĩnh đầu tiên. Ba cao trào cách mạng, quá trình chuẩn bị lực lượng và chớp thời cơ dẫn tới Cách mạng Tháng Tám, thành lập nước Việt Nam Dân chủ Cộng hòa.", "sections": [{"id": "context", "title": "Bối cảnh lịch sử và các phong trào yêu nước", "pages": [36, 49], "summary": "Chế độ thuộc địa làm biến đổi xã hội Việt Nam và đặt ra yêu cầu tìm một con đường cứu nước mới.", "points": ["Cách mạng Tháng Mười Nga và Quốc tế Cộng sản tác động đến phong trào giải phóng dân tộc.", "Chính sách thống trị, khai thác thuộc địa làm xã hội phân hóa và mâu thuẫn dân tộc gay gắt.", "Các phong trào phong kiến, dân chủ tư sản thất bại; yêu cầu về đường lối và tổ chức tiên phong trở nên cấp thiết."]}, {"id": "preparation", "title": "Nguyễn Ái Quốc chuẩn bị điều kiện thành lập Đảng", "pages": [49, 58], "summary": "Tìm đường cứu nước, lựa chọn cách mạng vô sản và chuẩn bị về tư tưởng, chính trị, tổ chức.", "points": ["Năm 1911 ra đi tìm đường cứu nước; năm 1920 tiếp cận Luận cương của Lênin và trở thành người cộng sản.", "Truyền bá chủ nghĩa Mác–Lênin, xác lập đường lối giải phóng dân tộc và vai trò tổ chức của Đảng.", "Hội Việt Nam Cách mạng Thanh niên, báo Thanh niên và các lớp huấn luyện tạo nền tảng cán bộ, tổ chức.", "Đường cách mệnh trình bày con đường, mục tiêu, lực lượng và phương pháp đấu tranh cách mạng."]}, {"id": "foundation", "title": "Các tổ chức cộng sản và Hội nghị thành lập Đảng", "pages": [58, 64], "summary": "Ba tổ chức cộng sản ra đời năm 1929 tạo tiền đề đồng thời đặt ra yêu cầu hợp nhất.", "points": ["Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng ra đời, thúc đẩy phong trào cách mạng.", "Đông Dương Cộng sản Liên đoàn hình thành từ bộ phận tiên tiến của Tân Việt Cách mạng Đảng.", "Nguyễn Ái Quốc triệu tập hội nghị hợp nhất tại Cửu Long, Hồng Kông.", "Hội nghị thống nhất tên Đảng Cộng sản Việt Nam, thông qua các văn kiện nền tảng."]}, {"id": "programme", "title": "Cương lĩnh đầu tiên và ý nghĩa thành lập Đảng", "pages": [64, 71], "summary": "Cương lĩnh xác lập đường lối giải phóng dân tộc, hướng tới xã hội cộng sản và đoàn kết lực lượng yêu nước.", "points": ["Kết hợp chống đế quốc và chống phong kiến, đặt độc lập dân tộc ở vị trí hàng đầu.", "Lực lượng cơ bản là công–nông, đồng thời đoàn kết những giai tầng tiến bộ, yêu nước.", "Gắn cách mạng Việt Nam với cách mạng thế giới, khẳng định vai trò lãnh đạo của Đảng.", "Đảng ra đời là sự kết hợp chủ nghĩa Mác–Lênin, phong trào công nhân và phong trào yêu nước."]}, {"id": "revolution1930", "title": "Phong trào 1930–1931 và Luận cương tháng 10/1930", "pages": [71, 78], "summary": "Cao trào 1930–1931 kiểm nghiệm vai trò lãnh đạo; Luận cương nêu chiến lược cách mạng và bộc lộ hạn chế cần khắc phục.", "points": ["Đỉnh cao là Xôviết Nghệ–Tĩnh, hình thức chính quyền cách mạng ở một số địa phương.", "Phong trào rèn luyện lực lượng và kiểm nghiệm vai trò lãnh đạo của Đảng.", "Hội nghị tháng 10/1930 đổi tên Đảng, bầu Trần Phú làm Tổng Bí thư, thông qua Luận cương.", "Luận cương chưa nhấn mạnh đúng mức nhiệm vụ dân tộc và chưa đề ra liên minh dân tộc rộng rãi."]}, {"id": "recovery", "title": "Khôi phục tổ chức và Đại hội I", "pages": [78, 83], "summary": "Trong khủng bố, đảng viên và quần chúng duy trì đấu tranh, khôi phục cơ sở và hệ thống lãnh đạo.", "points": ["Các chi bộ trong tù tổ chức đấu tranh, huấn luyện và giữ vững lực lượng.", "Chương trình hành động năm 1932 vạch nhiệm vụ khôi phục tổ chức và phong trào.", "Ban Chỉ huy ở ngoài thành lập năm 1934; hệ thống tổ chức phục hồi đầu năm 1935.", "Đại hội I tháng 3/1935 tại Ma Cao đề ra nhiệm vụ củng cố Đảng, vận động quần chúng, chống đế quốc và chiến tranh."]}, {"id": "democracy", "title": "Phong trào dân chủ 1936–1939", "pages": [83, 91], "summary": "Điều chỉnh nhiệm vụ trước mắt và hình thức đấu tranh, vận động rộng rãi vì tự do, dân chủ, cơm áo, hòa bình.", "points": ["Bối cảnh chống phátxít đặt ra nhiệm vụ tập hợp mặt trận nhân dân rộng rãi.", "Kết hợp công khai, hợp pháp, nửa hợp pháp với bí mật, bất hợp pháp.", "Mặt trận Dân chủ Đông Dương tập hợp lực lượng; báo chí, vận động nghị trường và truyền bá quốc ngữ phát triển.", "Phong trào mở rộng lực lượng, tích lũy kinh nghiệm cho Cách mạng Tháng Tám."]}, {"id": "liberation", "title": "Chuyển hướng chiến lược 1939–1941", "pages": [92, 98], "summary": "Chiến tranh thế giới và ách thống trị Pháp–Nhật đặt nhiệm vụ giải phóng dân tộc lên hàng đầu.", "points": ["Hội nghị tháng 11/1939 mở đầu chuyển hướng chiến lược, lấy quyền lợi dân tộc làm tối cao.", "Nguyễn Ái Quốc về nước ngày 28/1/1941, chủ trì Hội nghị Trung ương 8 tháng 5/1941.", "Hội nghị hoàn chỉnh chuyển hướng: giải phóng dân tộc, tạm gác cách mạng ruộng đất, quyền dân tộc tự quyết.", "Chuẩn bị khởi nghĩa vũ trang là nhiệm vụ trung tâm; Việt Minh tập hợp rộng rãi lực lượng cứu quốc."]}, {"id": "preinsurrection", "title": "Chuẩn bị lực lượng chính trị, vũ trang và căn cứ", "pages": [98, 104], "summary": "Đấu tranh chống Pháp–Nhật gắn với xây dựng lực lượng và căn cứ để tiến tới khởi nghĩa.", "points": ["Khởi nghĩa Bắc Sơn, Nam Kỳ và binh biến Đô Lương báo hiệu bước phát triển đấu tranh vũ trang.", "Việt Minh và các đoàn thể cứu quốc xây dựng lực lượng chính trị rộng lớn.", "Đề cương về văn hóa năm 1943 nêu ba nguyên tắc dân tộc, khoa học, đại chúng.", "Đội Việt Nam tuyên truyền giải phóng quân ra đời ngày 22/12/1944 ở Cao Bằng."]}, {"id": "antijapan", "title": "Cao trào kháng Nhật cứu nước", "pages": [104, 109], "summary": "Sau đảo chính Nhật–Pháp, cao trào phát triển thành khởi nghĩa từng phần, chuẩn bị trực tiếp cho tổng khởi nghĩa.", "points": ["Nhật đảo chính Pháp ngày 9/3/1945, độc chiếm Đông Dương.", "Chỉ thị ngày 12/3 xác định Nhật là kẻ thù trước mắt, phát động cao trào kháng Nhật cứu nước.", "Khẩu hiệu phá kho thóc, giải quyết nạn đói góp phần huy động đông đảo quần chúng.", "Khu giải phóng Việt Bắc hình thành ngày 4/6/1945, trở thành căn cứ địa chính của cả nước."]}, {"id": "august", "title": "Tổng khởi nghĩa và thành lập nhà nước mới", "pages": [109, 118], "summary": "Chớp thời cơ khi Nhật đầu hàng, giành chính quyền trước khi quân Đồng minh vào Đông Dương.", "points": ["Quân lệnh số 1 ngày 13/8/1945 phát lệnh tổng khởi nghĩa.", "Đại hội quốc dân Tân Trào tán thành tổng khởi nghĩa, lập Ủy ban giải phóng dân tộc.", "Thắng lợi ở Hà Nội, Huế, Sài Gòn có ý nghĩa quyết định đối với cả nước.", "Ngày 2/9/1945, Tuyên ngôn độc lập công bố sự ra đời của nước Việt Nam Dân chủ Cộng hòa."]}, {"id": "meaning", "title": "Tính chất, ý nghĩa và bài học Cách mạng Tháng Tám", "pages": [119, 125], "summary": "Cách mạng giải phóng dân tộc mang tính dân chủ mới, mở ra kỷ nguyên độc lập, tự do và hướng tới chủ nghĩa xã hội.", "points": ["Huy động toàn dân tộc, giải quyết nhiệm vụ hàng đầu là giải phóng dân tộc.", "Chấm dứt ách thuộc địa và chế độ quân chủ; nhân dân trở thành người chủ đất nước.", "Bài học chỉ đạo chiến lược: đặt giải phóng dân tộc lên hàng đầu.", "Đại đoàn kết, kết hợp chính trị với vũ trang, chớp thời cơ và xây dựng Đảng vững mạnh."]}], "questions": [{"id": "c1-q001", "section": "context", "prompt": "Sự kiện nào mở đầu cuộc xâm lược Việt Nam của thực dân Pháp?", "options": ["Hiệp ước Patơnốt được ký năm 1862", "Pháp tấn công Đà Nẵng ngày 1/9/1858", "Pháp tấn công Hà Nội năm 1884", "Nhật tiến vào Đông Dương năm 1940"], "answer": 1, "explanation": "Ngày Pháp nổ súng tấn công Đà Nẵng là thời điểm mở đầu quá trình xâm lược Việt Nam.", "page": 38, "evidence": "điều tra thám sát lâu dài, thâm nhập kiên trì của các giáo sĩ và thương nhân Pháp, ngày 1/9/1858, thực dân Pháp nổ súng tấn công Đà Nẵng, từng bước xâm lược Việt Nam. Đó là thời điểm chế độ phong kiến Việt Nam (đưới triều đại phong kiến nhà Nguyễn) đã lâm vào giai đoạn khủng hoảng trầm trọng. Trước", "type": "mcq"}, {"id": "c1-q002", "section": "context", "prompt": "Mâu thuẫn chủ yếu nhất của xã hội Việt Nam cuối thế kỷ XIX, đầu thế kỷ XX là gì?", "options": ["Tiểu tư sản với tư sản dân tộc", "Địa chủ với tư sản mại bản", "Toàn thể dân tộc Việt Nam với thực dân Pháp và phong kiến phản động", "Công nhân với nông dân"], "answer": 2, "explanation": "Sự thống trị của thực dân làm mâu thuẫn giữa toàn dân tộc với thực dân Pháp và phong kiến phản động trở nên chủ yếu và gay gắt.", "page": 43, "evidence": "giữa toàn thể dân tộc Việt Nam với thực đân Pháp và phong kiến phản động trở thành mâu thuẫn chủ yếu nhất và ngày càng gay gắt. Trong bối cảnh đó, những luồng tư tưởng ở bên ngoài như: tư tưởng Cách mạng tư sản Pháp 1789, phong trào Duy Tân Nhật Bản năm 1868, cuộc vận động Duy Tân tại Trung Quốc năm 1898,", "type": "mcq"}, {"id": "c1-q003", "section": "context", "prompt": "Một nguyên nhân căn bản khiến các phong trào yêu nước trước khi có Đảng thất bại là gì?", "options": ["Nhân dân hoàn toàn không có tinh thần yêu nước", "Không tồn tại mâu thuẫn dân tộc", "Mọi phong trào đều chỉ hoạt động ở nước ngoài", "Thiếu đường lối chính trị đúng đắn và tổ chức lãnh đạo vững mạnh"], "answer": 3, "explanation": "Giáo trình nhấn mạnh hạn chế về đường lối, tổ chức tập hợp và phương pháp đấu tranh; không phủ nhận tinh thần yêu nước của nhân dân.", "page": 49, "evidence": "lịch sử đều lần lượt thất bại”). Nguyên nhân thất bại của các phong trào đó là do thiếu đường lối chính trị đúng đắn để giải quyết triệt để những mâu thuẫn eơ bản, chủ yếu của xã hội, chưa có một tổ chức vững mạnh để tập hợp, giác ngộ và lãnh đạo toàn dân tộc, chưa xác định được phương pháp đấu tranh thích hợp để đánh", "type": "mcq"}, {"id": "c1-q004", "section": "preparation", "prompt": "Nguyễn Tất Thành quyết định ra đi tìm đường cứu nước vào năm nào?", "options": ["1911", "1917", "1920", "1925"], "answer": 0, "explanation": "Theo giáo trình, đáp án là: 1911.", "page": 50, "evidence": "nước đương thời, năm 1911, Nguyễn Tất Thành quyết định ra đi tìm đường cứu nước, giải phóng dân tộc. Qua trải nghiệm thực tế nhiều nước, Người đã nhận thức được một cách rạch ròi: “dù màu da có khác nhau, trên đời này chỉ có hai", "type": "mcq"}, {"id": "c1-q005", "section": "preparation", "prompt": "Bản Yêu sách của nhân dân An Nam được gửi tới Hội nghị Vécxây khi nào?", "options": ["28/1/1941", "18/6/1919", "21/6/1925", "3/2/1930"], "answer": 1, "explanation": "Theo giáo trình, đáp án là: 18/6/1919.", "page": 50, "evidence": "sách của nhân dân An Nam (gồm tám điểm đòi quyền tự do cho nhân dân Việt Nam) ngày 18/6/1919. Những người Việt Nam tiêu biểu cho tỉnh thần yêu nước ở Pháp, gồm: Phan Châu Trinh, Nguyễn An Ninh, 1. Hồ Chí Minh: Toàn tập, Sđd, L1, tư,287. 50", "type": "mcq"}, {"id": "c1-q006", "section": "preparation", "prompt": "Tài liệu nào giúp Nguyễn Ái Quốc tìm thấy hướng giải quyết cơ bản cho sự nghiệp cứu nước vào tháng 7/1920?", "options": ["Đề cương về văn hóa Việt Nam năm 1943", "Chương trình hành động của Đảng năm 1932", "Luận cương của Lênin về vấn đề dân tộc và vấn đề thuộc địa", "Luận cương chính trị tháng 10/1930"], "answer": 2, "explanation": "Nguyễn Ái Quốc đọc Luận cương của Lênin trên báo Nhân đạo và tìm thấy chỉ dẫn cho con đường giải phóng dân tộc.", "page": 51, "evidence": "luận quốc tế và Nguyễn Ái Quốc càng hiểu rõ hơn bản chất của đế quốc, thực dân. Tháng 7/1920, Người đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của V.I Lênin đăng trên báo .'Humanité (Nhân đạo), số ra ngày 16 và 17/7/1920. Những luận điểm của V.I. Lênin", "type": "mcq"}, {"id": "c1-q007", "section": "preparation", "prompt": "Sự kiện tại Đại hội Tua tháng 12/1920 đánh dấu chuyển biến nào của Nguyễn Ái Quốc?", "options": ["Thành lập ngay Đảng Cộng sản Việt Nam", "Lập Mặt trận Việt Minh", "Trở thành Tổng Bí thư Đảng Cộng sản Đông Dương", "Trở thành người cộng sản và tham gia sáng lập Đảng Cộng sản Pháp"], "answer": 3, "explanation": "Tán thành Quốc tế Cộng sản và tham gia sáng lập Đảng Cộng sản Pháp đánh dấu bước chuyển biến quyết định về tư tưởng và lập trường chính trị.", "page": 51, "evidence": "Nguyễn Ái Quốc trở thành một trong những người sáng lập Đảng Cộng sản Pháp và là người cộng sản đầu tiên của Việt Nam, đánh dấu bước chuyển biến quyết định trong tư tưởng và lập trường chính trị của Nguyễn Ái Quốc. Trong 51", "type": "mcq"}, {"id": "c1-q008", "section": "preparation", "prompt": "Nguyễn Ái Quốc chuẩn bị những điều kiện cơ bản nào cho sự ra đời của Đảng?", "options": ["Tư tưởng, chính trị và tổ chức", "Chỉ về tài chính", "Chỉ về vũ khí", "Chỉ về quan hệ ngoại giao"], "answer": 0, "explanation": "Ba mặt chuẩn bị gắn với truyền bá chủ nghĩa Mác–Lênin, xác lập đường lối giải phóng dân tộc và tổ chức lực lượng.", "page": 52, "evidence": "cách mạng vô sản, đồng thời tích cực truyền bá chủ nghĩa Mác - Lênin về Việt Nam. - Chuẩn bị về tư tưởng, chính trị và tổ chức cho sự ra đời của Đảng: Về tư tưởng: Từ giữa năm 1921, tại Pháp, cùng một số nhà cách mạng của các nước thuộc địa khác, Nguyễn Ái Quốc tham gia thành lập Hội Liên hiệp thuộc địa, sau đó sáng lập tờ báo", "type": "mcq"}, {"id": "c1-q009", "section": "preparation", "prompt": "Hội Việt Nam Cách mạng Thanh niên được thành lập ở đâu, khi nào?", "options": ["Cao Bằng, tháng 5/1941", "Quảng Châu, tháng 6/1925", "Hà Nội, tháng 3/1929", "Hồng Kông, tháng 2/1930"], "answer": 1, "explanation": "Theo giáo trình, đáp án là: Quảng Châu, tháng 6/1925.", "page": 55, "evidence": "lựa chọn một số thanh niên tích cực trong Tâm tâm xã, lập ra nhóm Cộng sản đoàn. Tháng 6/1925, Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu (Trung Quốc), 1. Hồ Chí Minh: Toàn tập, Sđd, t2, tr.289. 9. Hồ Chí Minh: Toàn tập, Sđd, t1, tr.209, 55", "type": "mcq"}, {"id": "c1-q010", "section": "preparation", "prompt": "Số đầu tiên của báo Thanh niên ra ngày nào?", "options": ["17/6/1929", "12/3/1945", "21/6/1925", "18/6/1919"], "answer": 2, "explanation": "Theo giáo trình, đáp án là: 21/6/1925.", "page": 56, "evidence": "tộc Việt Nam. Báo in bằng tiếng Việt và ra hằng tuần, mỗi số in khoảng 100 bản. Ngày 21/6/1925 ra số đầu tiên, đến tháng 4/1927, báo ra được 88 số. Sau khi Nguyễn Ái Quốc rời Quảng Châu (4/1927) đi Liên Xô, những đồng chí khác trong Tổng bộ vẫn tiếp tục việc xuất bản và hoạt động cho đến tháng 2/1930 với 202", "type": "mcq"}, {"id": "c1-q011", "section": "preparation", "prompt": "Cuốn Đường cách mệnh được hình thành chủ yếu từ nguồn nào?", "options": ["Biên bản Đại hội Đảng lần I", "Các nghị quyết Hội nghị Trung ương 8", "Báo cáo tổng kết Cách mạng Tháng Tám", "Các bài giảng của Nguyễn Ái Quốc tại lớp huấn luyện ở Quảng Châu"], "answer": 3, "explanation": "Theo giáo trình, đáp án là: Các bài giảng của Nguyễn Ái Quốc tại lớp huấn luyện ở Quảng Châu.", "page": 57, "evidence": "nước châu Âu. Năm 1928, Người trở về châu Á và hoạt động ở Xiêm (tức Thái Lan). Các bài giảng của Nguyễn Ái Quốc trong các lớp đào tạo, bồi dưỡng cho những người Việt Nam yêu nước tại Quảng Châu, được Hội Liên hiệp các dân tộc bị áp bức ở Á Đông xuất bản thành cuốn Đường cách mệnh. Đây là cuốn sách chính trị đầu", "type": "mcq"}, {"id": "c1-q012", "section": "preparation", "prompt": "Vai trò tổ chức nổi bật của Hội Việt Nam Cách mạng Thanh niên là gì?", "options": ["Tổ chức tiền thân của Đảng Cộng sản Việt Nam", "Chính phủ lâm thời sau Cách mạng Tháng Tám", "Tổ chức quân sự thay thế Cứu quốc quân", "Cơ quan hành chính của chính quyền thuộc địa"], "answer": 0, "explanation": "Hội trực tiếp truyền bá chủ nghĩa Mác–Lênin, thúc đẩy phong trào công nhân và chuẩn bị về tổ chức cho sự ra đời của Đảng.", "page": 58, "evidence": "trào yêu nước Việt Nam những năm 1928 - 1929 theo xu hướng cách mạng vô sản. Đồ là tổ chức tiền thân của Đảng Cộng sản Việt Nam. 3. Thành lập Đảng Cộng sản Việt Nam và Cương Hnh chính trị đầu tiên của Đảng a) Các tổ chức cộng sẵn ra đời Với sự nỗ lực truyền bá chủ nghĩa Mác - Lênin vào phong trào công nhân và phong trào yêu nước", "type": "mcq"}, {"id": "c1-q013", "section": "foundation", "prompt": "Đông Dương Cộng sản Đảng được thành lập vào thời điểm nào?", "options": ["11/4/1931", "17/6/1929", "21/6/1925", "3/2/1930"], "answer": 1, "explanation": "Theo giáo trình, đáp án là: 17/6/1929.", "page": 59, "evidence": "nhà 5D, phố Hàm Long, Hà Nội, quyết định lập chỉ bộ cộng sản đầu tiên ở Việt Nam. Ngày 17/6/1929, đại biểu của các tổ chức cộng sản ở Bắc Kỳ họp tại số nhà 312, phố Khâm Thiên (Hà Nội), quyết định thành lập Đông Dương Cộng sản Đảng, thông qua Tuyên ngôn, Điều lệ; lấy cờ đỏ búa liềm là Đảng kỳ và", "type": "mcq"}, {"id": "c1-q014", "section": "foundation", "prompt": "Vì sao sau khi ba tổ chức cộng sản ra đời năm 1929 cần tiến hành hợp nhất?", "options": ["Để duy trì ba hệ thống lãnh đạo riêng biệt", "Để thay thế mục tiêu độc lập bằng cải lương", "Để khắc phục phân tán lực lượng và thiếu thống nhất tổ chức", "Để chấm dứt hoàn toàn phong trào công nhân"], "answer": 2, "explanation": "Sự phát triển của phong trào đòi hỏi một chính đảng thống nhất đủ sức tập hợp và lãnh đạo lực lượng toàn dân tộc.", "page": 60, "evidence": "nhận tổ chức của mình và đều tự nhận là đảng cách mạng chân chính, không tránh khỏi phân tán về lực lượng và thiếu thống nhất về tổ chức trên cả nước. Sự chuyển biến mạnh mẽ các phong trào đấu tranh của các tầng lớp nhân đân ngày càng lên cao, nhu cầu thành lập một chính đẳng cách mạng có đủ khả năng tập 1. Đảng Cộng sản Việt", "type": "mcq"}, {"id": "c1-q015", "section": "foundation", "prompt": "Hội nghị hợp nhất các tổ chức cộng sản đầu năm 1930 được tổ chức ở đâu?", "options": ["Ma Cao", "Tân Trào, Tuyên Quang", "Bà Điểm, Gia Định", "Cửu Long, Hồng Kông"], "answer": 3, "explanation": "Theo giáo trình, đáp án là: Cửu Long, Hồng Kông.", "page": 61, "evidence": "triệu tập đại biểu của Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng đến họp tại Cửu Long (Hồng Kông) để tiến hành hội nghị hợp nhất các tổ chức cộng sản thành một chính đẳng duy nhất của Việt Nam. Hội nghị diễn ra từ ngày 6/1 đến ngày 7/2/19301, Trong Báo cáo gửi Quốc tế Cộng sản, ngày 18/2/1930,", "type": "mcq"}, {"id": "c1-q016", "section": "foundation", "prompt": "Ai chủ trì Hội nghị thành lập Đảng Cộng sản Việt Nam?", "options": ["Nguyễn Ái Quốc", "Trần Phú", "Lê Hồng Phong", "Nguyễn Văn Cừ"], "answer": 0, "explanation": "Theo giáo trình, đáp án là: Nguyễn Ái Quốc.", "page": 62, "evidence": "Cảnh), 2 đại biểu của An Nam Cộng sản Đảng (Châu Văn Liêm và Nguyễn Thiệu), dưới sự chủ trì của lãnh tụ Nguyễn Ái Quốc - đại biểu của Quốc tế Cộng sản. Chương trình nghị sự của Hội nghị: 1. Đại biểu của Quốc tế Cộng sản nói lý do cuộc bội nghị; 2. Thảo luận ý kiến của đại biểu Quốc tế Cộng sản về: a) Việc", "type": "mcq"}, {"id": "c1-q017", "section": "programme", "prompt": "Hai văn kiện nào hợp thành Cương lĩnh chính trị đầu tiên của Đảng?", "options": ["Chỉ thị Sửa soạn khởi nghĩa và Quân lệnh số 1", "Chánh cương vắn tắt và Sách lược vắn tắt", "Luận cương chính trị và Chương trình hành động", "Đề cương văn hóa và Tuyên ngôn độc lập"], "answer": 1, "explanation": "Chánh cương vắn tắt và Sách lược vắn tắt do Nguyễn Ái Quốc soạn thảo được thông qua tại Hội nghị thành lập Đảng.", "page": 64, "evidence": "Quốc soạn thảo, được thông qua tại Hội nghị thành lập Đảng, có hai văn kiện, đó là: Chánh cương vắn tắt của Đảng và Sách lược vắn tắt của Đảng đã phản ánh về đường hướng phát triển và những vấn đề cơ bản về chiến lược và sách lược của cách mạng Việt Nam. Hai văn kiện trên là Cương lĩnh chính trị đầu tiên của Đảng Cộng sản", "type": "mcq"}, {"id": "c1-q018", "section": "programme", "prompt": "Cương lĩnh đầu tiên đặt nhiệm vụ nào ở vị trí hàng đầu?", "options": ["Chỉ đấu tranh nghị trường", "Hoàn thành cách mạng ruộng đất trước mọi nhiệm vụ khác", "Chống đế quốc, giành độc lập dân tộc", "Chỉ tiến hành cải cách giáo dục"], "answer": 2, "explanation": "Cương lĩnh kết hợp chống đế quốc và chống phong kiến; chống đế quốc, giành độc lập được đặt ở vị trí hàng đầu.", "page": 65, "evidence": "bản để giành độc lập cho đân tộc và ruộng đất cho dân cày, trong đó chống đế quốc, giành độc lập cho đân tộc được đặt ở vị trí hàng đầu. Về phương diện xã hội, Cương Hnh xác định rõ: “a) Dân chúng được tự do tổ chức; b) Nam nữ bình quyền, v.v. e) Phổ thông giáo dục theo công nông hoá”. Về phương diện kinh tế, Cương lĩnh xác định: Thủ", "type": "mcq"}, {"id": "c1-q019", "section": "programme", "prompt": "Lực lượng cơ bản của cách mạng được Cương lĩnh đầu tiên xác định như thế nào?", "options": ["Chỉ có địa chủ", "Chỉ có tư sản mại bản", "Chỉ có trí thức ở nước ngoài", "Công nhân và nông dân, trong đó công nhân lãnh đạo"], "answer": 3, "explanation": "Cương lĩnh lấy công–nông làm lực lượng cơ bản, đồng thời đoàn kết các lực lượng tiến bộ, yêu nước khác.", "page": 66, "evidence": "giải phóng cho hai giai cấp công nhân và nông dân. Xác định lực lượng cách mạng: phải đoàn kết công nhân, nông dân - đây là lực lượng cơ bản, trong đó giai cấp công nhân lãnh đạo; đồng thời chủ trương đoàn kết tất cả các giai cấp, các lực lượng tiến bộ, yêu nước để tập trung chống đế quốc và tay sai.", "type": "mcq"}, {"id": "c1-q020", "section": "programme", "prompt": "Cương lĩnh đầu tiên xác định phương pháp giành độc lập theo con đường nào?", "options": ["Bạo lực cách mạng của quần chúng", "Chỉ cầu viện quân đội nước ngoài", "Thỏa hiệp vô điều kiện với thực dân", "Chỉ vận động cải cách trong bộ máy thuộc địa"], "answer": 0, "explanation": "Cương lĩnh khẳng định con đường bạo lực cách mạng của quần chúng và không thỏa hiệp lợi ích công–nông.", "page": 66, "evidence": "tiến hành cách mạng giải phóng dân tộc, Cương lĩnh khẳng định phải bằng con đường bạo lực cách mạng của quần chúng, trong bất cứ hoàn cảnh nào cũng không được thỏa hiệp, “không khi nào nhượng một 1. Đảng Cộng sản Việt Nam: Văn kiện Đảng toàn tập, Sđd, t2, tr.4. 66", "type": "mcq"}, {"id": "c1-q021", "section": "programme", "prompt": "Sự ra đời của Đảng Cộng sản Việt Nam là sự kết hợp những yếu tố nào?", "options": ["Chỉ tư tưởng dân chủ tư sản và phong trào Đông Du", "Chủ nghĩa Mác–Lênin, phong trào công nhân và phong trào yêu nước Việt Nam", "Chỉ phong trào nông dân và tư tưởng phong kiến", "Chỉ phong trào công nhân và viện trợ quốc tế"], "answer": 1, "explanation": "Theo giáo trình, đáp án là: Chủ nghĩa Mác–Lênin, phong trào công nhân và phong trào yêu nước Việt Nam.", "page": 69, "evidence": "phong vì lợi ích của giai cấp và dân tộc. Sự ra đời của Đảng Cộng sản Việt Nam à sản phẩm của sự kết hợp chủ nghĩa Mác - Lênin với phong trào công nhân và phong trào yêu nước Việt Nam. Đó cũng là kết quả của sự phát triển cao và thống nhất của phong trào công nhân và phong trào yêu nước Việt", "type": "mcq"}, {"id": "c1-q022", "section": "revolution1930", "prompt": "Đỉnh cao phong trào cách mạng 1930–1931 gắn với hình thức chính quyền nào?", "options": ["Hội đồng quản hạt Nam Kỳ", "Ủy ban dân tộc giải phóng năm 1945", "Chính quyền Xôviết ở Nghệ An và Hà Tĩnh", "Chính phủ Trần Trọng Kim"], "answer": 2, "explanation": "Ở nhiều địa phương Nghệ An, Hà Tĩnh, tổ chức nông hội quản lý đời sống xã hội, thực hiện chức năng chính quyền cách mạng theo kiểu Xôviết.", "page": 73, "evidence": "Ở vùng nông thôn hai tỉnh Nghệ An và Hà Tĩnh nổ ra nhiều cuộc biểu tình lớn của nông dân. Tháng 9/1930, phong trào cách mạng phái triển đến đỉnh cao với những hình thức đấu tranh ngày càng quyết liệt. Cuộc biểu tình của nông đân Hưng Nguyên, ngày 12/9/1930 bị đàn áp dữ dội, máy bay Pháp ném bom giết chết 171 người. Như lửa đổ thêm dầu, phong trào cách mạng bùng lên mạnh mẽ. Trước sức mạnh của quần chúng, bộ máy chính quyền của đế quốc và tay sai ở nhiều nơi tan rã, Các tổ chức đẳng lãnh đạo ban chấp hành nông hội ở thôn, xã đứng ra quản lý mọi mặt đời sống xã hội ỏ nông thôn, thực hiện chuyên chính với kẻ thù, đân chủ với quần chúng nhân dân, làm chức năng, nhiệm vụ một chính quyền cách mạng dưới hình thức các ủy ban tự quản theo kiểu Xôviết.", "type": "mcq"}, {"id": "c1-q023", "section": "revolution1930", "prompt": "Một ý nghĩa quan trọng của phong trào 1930–1931 là gì?", "options": ["Hoàn thành thống nhất đất nước", "Giành chính quyền trên cả nước", "Kết thúc cuộc kháng chiến chống Pháp", "Khẳng định thực tế quyền lãnh đạo và năng lực lãnh đạo cách mạng của Đảng"], "answer": 3, "explanation": "Phong trào kiểm nghiệm vai trò lãnh đạo của Đảng, rèn luyện cán bộ và tăng cường lòng tin của quần chúng công–nông.", "page": 74, "evidence": "cách mạng 1930 - 1931 có ý nghĩa lịch sử quan trọng đối với cách mạng Việt Nam, đã “khẳng định trong thực tế quyền lãnh đạo và năng lực lãnh đạo cách mạng của giai cấp vô sản mà đại biểu là Đẳng ta; ở chỗ nó đem lại cho nông dân niềm tin vững chắc vào giai cấp vô sản, đồng thời đem lại cho đông đảo quần chúng", "type": "mcq"}, {"id": "c1-q024", "section": "revolution1930", "prompt": "Hội nghị Trung ương tháng 10/1930 đã quyết định điều gì về tổ chức Đảng?", "options": ["Đổi tên thành Đảng Cộng sản Đông Dương và bầu Trần Phú làm Tổng Bí thư", "Đổi tên thành Hội Việt Nam Cách mạng Thanh niên", "Lập Mặt trận Việt Minh và bầu Hồ Chí Minh làm Chủ tịch", "Chuyển thành Đảng Dân chủ Việt Nam"], "answer": 0, "explanation": "Theo giáo trình, đáp án là: Đổi tên thành Đảng Cộng sản Đông Dương và bầu Trần Phú làm Tổng Bí thư.", "page": 75, "evidence": "họp Hội nghị lần thứ nhất tại Hương Cảng tức Hồng Kông (Trung Quốc), quyết định đổi tên Đảng Cộng sản Việt Nam thành Đảng Cộng sản Đông Dương. Đồng chí Trần Phú được bầu làm Tổng Bí thư của Đảng. Hội nghị thông qua Luận cương chính trị của Đảng Cộng sản Đông Dương gồm các nội dung chínb®: 1.", "type": "mcq"}, {"id": "c1-q025", "section": "revolution1930", "prompt": "Luận cương tháng 10/1930 nhấn mạnh vấn đề nào là cốt của cách mạng tư sản dân quyền?", "options": ["Vấn đề tự trị trong Liên bang Pháp", "Vấn đề thổ địa", "Vấn đề bầu cử nghị viện Pháp", "Vấn đề trung lập ngoại giao"], "answer": 1, "explanation": "Luận cương nhấn mạnh cách mạng ruộng đất; cần đối chiếu với sự ưu tiên nhiệm vụ dân tộc của Cương lĩnh đầu tiên.", "page": 76, "evidence": "chế độ phong kiến thì mới đánh đổ được đế quốc chủ nghĩa”. Luận cương nhấn mạnh: “Vấn để thổ địa là cái cốt của cách mạng tư sản dân quyền”, là cơ sở để Đảng giành quyền lãnh đạo dân cày. Giai cấp vô sản và nông dân là hai động lực chính của cách mạng tư sản đân quyền, trong đó giai cấp vô sản là", "type": "mcq"}, {"id": "c1-q026", "section": "revolution1930", "prompt": "Hạn chế nổi bật của Luận cương chính trị tháng 10/1930 là gì?", "options": ["Không đề cập phương pháp cách mạng", "Chủ trương giải tán giai cấp công nhân", "Chưa nhấn mạnh nhiệm vụ dân tộc và chưa đề ra liên minh dân tộc rộng rãi", "Hoàn toàn phủ nhận vai trò của Đảng"], "answer": 2, "explanation": "Luận cương nặng về đấu tranh giai cấp và cách mạng ruộng đất, chưa đánh giá đầy đủ yêu cầu dân tộc và khả năng tập hợp lực lượng.", "page": 77, "evidence": "nhiên, Luận cương đã không nêu rõ mâu thuẫn chủ yếu của xã hội Việt Nam thuộc địa, không nhấn mạnh nhiệm vụ giải phóng dân tộc, mà nặng về đấu tranh giai cấp và cách mạng ruộng đất; không đề ra được một chiến lược liên minh đân tộc và giai cấp rộng rãi trong cuộc đấu tranh chống đế quốc xâm lược và tay sai. Nguyên", "type": "mcq"}, {"id": "c1-q027", "section": "recovery", "prompt": "Đại hội đại biểu lần thứ I của Đảng họp ở đâu, khi nào?", "options": ["Hồng Kông, tháng 2/1930", "Hà Nội, tháng 9/1960", "Tân Trào, tháng 8/1945", "Ma Cao, tháng 3/1935"], "answer": 3, "explanation": "Theo giáo trình, đáp án là: Ma Cao, tháng 3/1935.", "page": 82, "evidence": "Đảng được phục hồi. Đó là cơ sở để tiến tới Đại hội đại biểu lần thứ I của Đảng. 'Tháng 3/1935, Đại hội đại biểu lần thứ I của Đảng họp ở Ma Cao (Trung Quốc), đề ra ba nhiệm vụ trước mắt: 1) Củng cố và phát triển Đảng; 2) Đẩy mạnh cuộc vận động tập hợp quần chúng; 3) Mỏ rộng tuyên truyền chống", "type": "mcq"}, {"id": "c1-q028", "section": "recovery", "prompt": "Ai được bầu làm Tổng Bí thư tại Đại hội I của Đảng?", "options": ["Lê Hồng Phong", "Trần Phú", "Hà Huy Tập", "Trường Chinh"], "answer": 0, "explanation": "Theo giáo trình, đáp án là: Lê Hồng Phong.", "page": 82, "evidence": "nghị quyết về vận động quần chúng. Đại hội bầu Ban Chấp hành Trung ương do đồng chí Lê Hồng Phong làm Tổng Bí thư, bầu đoàn đại biểu đi dự Đại hội VI Quốc tế Cộng sản. Đồng chí Nguyễn Ái Quốc được cử làm đại diện của Đảng bên cạnh Quốc tế Cộng sản. Đại hội lần thứ Ĩ của Đảng (3/1935) vẫn chưa đề ra một chủ trương", "type": "mcq"}, {"id": "c1-q029", "section": "democracy", "prompt": "Nhiệm vụ trước mắt của phong trào dân chủ 1936–1939 là gì?", "options": ["Thủ tiêu mọi hình thức đấu tranh công khai", "Chống phátxít, chiến tranh, phản động thuộc địa; đòi tự do, dân chủ, cơm áo, hòa bình", "Phát động ngay tổng khởi nghĩa trên toàn Đông Dương", "Chỉ tập trung cải cách ruộng đất"], "answer": 1, "explanation": "Nhiệm vụ trước mắt được xác định phù hợp tình hình quốc tế và trong nước; mục tiêu chiến lược lâu dài không bị từ bỏ.", "page": 85, "evidence": "theo những nghị quyết của Đại hội lần thứ VH Quốc tế Cộng sản!, Hội nghị xác định nhiệm vụ trước mắt là chống phátxít, chống chiến tranh đế quốc, chống phản động thuộc địa và tay sai, đòi tự do, dân chủ, cơm áo và hòa bình; lập Mặt trận nhân dân phản đế rộng rãi chính để bao gồm các giai cấp, các đẳng", "type": "mcq"}, {"id": "c1-q030", "section": "democracy", "prompt": "Những hình thức đấu tranh nào được kết hợp trong thời kỳ 1936–1939?", "options": ["Chỉ hoạt động bí mật, không tổ chức quần chúng", "Chỉ gửi kiến nghị qua quan chức thuộc địa", "Công khai, nửa công khai, hợp pháp, nửa hợp pháp với bí mật, bất hợp pháp", "Chỉ đấu tranh quân sự tập trung"], "answer": 2, "explanation": "Đảng linh hoạt kết hợp hình thức tổ chức và đấu tranh để tập hợp đông đảo quần chúng.", "page": 86, "evidence": "công khai, nửa công khai, hợp pháp, nửa hợp pháp, kết hợp. với bí mật, bất hợp pháp. Đồng chí Hà Huy Tập là Tổng Bí thư của Đảng từ tháng 8/1936 đến tháng 3/1938. Các Hội nghị lần thứ ba (3/1937) và lần thứ tư (9/1937) của Ban", "type": "mcq"}, {"id": "c1-q031", "section": "democracy", "prompt": "Hội nghị Trung ương tháng 3/1938 quyết định lập mặt trận nào?", "options": ["Mặt trận Việt Minh", "Mặt trận Liên Việt", "Mặt trận Dân tộc giải phóng miền Nam Việt Nam", "Mặt trận Dân chủ Đông Dương"], "answer": 3, "explanation": "Theo giáo trình, đáp án là: Mặt trận Dân chủ Đông Dương.", "page": 89, "evidence": "bá quốc ngữ phát triển mạnh. Hội nghị Trung ương Đảng (29 - 30/3/1938) quyết định lập Mặt trận Dân chủ Đông Dương để tập hợp rộng rãi lực lượng, phát triển phong trào. Hội nghị bầu đồng chí Nguyễn Văn Cừ làm Tổng Bí thư của Đẳng. Các hình thức tổ chức quần chúng phát triển rộng rãi, bao gốm các hội tương tế, hội", "type": "mcq"}, {"id": "c1-q032", "section": "democracy", "prompt": "Tác phẩm Tự chỉ trích năm 1939 của Nguyễn Văn Cừ tập trung vào nội dung gì?", "options": ["Tự phê bình, phê bình và rút bài học lãnh đạo của Đảng", "Cương lĩnh thành lập quân đội năm 1944", "Kế hoạch tiến công Điện Biên Phủ", "Tuyên bố thành lập nước Việt Nam Dân chủ Cộng hòa"], "answer": 0, "explanation": "Tác phẩm chỉ rõ sai lầm, khuyết điểm và bài học cần thiết trong lãnh đạo, chỉ đạo, góp phần xây dựng Đảng.", "page": 89, "evidence": "kinh tế lý tài Đông Dương. Năm 1939, Tổng Bí thư Nguyễn Văn Cừ xuất bản cuốn sách Tự chỉ trích, thẳng thắn chỉ rõ những sai lâm, khuyết điểm, nêu rõ những bài học cần thiết trong lãnh đạo, chỉ đạo của Đảng. Đó là tác phẩm có ý nghĩa lý luận, thực tiễn về xây dựng Đảng, tự phê bình và phê 89", "type": "mcq"}, {"id": "c1-q033", "section": "democracy", "prompt": "Phong trào dân chủ 1936–1939 có quan hệ thế nào với Cách mạng Tháng Tám?", "options": ["Không ảnh hưởng đến lực lượng cách mạng", "Là bước chuẩn bị về lực lượng và kinh nghiệm cho thắng lợi sau này", "Thay thế hoàn toàn nhiệm vụ giành độc lập", "Đã lập nhà nước độc lập năm 1938"], "answer": 1, "explanation": "Phong trào mở rộng trận địa, lực lượng cách mạng và tích lũy kinh nghiệm về mục tiêu, tổ chức, hình thức đấu tranh.", "page": 91, "evidence": "địa và lực lượng cách mạng được mở rộng ở cả nông thôn và thành thị, thực sự là một bước chuẩn bị cho thắng lợi của Cách mạng Tháng Tám sau này. 1. Xem Đảng Cộng sản Việt Nam: Văn kiện Đảng toàn tập, Sđd, t6, tr.375. 2. Hồ Chí Minh: Toàn tập, Sđủ, t.7, tr.21. 91", "type": "mcq"}, {"id": "c1-q034", "section": "liberation", "prompt": "Hội nghị Trung ương tháng 11/1939 nhấn mạnh chuyển hướng nào?", "options": ["Chỉ đấu tranh đòi cải thiện tiền lương", "Ưu tiên chia ruộng đất thay cho độc lập", "Đặt quyền lợi dân tộc lên tối cao, hướng vào giải phóng dân tộc", "Từ bỏ nhiệm vụ chống ngoại xâm"], "answer": 2, "explanation": "Hội nghị mở đầu chuyển hướng chiến lược trong hoàn cảnh chiến tranh, tạm gác khẩu hiệu cách mạng ruộng đất để phục vụ giải phóng dân tộc.", "page": 93, "evidence": "đổi ít nhiều cho hợp với tình thế mới”?. “Đứng trên lập trường giải phóng dân tộc, lấy quyền lợi dân tộc làm tối cao, tất cả mọi vấn đề của cuộc cách mệnh, cả vấn đề điền địa cũng phải nhằm vào s MN 4 7”, Khẩu hiệu “cách mạng cái mục đích ấy mã giải quyết ruộng đất” tạm gác lại và thay bằng các khẩu hiệu chống địa tô", "type": "mcq"}, {"id": "c1-q035", "section": "liberation", "prompt": "Nguyễn Ái Quốc trở về nước sau 30 năm hoạt động ở nước ngoài vào ngày nào?", "options": ["3/2/1930", "19/8/1945", "2/9/1945", "28/1/1941"], "answer": 3, "explanation": "Theo giáo trình, đáp án là: 28/1/1941.", "page": 95, "evidence": "hàng đầu được đề ra tại Hội nghị tháng 111939, Sau 30 năm hoạt động ở nước ngoài, ngày 28/1/1941, lãnh tụ Nguyễn Ái Quốc về nước và dùng chân ở Cao Bằng. Tháng 5/1941, Nguyễn Ái Quốc chủ trì Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng. Hội nghị khẳng định: “Vấn đề chính là nhận định cuộc cách", "type": "mcq"}, {"id": "c1-q036", "section": "liberation", "prompt": "Hội nghị Trung ương 8 tháng 5/1941 xác định nhiệm vụ cần kíp trước mắt là gì?", "options": ["Giải phóng dân tộc", "Cách mạng ruộng đất triệt để ngay lập tức", "Xây dựng chủ nghĩa xã hội ngay trong chế độ thuộc địa", "Chỉ yêu cầu tự trị trong hệ thống thuộc địa"], "answer": 0, "explanation": "Hội nghị khẳng định trước mắt là cách mạng giải phóng dân tộc và đặt quyền lợi bộ phận, giai cấp dưới sự tồn vong của dân tộc.", "page": 96, "evidence": "đế và điền địa nữa, mà là cuộc cách mạng chỉ phải giải quyết một vấn đề cần kíp “dân tộc giải phóng”. Trung ương Đảng khẳng định: “Chưa chủ trương làm cách mạng tư sản dân quyền mà chủ trương làm cách mạng giải phóng dân tộc”. Để thực hiện nhiệm vụ đó, Hội nghị quyết định tiếp tục tạm gác khẩu hiệu", "type": "mcq"}, {"id": "c1-q037", "section": "liberation", "prompt": "Các đoàn thể quần chúng trong Mặt trận Việt Minh mang tên chung nào?", "options": ["Dân nguyện", "Cứu quốc", "Tương tế", "Ái hữu"], "answer": 1, "explanation": "Tên gọi cứu quốc thể hiện mục tiêu tập hợp rộng rãi mọi lực lượng có lòng yêu nước để giành độc lập.", "page": 97, "evidence": "quyền độc lập, tự do cho đân tộc”, Các tổ chức quần chúng trong Mặt trận Việt Minh đều mang tên “cứu quốc” Trong việc xây dựng các đoàn thể cứu quốc, “điều cốt yếu là không phải những hội viên phải hiểu chủ nghĩa cộng sản, mà điều cốt yếu hơn hết là họ có tình thần cứu quốc và muốn tranh đấu cứu", "type": "mcq"}, {"id": "c1-q038", "section": "liberation", "prompt": "Hội nghị Trung ương 8 xác định nhiệm vụ trung tâm của Đảng và nhân dân là gì?", "options": ["Lập chính phủ liên bang thuộc địa", "Tạm dừng mọi chuẩn bị lực lượng", "Chuẩn bị khởi nghĩa vũ trang", "Chỉ mở rộng vận động nghị trường"], "answer": 2, "explanation": "Chuẩn bị khởi nghĩa vũ trang là nhiệm vụ trung tâm, gắn với xây dựng lực lượng và nắm thời cơ.", "page": 97, "evidence": "phủ dân chủ cộng hòa”. Thứ sáu, Hội nghị xác định chuẩn bị khỏi nghĩa vũ trang là nhiệm vụ trung tâm của Đảng và nhân dân; 1, 2, 3, 4. Đảng Cộng sản Việt Nam: Văn kiện Đảng toàn tập, 5đd, t.7, tr.112, 125, 114, 127. 97", "type": "mcq"}, {"id": "c1-q039", "section": "preinsurrection", "prompt": "Khởi nghĩa Nam Kỳ bùng nổ vào thời điểm nào?", "options": ["Ngày 27/9/1940", "Ngày 13/1/1941", "Ngày 9/3/1945", "Đêm 23/11/1940"], "answer": 3, "explanation": "Chủ trương hoãn của Trung ương chưa kịp triển khai thì khởi nghĩa nổ ra; phong trào bị thực dân Pháp đàn áp khốc liệt.", "page": 99, "evidence": "hoãn cuộc khởi nghĩa ở Nam Kỳ chưa được triển khai thì cuộc khởi nghĩa đã nổ ra vào đêm 23/11/1940. Quân khởi nghĩa đánh chiếm nhiều đồn bết và tiến công nhiều quận ly. Chính quyền cách mạng được thành lập ở một số địa phương và ban bố các quyền tự do dân chủ, mỏ các phiên tòa để xét xử phản cách mạng...", "type": "mcq"}, {"id": "c1-q040", "section": "preinsurrection", "prompt": "Ba nguyên tắc xây dựng nền văn hóa mới trong Đề cương về văn hóa Việt Nam năm 1943 là gì?", "options": ["Dân tộc, khoa học, đại chúng", "Tự do, bình đẳng, bác ái", "Tập trung, thống nhất, kịp thời", "Toàn dân, toàn diện, lâu dài"], "answer": 0, "explanation": "Đề cương xác định văn hóa là một trận địa cách mạng và nêu ba nguyên tắc dân tộc, khoa học, đại chúng.", "page": 101, "evidence": "trận địa cách mạng, chủ trương xây dựng một nền văn hóa mới theo ba nguyên tắc: dân tộc, khoa học và đại chúng. 101", "type": "mcq"}, {"id": "c1-q041", "section": "preinsurrection", "prompt": "Đội Việt Nam tuyên truyền giải phóng quân ra đời khi nào, ở đâu?", "options": ["16/8/1945, Tân Trào", "22/12/1944, Cao Bằng", "19/8/1945, Hà Nội", "3/2/1930, Hồng Kông"], "answer": 1, "explanation": "Đội ra đời tại Cao Bằng, sau đó thắng hai trận Phai Khắt và Nà Ngần, kết hợp hoạt động chính trị với quân sự.", "page": 104, "evidence": "vũ trang. Bản Chỉ thị này có giá trị như một cương lĩnh quân sự tóm tắt của Đảng. Ngày 22/12/1944, Đội Việt Nam tuyên truyền giải phóng quân ra đời ở Cao Bằng. Ba ngày sau, đội đánh thắng liên tiếp hai trận ở Phai Khắt (25/12/1944) và Nà Ngần (26/12/1944). Đội đẩy mạnh vũ trang tuyên truyền, kết hợp", "type": "mcq"}, {"id": "c1-q042", "section": "antijapan", "prompt": "Ngày 9/3/1945 xảy ra sự kiện nào ở Đông Dương?", "options": ["Tổng khởi nghĩa thắng lợi ở Hà Nội", "Đại hội quốc dân họp ở Tân Trào", "Nhật đảo chính lật đổ Pháp", "Nhật tuyên bố đầu hàng Đồng minh"], "answer": 2, "explanation": "Nhật đảo chính Pháp, độc chiếm Đông Dương; tình hình đặt ra yêu cầu chỉ đạo mới cho cách mạng.", "page": 105, "evidence": "tiến tới chỗ tao sống mày chết, quyết liệt cùng nhau”!, Với sự chuẩn bị từ trước, ngày 9/3/1945, Nhật nổ súng đảo chính lật đổ Pháp, độc chiếm Đông Dương. Pháp chống cự yếu ớt rồi nhanh chóng đầu hàng. Sau khi đảo chính thành công, Nhật thi hành một loạt chính sách nhằm củng cố quyền thống trị.", "type": "mcq"}, {"id": "c1-q043", "section": "antijapan", "prompt": "Chỉ thị Nhật–Pháp bắn nhau và hành động của chúng ta được ban hành ngày nào?", "options": ["9/3/1945", "13/8/1945", "2/9/1945", "12/3/1945"], "answer": 3, "explanation": "Ban Thường vụ Trung ương ban hành chỉ thị ngày 12/3/1945 để phân tích tình hình và phát động cao trào kháng Nhật cứu nước.", "page": 106, "evidence": "(Từ Sơn, Bắc Ninh) để phân tích tình hình và đểề.ra chủ. trương chiến lược mới. Ngày 12/3/1945, Bạn Thường vụ Trung ương Đảng ra Chỉ thị Nhật - Pháp bắn nhau và hành động của chúng ta, chỉ rõ bản chất hành động của Nhật ngày 9/3/1945 là một cuộc đảo chính tranh giành lợi ích giữa Nhật và Pháp;", "type": "mcq"}, {"id": "c1-q044", "section": "antijapan", "prompt": "Sau đảo chính tháng 3/1945, Chỉ thị xác định kẻ thù cụ thể, trước mắt và duy nhất là ai?", "options": ["Phátxít Nhật", "Toàn bộ quân Đồng minh", "Chỉ chính phủ Pháp ở châu Âu", "Mọi tầng lớp tư sản dân tộc"], "answer": 0, "explanation": "Chỉ thị xác định phátxít Nhật là kẻ thù trước mắt và thay khẩu hiệu đánh đuổi Nhật–Pháp bằng đánh đuổi phátxít Nhật.", "page": 106, "evidence": "chính tranh giành lợi ích giữa Nhật và Pháp; xác định kẻ thù cụ thể, trước mắt và duy nhất của nhân dân Đông Dương sau cuộc đảo chính là phátxít Nhật; thay khẩu hiệu “Đánh đuổi phátxít Nhật - Pháp” bằng khẩu hiệu “Đánh đuổi phátxít Nhật, nêu khẩu hiệu “Thành lập chính quyền cách mạng của nhân", "type": "mcq"}, {"id": "c1-q045", "section": "antijapan", "prompt": "Khẩu hiệu nào gắn nhu cầu cấp bách của nhân dân với cao trào kháng Nhật cứu nước?", "options": ["Trì hoãn mọi đấu tranh dân sinh", "Phá kho thóc, giải quyết nạn đói", "Chỉ tăng thuế điền thổ", "Ngừng tổ chức cứu quốc"], "answer": 1, "explanation": "Phá kho thóc, giải quyết nạn đói góp phần phát động đông đảo nhân dân vùng dậy, phát triển khởi nghĩa từng phần.", "page": 108, "evidence": "Việt Minh đẩy mạnh hoạt động vũ trang tuyên truyền, diệt ác trừ gian, tạo điều kiện phát triển các tổ chức cứu quốc trong các tầng lớp nhân dân thành thị và xây dựng lực lượng tự vệ cứu quốc. Ö các tỉnh Bắc Bộ và Bắc Trung Bộ, khẩu hiệu “phá kho thóc, giải quyết nạn đói” đã “thổi bùng ngọn", "type": "mcq"}, {"id": "c1-q046", "section": "august", "prompt": "Thời cơ tổng khởi nghĩa tháng 8/1945 chủ yếu trong khoảng thời gian nào?", "options": ["Sau khi Pháp tái lập toàn bộ bộ máy cai trị", "Từ khi chiến tranh thế giới bùng nổ năm 1939", "Sau khi Nhật đầu hàng, trước khi quân Đồng minh vào Đông Dương", "Sau khi quân Đồng minh hoàn thành chiếm đóng Đông Dương"], "answer": 2, "explanation": "Thời cơ ngắn trong nửa cuối tháng 8/1945 đòi hỏi hành động khẩn trương để tranh thủ thuận lợi và khắc phục nguy cơ.", "page": 111, "evidence": "Thời cơ giành chính quyền chỉ tồn tại trong thời gian tờ khi Nhật tuyên bố đầu hàng Đồng mình đến trước khi quân Đồng minh vào Đông Dương, vào khoảng nửa cuối tháng 8/1945. Trong tình hình trên, vấn đề giành chính quyền được đặt", "type": "mcq"}, {"id": "c1-q047", "section": "august", "prompt": "Quân lệnh số 1 phát lệnh tổng khởi nghĩa trong cả nước được ban bố ngày nào?", "options": ["12/3/1945", "19/8/1945", "2/9/1945", "13/8/1945"], "answer": 3, "explanation": "Ủy ban Khởi nghĩa toàn quốc được thành lập ngày 13/8; trong ngày ban bố Quân lệnh số 1.", "page": 111, "evidence": "công. Ngày 12/8/1945, Ủy ban lâm thời Khu giải phóng hạ lệnh khởi nghĩa trong khu. Ngày 13/8/1945, Trung ương Đảng và Tổng bộ Việt Minh thành lập Ủy ban Khôi nghĩa toàn quốc; 98 giờ cùng ngày, Ủy ban Khởi nghĩa toàn quốc ban bố “Quân lệnh số 1”, phát đi lệnh tổng khởi nghĩa trong cả nước. Ngày 14", "type": "mcq"}, {"id": "c1-q048", "section": "august", "prompt": "Ba nguyên tắc chỉ đạo tổng khởi nghĩa là gì?", "options": ["Tập trung, thống nhất, kịp thời", "Dân tộc, khoa học, đại chúng", "Hòa hoãn, nhân nhượng, kéo dài", "Đơn lẻ, bí mật, tự phát"], "answer": 0, "explanation": "Ba nguyên tắc nhằm thống nhất hành động và chớp thời cơ giành chính quyền trên cả nước.", "page": 112, "evidence": "đạo khỏi nghĩa là tập trung, thống nhất và kịp thời. Phương hướng hành động trong tổng khởi nghĩa: phải đánh chiếm ngay những nơi chắc thắng, không kể thành phố hay nông thôn; quân sự và chính trị phải phối hợp; phải làm tan rã tỉnh thần quân địch và dụ", "type": "mcq"}, {"id": "c1-q049", "section": "august", "prompt": "Đại hội quốc dân Tân Trào ngày 16/8/1945 lập cơ quan nào?", "options": ["Hội Việt Nam Cách mạng Thanh niên", "Ủy ban giải phóng dân tộc Việt Nam do Hồ Chí Minh làm Chủ tịch", "Đông Dương Cộng sản Đảng", "Chính phủ Mặt trận nhân dân Pháp"], "answer": 1, "explanation": "Đại hội tán thành tổng khởi nghĩa, thông qua 10 chính sách lớn của Việt Minh và lập Ủy ban giải phóng dân tộc.", "page": 112, "evidence": "quyết định tổng khởi nghĩa của Đảng, thông qua 10 chính sách lớn của Việt Minh, lập Ủy ban giải phóng dân tộc Việt Nam do Hồ Chí Minh làm Chủ tịch. Ngay sau Đại hội quốc đân, Hồ Chí Minh kêu gọi đồng bào cả nước: “Giờ quyết định cho vận mệnh dân tộc ta đã đến. Toàn quốc đồng bào hãy đứng dậy đem sức ta mà tự", "type": "mcq"}, {"id": "c1-q050", "section": "august", "prompt": "Nhân dân Hà Nội giành chính quyền trong Tổng khởi nghĩa vào ngày nào?", "options": ["25/8/1945", "30/8/1945", "19/8/1945", "23/8/1945"], "answer": 2, "explanation": "Thắng lợi ở Hà Nội ngày 19/8 tạo ảnh hưởng và cổ vũ mạnh mẽ phong trào cả nước.", "page": 114, "evidence": "lượng, Thành ủy Hà Nội nhận định đã có đủ điều kiện để phát động tổng khỏi nghĩa. Sáng ngày 19/8, Thủ đô Hà Nội tràn ngập cờ đổ sao vàng. Quần chúng cách mạng xuống đường tập hợp thành đội ngũ, rầm rộ kéo đến quảng trường Nhà hát thành phố trong tiếng hát “Tiến quân ca” và cờ đổ sao vàng để dự cuộc", "type": "mcq"}, {"id": "c1-q051", "section": "august", "prompt": "Khởi nghĩa giành chính quyền ở Sài Gòn thắng lợi vào ngày nào?", "options": ["19/8/1945", "16/8/1945", "2/9/1945", "25/8/1945"], "answer": 3, "explanation": "Ngày 25/8, lực lượng khởi nghĩa và quần chúng chiếm các công sở ở Sài Gòn, giành thắng lợi nhanh chóng.", "page": 115, "evidence": "nghĩa với gậy tầm vông, giáo mác, từ các tỉnh xung quanh rầm rập kéo về Sài Gòn. Sáng 25/8, hơn 1 triệu người biểu tình tuần hành thị uy. Quân khởi nghĩa chiếm các công sở. Cuộc khỏi nghĩa thành công nhanh chóng. Những cuộc khởi nghĩa ở Hà Nội, Huế, Sài Gòn và các đô thị đập tan các cơ quan", "type": "mcq"}, {"id": "c1-q052", "section": "august", "prompt": "Chủ tịch Hồ Chí Minh đọc Tuyên ngôn độc lập tại Ba Đình vào ngày nào?", "options": ["2/9/1945", "19/8/1945", "30/8/1945", "23/9/1945"], "answer": 0, "explanation": "Lễ độc lập công bố trước quốc dân và thế giới sự ra đời của nước Việt Nam Dân chủ Cộng hòa.", "page": 117, "evidence": "nhiêu hy vọng, gắng sức và tin tưởng của hơn hai mươi triệu nhân dân Việt Nam”!, Ngày 2/9/1945, Lễ độc lập được tổ chức trọng thể tại Quảng trường Ba Đình, Hà Nội. Chính phủ lâm thời ra mắt quốc dân. Thay mặt Chính phủ lâm thời, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn độc lập, trịnh trọng tuyên bố", "type": "mcq"}, {"id": "c1-q053", "section": "meaning", "prompt": "Tính chất điển hình của Cách mạng Tháng Tám năm 1945 là gì?", "options": ["Cuộc cải tổ hành chính trong chế độ quân chủ", "Cách mạng giải phóng dân tộc mang tính chất dân chủ mới", "Cách mạng tư sản theo mô hình thuộc địa tự trị", "Cách mạng ruộng đất đã hoàn thành triệt để"], "answer": 1, "explanation": "Cách mạng tập trung giải phóng dân tộc, huy động toàn dân và thành lập chính quyền dân chủ cộng hòa; cách mạng ruộng đất chưa hoàn thành.", "page": 119, "evidence": "chất A É& Cách mạng Tháng Tám năm 1945 là “một cuộc cách mạng giải phóng dân tộc mang tính chất dân chủ mới. Nó là một bộ phận khăng khít của cách mạng dân tộc dân chủ nhân dân Việt Nam”, “Cách mạng Tháng Tám Việt Nam là một cuộc cách mạng giải phóng dân tộc. Mục đích của nó là làm cho dân tộc Việt Nam thoát", "type": "mcq"}, {"id": "c1-q054", "section": "meaning", "prompt": "Thắng lợi Cách mạng Tháng Tám làm thay đổi địa vị nhân dân Việt Nam như thế nào?", "options": ["Chỉ thay đổi nghĩa vụ thuế", "Không thay đổi quyền quyết định vận mệnh", "Từ thân phận nô lệ trở thành người chủ đất nước", "Từ công dân độc lập thành cư dân thuộc địa"], "answer": 2, "explanation": "Giành chính quyền và lập nhà nước mới đem lại cho nhân dân quyền quyết định vận mệnh của mình.", "page": 122, "evidence": "lợi của Oách mạng Tháng Tám, nhân dân Việt Nam từ thân phận nô lệ bước lên địa vị người chủ đất nước, có quyền quyết định vận mệnh của mình. Nước Việt Nam từ một nước thuộc địa trở thành một quốc gia độc lập có chủ quyền, vươn lên cùng các dân tộc trên thế giới đấu tranh cho những mục tiêu cao cả của", "type": "mcq"}, {"id": "c1-q055", "section": "meaning", "prompt": "Bài học về phương pháp cách mạng từ Cách mạng Tháng Tám nhấn mạnh điều gì?", "options": ["Chỉ dựa vào ngoại giao", "Chỉ chờ điều kiện quốc tế thuận lợi", "Tách rời đấu tranh chính trị và đấu tranh vũ trang", "Kết hợp lực lượng chính trị với vũ trang, khởi nghĩa từng phần lên tổng khởi nghĩa đúng thời cơ"], "answer": 3, "explanation": "Bài học là xây dựng lực lượng chính trị và vũ trang, kết hợp các hình thức đấu tranh, chớp đúng thời cơ giành chính quyền toàn quốc.", "page": 124, "evidence": "mạng của quần chúng, ra sức xây dựng lực lượng chính trị và lực lượng vũ trang, kết hợp đấu tranh chính trị với đấu tranh vũ trang, tiến hành chiến tranh du kích cục bộ và khởi nghĩa từng phần, giành chính quyền bộ phận ở những vùng nông thôn có điều kiện, tiến lên chớp đúng thời cơ, phát động", "type": "mcq"}], "mindmap": {"title": "Đảng ra đời và giành chính quyền (1930–1945)", "branches": [{"id": "c1-b1", "title": "Bối cảnh và con đường cứu nước", "page": 36, "summary": "Chế độ thuộc địa làm biến đổi xã hội Việt Nam và đặt ra yêu cầu tìm một con đường cứu nước mới. Tìm đường cứu nước, lựa chọn cách mạng vô sản và chuẩn bị về tư tưởng, chính trị, tổ chức.", "children": [{"title": "Tác động quốc tế", "page": 37, "note": "Cách mạng Tháng Mười Nga và Quốc tế Cộng sản tác động đến phong trào giải phóng dân tộc."}, {"title": "Mâu thuẫn dân tộc", "page": 43, "note": "Chính sách thống trị, khai thác thuộc địa làm xã hội phân hóa và mâu thuẫn dân tộc gay gắt."}, {"title": "Yêu cầu về đường lối mới", "page": 49, "note": "Các phong trào phong kiến, dân chủ tư sản thất bại; yêu cầu về đường lối và tổ chức tiên phong trở nên cấp thiết."}, {"title": "Tìm đường cứu nước", "page": 50, "note": "Năm 1911, Nguyễn Tất Thành ra đi tìm đường cứu nước, trải nghiệm thực tế nhiều nước."}, {"title": "Tư tưởng và chính trị", "page": 52, "note": "Truyền bá chủ nghĩa Mác–Lênin, xác lập đường lối giải phóng dân tộc và vai trò tổ chức của Đảng."}, {"title": "Chuẩn bị tổ chức", "page": 55, "note": "Tháng 6/1925, Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu."}, {"title": "Đường cách mệnh", "page": 57, "note": "Đường cách mệnh trình bày con đường, mục tiêu, lực lượng và phương pháp đấu tranh cách mạng."}, {"title": "Bước ngoặt năm 1920", "page": 51, "note": "Đọc Luận cương của Lênin và tham gia sáng lập Đảng Cộng sản Pháp, trở thành người cộng sản đầu tiên của Việt Nam."}, {"title": "Báo Thanh niên", "page": 56, "note": "Số đầu ra ngày 21/6/1925; tuyên truyền chủ nghĩa Mác–Lênin và con đường giải phóng dân tộc."}]}, {"id": "c1-b2", "title": "Thành lập Đảng và Cương lĩnh", "page": 58, "summary": "Ba tổ chức cộng sản ra đời năm 1929 tạo tiền đề đồng thời đặt ra yêu cầu hợp nhất. Cương lĩnh xác lập đường lối giải phóng dân tộc, hướng tới xã hội cộng sản và đoàn kết lực lượng yêu nước.", "children": [{"title": "Các đảng cộng sản năm 1929", "page": 59, "note": "Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng ra đời, thúc đẩy phong trào cách mạng."}, {"title": "Đông Dương Cộng sản Liên đoàn", "page": 60, "note": "Đông Dương Cộng sản Liên đoàn hình thành từ bộ phận tiên tiến của Tân Việt Cách mạng Đảng."}, {"title": "Hội nghị hợp nhất", "page": 61, "note": "Nguyễn Ái Quốc triệu tập hội nghị hợp nhất tại Cửu Long, Hồng Kông."}, {"title": "Tên Đảng và văn kiện", "page": 62, "note": "Hội nghị thống nhất tên Đảng Cộng sản Việt Nam, thông qua các văn kiện nền tảng."}, {"title": "Độc lập dân tộc trước hết", "page": 65, "note": "Kết hợp chống đế quốc và chống phong kiến, đặt độc lập dân tộc ở vị trí hàng đầu."}, {"title": "Công–nông và đại đoàn kết", "page": 66, "note": "Lực lượng cơ bản là công–nông, đồng thời đoàn kết những giai tầng tiến bộ, yêu nước."}, {"title": "Đảng và cách mạng thế giới", "page": 67, "note": "Gắn cách mạng Việt Nam với cách mạng thế giới, khẳng định vai trò lãnh đạo của Đảng."}, {"title": "Ba yếu tố hình thành Đảng", "page": 69, "note": "Đảng ra đời là sự kết hợp chủ nghĩa Mác–Lênin, phong trào công nhân và phong trào yêu nước."}]}, {"id": "c1-b3", "title": "1930–1935: cao trào và phục hồi", "page": 71, "summary": "Cao trào 1930–1931 kiểm nghiệm vai trò lãnh đạo; Luận cương nêu chiến lược cách mạng và bộc lộ hạn chế cần khắc phục. Trong khủng bố, đảng viên và quần chúng duy trì đấu tranh, khôi phục cơ sở và hệ thống lãnh đạo.", "children": [{"title": "Xôviết Nghệ–Tĩnh", "page": 73, "note": "Đỉnh cao là Xôviết Nghệ–Tĩnh, hình thức chính quyền cách mạng ở một số địa phương."}, {"title": "Vai trò và năng lực lãnh đạo", "page": 74, "note": "Phong trào rèn luyện lực lượng và kiểm nghiệm vai trò lãnh đạo của Đảng."}, {"title": "Hội nghị tháng 10/1930", "page": 75, "note": "Hội nghị tháng 10/1930 đổi tên Đảng, bầu Trần Phú làm Tổng Bí thư, thông qua Luận cương."}, {"title": "Hạn chế Luận cương", "page": 77, "note": "Luận cương chưa nhấn mạnh đúng mức nhiệm vụ dân tộc và chưa đề ra liên minh dân tộc rộng rãi."}, {"title": "Đấu tranh trong tù", "page": 80, "note": "Các chi bộ trong tù tổ chức đấu tranh, huấn luyện và giữ vững lực lượng."}, {"title": "Chương trình hành động 1932", "page": 81, "note": "Chương trình hành động năm 1932 vạch nhiệm vụ khôi phục tổ chức và phong trào."}, {"title": "Phục hồi hệ thống tổ chức", "page": 82, "note": "Ban Chỉ huy ở ngoài thành lập năm 1934; hệ thống tổ chức phục hồi đầu năm 1935."}, {"title": "Đại hội I tại Ma Cao", "page": 82, "note": "Đại hội I tháng 3/1935 tại Ma Cao đề ra nhiệm vụ củng cố Đảng, vận động quần chúng, chống đế quốc và chiến tranh."}]}, {"id": "c1-b4", "title": "1936–1939: dân chủ, dân sinh", "page": 83, "summary": "Điều chỉnh nhiệm vụ trước mắt và hình thức đấu tranh, vận động rộng rãi vì tự do, dân chủ, cơm áo, hòa bình.", "children": [{"title": "Chống phátxít, chiến tranh", "page": 83, "note": "Bối cảnh chống phátxít đặt ra nhiệm vụ tập hợp mặt trận nhân dân rộng rãi."}, {"title": "Kết hợp hình thức đấu tranh", "page": 86, "note": "Kết hợp công khai, hợp pháp, nửa hợp pháp với bí mật, bất hợp pháp."}, {"title": "Mặt trận Dân chủ", "page": 89, "note": "Mặt trận Dân chủ Đông Dương tập hợp lực lượng; báo chí, vận động nghị trường và truyền bá quốc ngữ phát triển."}, {"title": "Chuẩn bị lực lượng, kinh nghiệm", "page": 91, "note": "Phong trào mở rộng lực lượng, tích lũy kinh nghiệm cho Cách mạng Tháng Tám."}]}, {"id": "c1-b5", "title": "1939–1941: giải phóng dân tộc", "page": 92, "summary": "Chiến tranh thế giới và ách thống trị Pháp–Nhật đặt nhiệm vụ giải phóng dân tộc lên hàng đầu.", "children": [{"title": "Chuyển hướng tháng 11/1939", "page": 93, "note": "Hội nghị tháng 11/1939 mở đầu chuyển hướng chiến lược, lấy quyền lợi dân tộc làm tối cao."}, {"title": "Nguyễn Ái Quốc về nước", "page": 95, "note": "Nguyễn Ái Quốc về nước ngày 28/1/1941, chủ trì Hội nghị Trung ương 8 tháng 5/1941."}, {"title": "Nhiệm vụ dân tộc hàng đầu", "page": 96, "note": "Hội nghị hoàn chỉnh chuyển hướng: giải phóng dân tộc, tạm gác cách mạng ruộng đất, quyền dân tộc tự quyết."}, {"title": "Việt Minh và chuẩn bị khởi nghĩa", "page": 97, "note": "Chuẩn bị khởi nghĩa vũ trang là nhiệm vụ trung tâm; Việt Minh tập hợp rộng rãi lực lượng cứu quốc."}]}, {"id": "c1-b6", "title": "Chuẩn bị lực lượng và căn cứ", "page": 98, "summary": "Đấu tranh chống Pháp–Nhật gắn với xây dựng lực lượng và căn cứ để tiến tới khởi nghĩa.", "children": [{"title": "Bắc Sơn, Nam Kỳ, Đô Lương", "page": 99, "note": "Khởi nghĩa Bắc Sơn, Nam Kỳ và binh biến Đô Lương báo hiệu bước phát triển đấu tranh vũ trang."}, {"title": "Lực lượng chính trị", "page": 101, "note": "Việt Minh và các đoàn thể cứu quốc xây dựng lực lượng chính trị rộng lớn."}, {"title": "Đề cương văn hóa 1943", "page": 101, "note": "Đề cương về văn hóa năm 1943 nêu ba nguyên tắc dân tộc, khoa học, đại chúng."}, {"title": "Lực lượng vũ trang", "page": 104, "note": "Đội Việt Nam tuyên truyền giải phóng quân ra đời ngày 22/12/1944 ở Cao Bằng."}]}, {"id": "c1-b7", "title": "Kháng Nhật cứu nước", "page": 104, "summary": "Sau đảo chính Nhật–Pháp, cao trào phát triển thành khởi nghĩa từng phần, chuẩn bị trực tiếp cho tổng khởi nghĩa.", "children": [{"title": "Đảo chính Nhật–Pháp", "page": 105, "note": "Nhật đảo chính Pháp ngày 9/3/1945, độc chiếm Đông Dương."}, {"title": "Chỉ thị ngày 12/3/1945", "page": 106, "note": "Chỉ thị ngày 12/3 xác định Nhật là kẻ thù trước mắt, phát động cao trào kháng Nhật cứu nước."}, {"title": "Phá kho thóc, cứu đói", "page": 108, "note": "Khẩu hiệu phá kho thóc, giải quyết nạn đói góp phần huy động đông đảo quần chúng."}, {"title": "Khu giải phóng Việt Bắc", "page": 107, "note": "Khu giải phóng Việt Bắc hình thành ngày 4/6/1945, trở thành căn cứ địa chính của cả nước."}]}, {"id": "c1-b8", "title": "Tổng khởi nghĩa tháng 8/1945", "page": 109, "summary": "Chớp thời cơ khi Nhật đầu hàng, giành chính quyền trước khi quân Đồng minh vào Đông Dương.", "children": [{"title": "Quân lệnh số 1", "page": 111, "note": "Quân lệnh số 1 ngày 13/8/1945 phát lệnh tổng khởi nghĩa."}, {"title": "Quốc dân Đại hội Tân Trào", "page": 112, "note": "Đại hội quốc dân Tân Trào tán thành tổng khởi nghĩa, lập Ủy ban giải phóng dân tộc."}, {"title": "Hà Nội, Huế, Sài Gòn", "page": 115, "note": "Thắng lợi ở Hà Nội, Huế, Sài Gòn có ý nghĩa quyết định đối với cả nước."}, {"title": "Tuyên ngôn độc lập", "page": 117, "note": "Ngày 2/9/1945, Tuyên ngôn độc lập công bố sự ra đời của nước Việt Nam Dân chủ Cộng hòa."}]}, {"id": "c1-b9", "title": "Tính chất, ý nghĩa, kinh nghiệm", "page": 119, "summary": "Cách mạng giải phóng dân tộc mang tính dân chủ mới, mở ra kỷ nguyên độc lập, tự do và hướng tới chủ nghĩa xã hội.", "children": [{"title": "Giải phóng dân tộc", "page": 119, "note": "Huy động toàn dân tộc, giải quyết nhiệm vụ hàng đầu là giải phóng dân tộc."}, {"title": "Nhân dân làm chủ đất nước", "page": 122, "note": "Chấm dứt ách thuộc địa và chế độ quân chủ; nhân dân trở thành người chủ đất nước."}, {"title": "Chỉ đạo chiến lược", "page": 123, "note": "Bài học chỉ đạo chiến lược: đặt giải phóng dân tộc lên hàng đầu."}, {"title": "Lực lượng, phương pháp, Đảng", "page": 124, "note": "Đại đoàn kết, kết hợp chính trị với vũ trang, chớp thời cơ và xây dựng Đảng vững mạnh."}]}]}, "timeline": [{"year": "1911", "title": "Nguyễn Tất Thành ra đi tìm đường cứu nước", "page": 50, "description": "Bắt đầu khảo nghiệm thực tiễn để lựa chọn con đường giải phóng dân tộc."}, {"year": "1920", "title": "Đến với chủ nghĩa Mác–Lênin", "page": 51, "description": "Đọc Luận cương Lênin, tán thành Quốc tế Cộng sản và tham gia sáng lập Đảng Cộng sản Pháp."}, {"year": "6/1925", "title": "Hội Việt Nam Cách mạng Thanh niên", "page": 55, "description": "Thành lập tại Quảng Châu, chuẩn bị cán bộ và tổ chức cho sự ra đời của Đảng."}, {"year": "1929", "title": "Các tổ chức cộng sản ra đời", "page": 60, "description": "Ba tổ chức cộng sản ra đời, đặt ra yêu cầu thống nhất lãnh đạo cách mạng."}, {"year": "2/1930", "title": "Thành lập Đảng Cộng sản Việt Nam", "page": 64, "description": "Hội nghị do Nguyễn Ái Quốc chủ trì thông qua các văn kiện Cương lĩnh đầu tiên."}, {"year": "1930–1931", "title": "Xôviết Nghệ–Tĩnh", "page": 73, "description": "Đỉnh cao phong trào công–nông, xuất hiện chính quyền cách mạng ở một số địa phương."}, {"year": "3/1935", "title": "Đại hội I của Đảng", "page": 82, "description": "Họp tại Ma Cao, đánh dấu sự phục hồi tổ chức và phong trào cách mạng."}, {"year": "1936–1939", "title": "Phong trào dân chủ", "page": 85, "description": "Chống phản động thuộc địa, đòi tự do, dân chủ, cơm áo và hòa bình."}, {"year": "5/1941", "title": "Hội nghị Trung ương 8", "page": 95, "description": "Hoàn chỉnh chuyển hướng chiến lược, đặt giải phóng dân tộc lên hàng đầu và lập Việt Minh."}, {"year": "22/12/1944", "title": "Đội Việt Nam tuyên truyền giải phóng quân", "page": 104, "description": "Ra đời tại Cao Bằng, phát triển lực lượng vũ trang và cơ sở cách mạng."}, {"year": "8/1945", "title": "Tổng khởi nghĩa giành chính quyền", "page": 111, "description": "Chớp thời cơ Nhật đầu hàng, toàn dân nổi dậy giành chính quyền."}, {"year": "2/9/1945", "title": "Tuyên ngôn độc lập", "page": 117, "description": "Chủ tịch Hồ Chí Minh tuyên bố sự ra đời của nước Việt Nam Dân chủ Cộng hòa tại Ba Đình."}], "reviewPrompts": [{"prompt": "Phân tích những điều kiện cần thiết dẫn tới thành lập Đảng Cộng sản Việt Nam tháng 2/1930.", "page": 125}, {"prompt": "Nội dung cơ bản và ý nghĩa lịch sử của Cương lĩnh chính trị đầu tiên của Đảng được Hội nghị thành lập Đảng (2/1930) thông qua.", "page": 125}, {"prompt": "Vai trò lãnh đạo của Đảng trong sự nghiệp giải phóng dân tộc 1930–1945.", "page": 126}, {"prompt": "Tính chất, ý nghĩa và bài học kinh nghiệm của cuộc Cách mạng Tháng Tám năm 1945.", "page": 126}]}, {"id": "c2", "label": "Chương 2", "title": "Đảng lãnh đạo hai cuộc kháng chiến chống ngoại xâm, hoàn thành giải phóng dân tộc, thống nhất đất nước", "period": "1945–1975", "startPage": 127, "endPage": 236, "summary": "Tìm hiểu sự lãnh đạo của Đảng trong xây dựng, bảo vệ chính quyền cách mạng và kháng chiến chống thực dân Pháp. Theo dõi đường lối cách mạng hai miền, kháng chiến chống Mỹ và thắng lợi giải phóng miền Nam, thống nhất đất nước.", "sections": [{"id": "c2-s1", "title": "Xây dựng và bảo vệ chính quyền cách mạng (1945–1946)", "pages": [128, 145], "summary": "Đảng lãnh đạo giải quyết những khó khăn sau Cách mạng Tháng Tám, củng cố nhà nước và bảo vệ nền độc lập mới giành được.", "points": ["Nhận diện thuận lợi và tình thế khó khăn về kinh tế, văn hóa, chính trị, quân sự.", "Chỉ thị Kháng chiến kiến quốc: củng cố chính quyền, chống Pháp, bài trừ nội phản và cải thiện đời sống.", "Chống giặc đói, chống giặc dốt; Tổng tuyển cử và Hiến pháp năm 1946.", "Kháng chiến ở Nam Bộ; đấu tranh, nhân nhượng có nguyên tắc để thêm thời gian chuẩn bị."]}, {"id": "c2-s2", "title": "Đường lối kháng chiến và tổ chức chiến đấu (1946–1950)", "pages": [145, 160], "summary": "Từ toàn quốc kháng chiến, Đảng từng bước hình thành và thực hiện đường lối chiến tranh nhân dân.", "points": ["Toàn dân, toàn diện, lâu dài, dựa vào sức mình là chính.", "Chiến đấu ở đô thị để giam chân địch và bảo toàn lực lượng.", "Việt Bắc thu đông 1947 bảo vệ cơ quan đầu não, căn cứ địa.", "Xây dựng lực lượng, hậu phương và ngoại giao; Biên giới 1950 mở cục diện mới."]}, {"id": "c2-s3", "title": "Đẩy mạnh kháng chiến đến thắng lợi (1951–1954)", "pages": [160, 174], "summary": "Đại hội II hoàn chỉnh đường lối; phối hợp quân sự, xây dựng hậu phương và ngoại giao để kết thúc chiến tranh.", "points": ["Đảng ra hoạt động công khai với tên Đảng Lao động Việt Nam; thông qua Chính cương năm 1951.", "Đẩy mạnh kháng chiến trên các mặt trận và tăng cường đoàn kết ba nước Đông Dương.", "Chủ trương Đông Xuân 1953–1954 làm phân tán lực lượng địch.", "Chiến thắng Điện Biên Phủ và đấu tranh tại Hội nghị Giơnevơ."]}, {"id": "c2-s4", "title": "Ý nghĩa và kinh nghiệm kháng chiến chống Pháp", "pages": [175, 179], "summary": "Thắng lợi bảo vệ thành quả Cách mạng Tháng Tám, giải phóng miền Bắc và để lại những kinh nghiệm lãnh đạo chiến tranh.", "points": ["Giải phóng miền Bắc, tạo cơ sở cho quá độ lên chủ nghĩa xã hội và chi viện miền Nam.", "Khơi dậy sức mạnh toàn dân, kết hợp nội lực với sự ủng hộ quốc tế.", "Kết hợp kháng chiến với kiến quốc, quân sự với các mặt trận khác.", "Xây dựng ba thứ quân, xây dựng Đảng; khắc phục chủ quan, giáo điều."]}, {"id": "c2-s5", "title": "Cách mạng hai miền từ sau Giơnevơ đến Đồng khởi (1954–1960)", "pages": [180, 192], "summary": "Miền Bắc khôi phục kinh tế, cải tạo xã hội; miền Nam chuyển từ giữ gìn lực lượng sang thế tiến công.", "points": ["Khôi phục sản xuất, ổn định đời sống miền Bắc; chỉ ra sai lầm trong cải cách ruộng đất và tổ chức sửa sai.", "Cải tạo xã hội chủ nghĩa và xây dựng cơ sở hậu phương.", "Nghị quyết Trung ương 15 kết hợp đấu tranh chính trị với đấu tranh vũ trang.", "Đồng khởi 1960 và thành lập Mặt trận Dân tộc giải phóng miền Nam Việt Nam."]}, {"id": "c2-s6", "title": "Hai chiến lược cách mạng và chống Chiến tranh đặc biệt (1961–1965)", "pages": [193, 205], "summary": "Đại hội III xác định quan hệ giữa hai miền; miền Bắc xây dựng chủ nghĩa xã hội và chi viện, miền Nam phát triển thế tiến công.", "points": ["Miền Bắc quyết định nhất; miền Nam quyết định trực tiếp đối với giải phóng miền Nam.", "Kế hoạch nhà nước 5 năm lần thứ nhất 1961–1965.", "Chiến đấu trên ba vùng chiến lược bằng ba mũi giáp công.", "Ấp Bắc, Bình Giã và các thắng lợi làm phá sản Chiến tranh đặc biệt."]}, {"id": "c2-s7", "title": "Lãnh đạo cách mạng cả nước, giải phóng miền Nam (1965–1975)", "pages": [205, 232], "summary": "Cả nước kháng chiến chống Mỹ; kết hợp chiến đấu, xây dựng hậu phương và ngoại giao, tiến tới Tổng tiến công mùa xuân 1975.", "points": ["Trung ương 11, 12 năm 1965 xác định quyết tâm và đường lối kháng chiến trên cả nước.", "Miền Bắc vừa sản xuất vừa chiến đấu, chi viện; miền Nam đánh bại Chiến tranh cục bộ.", "Mậu Thân 1968 tạo bước ngoặt; giáo trình chỉ ra cả hạn chế trong chỉ đạo.", "Chống Việt Nam hóa chiến tranh; tiến công 1972, Điện Biên Phủ trên không và Hiệp định Pari.", "Nắm thời cơ sau Phước Long; Tây Nguyên, Huế – Đà Nẵng, Chiến dịch Hồ Chí Minh."]}, {"id": "c2-s8", "title": "Ý nghĩa và kinh nghiệm thời kỳ 1954–1975", "pages": [233, 236], "summary": "Thắng lợi năm 1975 kết thúc cách mạng dân tộc dân chủ nhân dân trên cả nước, mở ra thời kỳ hòa bình, thống nhất và đi lên chủ nghĩa xã hội.", "points": ["Giành lại độc lập, thống nhất và mở ra kỷ nguyên mới cho dân tộc.", "Ảnh hưởng quốc tế đối với phong trào độc lập dân tộc, dân chủ và hòa bình.", "Giương cao độc lập dân tộc và chủ nghĩa xã hội; dùng phương pháp cách mạng tổng hợp.", "Coi trọng tổ chức chiến đấu, xây dựng Đảng, lực lượng và đoàn kết quốc tế; nhận diện hạn chế chủ quan."]}], "questions": [{"id": "c2-q001", "section": "c2-s1", "prompt": "Phiên họp đầu tiên của Chính phủ lâm thời ngày 3/9/1945 xác định ba nhiệm vụ cấp bách nào?", "options": ["Diệt giặc đói, giặc dốt và giặc ngoại xâm", "Chỉ tập trung phát triển công nghiệp nặng", "Chỉ tổ chức cải cách hành chính", "Hoàn thành ngay công cuộc hợp tác hóa"], "answer": 0, "explanation": "Chính phủ xác định chống đói, chống dốt và chống ngoại xâm là những nhiệm vụ lớn trước mắt.", "page": 131, "evidence": "ngay nhiệm vụ lớn trước mắt là: điệt giặc đói, điệt giặc đốt và diệt giặc ngoại xâm. Ngày 25/11/1945, Ban Chấp hành Trung ương Đảng ra Chỉ thị Kháng chiến kiến quốc, nhận định tình hình và định hướng con đường ", "type": "mcq"}, {"id": "c2-q002", "section": "c2-s1", "prompt": "Chỉ thị Kháng chiến kiến quốc được Trung ương Đảng ban hành vào ngày nào?", "options": ["7/5/1954", "25/11/1945", "6/1/1946", "19/12/1946"], "answer": 1, "explanation": "Chỉ thị ngày 25/11/1945 nhận định tình hình và định hướng cách mạng sau khi giành chính quyền.", "page": 131, "evidence": "Ngày 25/11/1945, Ban Chấp hành Trung ương Đảng ra Chỉ thị Kháng chiến kiến quốc, nhận định tình hình và định hướng con đường đi lên của cách mạng Việt Nam sau khi giành được chính quyền. Chỉ thị phân tích sâu sắc sự biến đổi của tình hình thế giới và trong nước, nhất là tình hình Nam Bộ và xác định rõ: “kẻ thù chính của ta lúc này là thực dân Pháp xâm lược phải tập trung ngọn lửa đấu tranh vào chúng”; nêu rõ mục tiêu của cuộc cách mạng Đông Dương lúc này vẫn là “đân tộc giải phóng” và để ra khẩu hiệu “Dân tộc trên hết, 1.", "type": "mcq"}, {"id": "c2-q003", "section": "c2-s1", "prompt": "Chỉ thị Kháng chiến kiến quốc xác định kẻ thù chính lúc đó là ai?", "options": ["Đế quốc Mỹ trực tiếp đưa quân chiến đấu vào miền Nam", "Toàn bộ nhân dân Pháp", "Thực dân Pháp xâm lược", "Phát xít Nhật đang mở rộng chiến tranh thế giới"], "answer": 2, "explanation": "Chỉ thị xác định phải tập trung đấu tranh vào thực dân Pháp xâm lược.", "page": 131, "evidence": "kẻ thù chính của ta lúc này là thực dân Pháp xâm lược phải tập trung ngọn lửa đấu tranh vào chúng”; nêu rõ mục tiêu của cuộc cách mạng Đông Dương lúc này vẫn là “đân tộc giải phóng” và để ra khẩu hiệu “Dân tộc ", "type": "mcq"}, {"id": "c2-q004", "section": "c2-s1", "prompt": "Phong trào Bình dân học vụ nhằm giải quyết nhiệm vụ chủ yếu nào?", "options": ["Tổ chức tuyển quân cho quân đội chính quy", "Thực hiện tập thể hóa toàn bộ nông nghiệp", "Mở cuộc tiến công quân sự ở biên giới", "Xóa nạn mù chữ, giúp nhân dân học chữ quốc ngữ"], "answer": 3, "explanation": "Bình dân học vụ gắn với nhiệm vụ chống giặc dốt và xây dựng đời sống văn hóa mới.", "page": 134, "evidence": "phong trào “Bình dân học vụ”, toàn dân học chữ quốc ngữ để từng bước xóa bỏ nạn dốt; vận động toàn dân xây đựng nếp sống mới, đời sống văn hóa mới để đẩy lùi các tệ nạn, hủ tục, thói quen cũ, lạc hậu cản trổ tiến bộ.", "type": "mcq"}, {"id": "c2-q005", "section": "c2-s1", "prompt": "Cuộc Tổng tuyển cử đầu tiên bầu Quốc hội diễn ra vào ngày nào?", "options": ["6/1/1946", "2/9/1945", "9/11/1946", "21/7/1954"], "answer": 0, "explanation": "Ngày 6/1/1946, nhân dân cả nước tham gia bầu cử theo hình thức phổ thông đầu phiếu.", "page": 134, "evidence": "Ngày 6/1/1946, nhân dân cả nước tham gia cuộc bầu cử; có hơn 89% số cử tri đi bỏ phiếu dân chủ lân đầu tiên; đồng bào Nam Bộ và một số nơi đi bỏ phiếu dưới làn đạn của giặc Pháp, nhưng tất cả đều thể hiện rõ tình thần “mỗi lá phiếu là một viên đạn bắn vào quân thù”, làm thất bại âm mưu chia rẽ, lật đổ của các kẻ thù.", "type": "mcq"}, {"id": "c2-q006", "section": "c2-s1", "prompt": "Quốc hội thông qua bản Hiến pháp đầu tiên của Nhà nước Việt Nam Dân chủ Cộng hòa vào ngày nào?", "options": ["19/12/1946", "9/11/1946", "25/11/1945", "6/3/1946"], "answer": 1, "explanation": "Hiến pháp năm 1946 được thông qua tại kỳ họp thứ hai của Quốc hội, ngày 9/11/1946.", "page": 135, "evidence": "Tại kỳ họp thứ 2, ngày 9/11/1946, Quốc hội đã thông qua bản Hiến pháp đầu tiên của Nhà nước Việt Nam Đân chủ Cộng hòa (Hiến pháp năm 1946). Xây dựng đi đôi với bảo vệ và làm cho bộ máy chính quyền thực sự dân chủ, trong sạch, trong thư gửi cho các ủy ban nhân dân, Hồ Chí Minh chỉ rõ: “các cơ quan của Chính phủ từ toàn quốc đến các làng, đều là công bộc của dân, nghĩa là để gánh việc chung cho dân, chứ không phải để đề đầu dân như trong thời kỹ dưới quyền thống trị của Pháp, Nhật”).", "type": "mcq"}, {"id": "c2-q007", "section": "c2-s1", "prompt": "Theo Hiệp định Sơ bộ, Chính phủ Pháp công nhận Việt Nam với địa vị nào?", "options": ["Một thuộc địa không có cơ quan tự quản", "Một nước đã gia nhập Liên hợp quốc", "Một quốc gia tự do có chính phủ, nghị viện, tài chính và quân đội riêng", "Một nước đã hoàn toàn thống nhất về mặt nhà nước trong năm 1946"], "answer": 2, "explanation": "Hiệp định ghi nhận Việt Nam là quốc gia tự do, nằm trong Liên bang Đông Dương thuộc khối Liên hiệp Pháp; không nên đánh đồng nội dung này với độc lập hoàn toàn.", "page": 141, "evidence": "Chính phủ Pháp công nhận Việt Nam là một quốc gia tự do, có chính phủ, nghị viện, tài chính và quân đội riêng nằm trong Liên bang Đông Đương thuộc khối Liên hiệp Pháp; Việt Nam đồng ý để 15.000 quân đội Pháp ra", "type": "mcq"}, {"id": "c2-q008", "section": "c2-s1", "prompt": "Chỉ thị Hòa để tiến ngày 9/3/1946 yêu cầu gì sau khi ký Hiệp định Sơ bộ?", "options": ["Ngừng mọi việc chuẩn bị kháng chiến", "Giải tán toàn bộ cơ sở Đảng", "Chấm dứt công tác đào tạo cán bộ quân sự", "Giữ cảnh giác và tiếp tục chuẩn bị kháng chiến"], "answer": 3, "explanation": "Hòa hoãn không có nghĩa là mất cảnh giác; Chỉ thị yêu cầu sẵn sàng kháng chiến bất cứ lúc nào.", "page": 141, "evidence": "tiếp tục nêu cao tinh thần cảnh giác cách mạng, không ngừng một phút công việc sửa soạn, sẵn sàng kháng chiến bất cứ lúc nào và nhất định không để cho việc đàm phán với Pháp làm nhụt tỉnh thần quyết chiến của dân tộc ta, nhất là đối với đồng bào Nam Bộ và các chiến sĩ ngoài mặt trận; cần đẩy mạnh công tác xây dựng Đảng, đặc biệt chú ý đào tạo cán bộ chính trị và quân sự, gây dựng cơ sở đáng, củng cố phong trào quần chúng.", "type": "mcq"}, {"id": "c2-q009", "section": "c2-s1", "prompt": "Bản Tạm ước do Chủ tịch Hồ Chí Minh ký với đại diện Chính phủ Pháp mang ngày nào?", "options": ["14/9/1946", "6/1/1946", "12/12/1946", "21/7/1954"], "answer": 0, "explanation": "Tạm ước 14/9/1946 tiếp tục thể hiện nỗ lực hòa bình và nhân nhượng có giới hạn.", "page": 142, "evidence": "ngày 14/9/1946, Chủ tịch Hồ Chí Minh đã ký với Marius Moutet (M. Mutê) - đại diện Chính phủ Pháp, bản Tạm ước 14/9 tại Mácxây (Marseil), đồng ý nhân nhượng thêm cho Pháp một số quyền lợi kinh tế, văn hóa ở Việt", "type": "mcq"}, {"id": "c2-q010", "section": "c2-s2", "prompt": "Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến vào ngày nào?", "options": ["11/2/1951", "19/12/1946", "25/11/1945", "15/10/1947"], "answer": 1, "explanation": "Ngày 19/12/1946, Lời kêu gọi khẳng định quyết tâm bảo vệ độc lập, tự do.", "page": 147, "evidence": "Ngày 19/12/1946, Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến, khẳng định quyết tâm sắt đá của nhân đân ta quyết kháng chiến đến cùng để bảo vệ nền độc lập, tự do: “Chúng ta muốn hòa bình, chúng ta", "type": "mcq"}, {"id": "c2-q011", "section": "c2-s2", "prompt": "Cuộc chiến đấu ở các đô thị cuối năm 1946, đầu năm 1947 có nhiệm vụ quan trọng nào?", "options": ["Đưa toàn bộ lực lượng trở lại hoạt động công khai trong nội thành", "Tập trung toàn bộ dân cư vào các vị trí quân Pháp kiểm soát", "Giam chân địch, bảo toàn lực lượng và bảo vệ cơ quan đầu não rút ra ngoài", "Giành thắng lợi cuối cùng ngay tại Hà Nội"], "answer": 2, "explanation": "Cuộc chiến đấu tạo thời gian và điều kiện cho cả nước chuẩn bị kháng chiến lâu dài.", "page": 149, "evidence": "Quân ta đã chống trả quyết liệt, đánh tiêu hao nhiều sinh lực địch, bảo vệ an toàn các eơ quan đầu não, lãnh đạo của Trung ương và nhân dân rút ra ngoại thành; hoàn thành nhiệm vụ giam chân địch trong thành phố, bước đầu làm thất bại kế hoạch đánh nhanh, thắng nhanh của thực dân Pháp; bảo toàn lực lượng, phát triển lực lượng chiến đấu thành một Trung đoàn chính quy mang tên “Trung đoàn Thủ đô”.", "type": "mcq"}, {"id": "c2-q012", "section": "c2-s2", "prompt": "Nội dung kháng chiến toàn dân nhấn mạnh điều gì?", "options": ["Chỉ quân đội chính quy tham gia chiến đấu", "Chỉ những địa phương ở tiền tuyến tham gia", "Tách quần chúng khỏi hoạt động kháng chiến", "Động viên toàn bộ sức dân, tài dân, lực dân tham gia kháng chiến"], "answer": 3, "explanation": "Toàn dân kháng chiến huy động mọi tầng lớp nhân dân, với Quân đội nhân dân làm nòng cốt.", "page": 150, "evidence": "Kháng chiến toàn dân là đem toàn bộ sức dân, tài dân, lực đân; động viên toàn dân tích cực tham gia kháng chiến. Xây dựng sự đồng thuận, nhất trí của cả nước, đánh địch ở mọi nơi, mọi lúc, “mỗi người dân là một", "type": "mcq"}, {"id": "c2-q013", "section": "c2-s2", "prompt": "Kháng chiến toàn diện được hiểu như thế nào?", "options": ["Đấu tranh trên các mặt quân sự, chính trị, kinh tế, văn hóa, tư tưởng và ngoại giao", "Chỉ tập trung vào mặt trận ngoại giao", "Chỉ tiến hành tác chiến quân sự", "Dừng xây dựng kinh tế, văn hóa và xã hội"], "answer": 0, "explanation": "Toàn diện là đánh địch trên mọi lĩnh vực; đấu tranh vũ trang giữ vai trò mũi nhọn, mang tính quyết định.", "page": 150, "evidence": "Kháng chiến toàn diện là đánh địch trên mọi lĩnh vực, mọi mặt trận không chỉ bằng quân sự mà cả về chính trị, kinh tế, văn hóa, tư tưởng, ngoại giao, trong đó mặt trận quân sự, đấu tranh vũ trang giữ vai trò mũi nhọn, mang tính quyết định.", "type": "mcq"}, {"id": "c2-q014", "section": "c2-s2", "prompt": "Vì sao đường lối kháng chiến nhấn mạnh tính lâu dài?", "options": ["Để không cần xây dựng lực lượng kháng chiến", "Để vừa tiêu hao địch vừa phát triển lực lượng ta, chuyển biến tương quan lực lượng", "Để kéo dài chiến tranh vô thời hạn", "Để từ bỏ thời cơ giành thắng lợi"], "answer": 1, "explanation": "Trường kỳ kháng chiến nhằm chuyển yếu thành mạnh; vẫn phải tranh thủ thời cơ để giành thắng lợi.", "page": 151, "evidence": "Trường kỳ kháng chiến là một quá trình vừa đánh tiêu hao lực lượng địch, vừa xây dựng, phát triển lực lượng ta, từng bước làm chuyển biến so sánh lực lượng trên chiến trường có lợi cho ta; lấy thời gian là lực ", "type": "mcq"}, {"id": "c2-q015", "section": "c2-s2", "prompt": "Kháng chiến dựa vào sức mình là chính có loại trừ sự giúp đỡ quốc tế không?", "options": ["Không; vì hoàn toàn phụ thuộc vào viện trợ", "Có; phải chấm dứt mọi quan hệ ngoại giao", "Không; lấy nội lực làm chủ yếu đồng thời tranh thủ giúp đỡ quốc tế", "Có; phải từ chối mọi sự ủng hộ bên ngoài"], "answer": 2, "explanation": "Giáo trình kết hợp phát huy nội lực với tìm kiếm, sử dụng hiệu quả sự ủng hộ quốc tế.", "page": 151, "evidence": "Kháng chiến dựa vào sức mình là chính, là sự kế thừa tư tưởng chiến lược trong chỉ đạo sự nghiệp cách mạng giải phóng dân tộc, giành chính quyền của lãnh tụ Hồ Chí Minh. Phải lấy nguồn nội lực của dân tộc, phát huy nguồn sức mạnh vật chất, tình thần trong nhân dân ta làm chỗ dựa chủ yếu, nguồn lực chủ yếu của cuộc chiến tranh nhân dân. Trên cơ sở đó, tìm kiếm, phát huy cao độ và có hiệu quả sự ủng hộ, giúp đỡ tỉnh thần và vật chất của quốc tế khi có điều kiện. Lấy độc lập, tự chủ về đường lối là yếu tố quan trọng hàng đầu.", "type": "mcq"}, {"id": "c2-q016", "section": "c2-s2", "prompt": "Thắng lợi Việt Bắc thu đông 1947 có ý nghĩa nổi bật nào?", "options": ["Kết thúc hoàn toàn cuộc kháng chiến chống Pháp", "Giải phóng toàn bộ miền Nam", "Buộc Mỹ ký Hiệp định Pari", "Bảo toàn cơ quan đầu não và căn cứ địa, đánh bại kế hoạch đánh nhanh thắng nhanh của Pháp"], "answer": 3, "explanation": "Chiến thắng bảo vệ căn cứ Việt Bắc và làm thất bại ý đồ kết thúc chiến tranh nhanh của Pháp.", "page": 154, "evidence": "Ta đã bảo toàn được cơ quan đầu não và căn cứ địa kháng chiến, đánh bại âm mưu, kế hoạch đánh nhanh, thắng nhanh của thực dân Pháp. Phối hợp với mặt trận chính, Đảng đã chỉ đạo quân dân vùng tạm bị chiếm đẩy mạnh kháng chiến, ra sức đánh phá chính quyển địch, điệt tể, trừ gian, trừng trị 154", "type": "mcq"}, {"id": "c2-q017", "section": "c2-s2", "prompt": "Ý nghĩa trực tiếp nổi bật của Chiến dịch Biên giới thu đông 1950 là gì?", "options": ["Phá thế bị bao vây, mở ra cục diện phát triển mới cho kháng chiến", "Kết thúc sự chia cắt hai miền sau năm 1954", "Giải phóng Sài Gòn và thống nhất đất nước", "Hoàn thành Kế hoạch nhà nước 5 năm lần thứ nhất"], "answer": 0, "explanation": "Chiến thắng Biên giới kết thúc thời kỳ chiến đấu trong vòng vây, đưa kháng chiến phát triển cao hơn.", "page": 160, "evidence": "kết thúc thời kỳ chiến đấu trong vòng vây”. Chiến thắng này đã mở ra cục điện mới, đưa cuộc kháng chiến chuyển sang giai đoạn phát triển cao hơn. 3. Đẩy mạnh cuộc kháng chiến đến thắng lợi (1951 - 1954) a) Đại ", "type": "mcq"}, {"id": "c2-q018", "section": "c2-s3", "prompt": "Đại hội đại biểu lần thứ II của Đảng họp tháng 2/1951 ở tỉnh nào?", "options": ["Bến Tre", "Tuyên Quang", "Hà Nội", "Tây Ninh"], "answer": 1, "explanation": "Đại hội họp tại xã Vĩnh Quang, nay là Kim Bình, huyện Chiêm Hóa, tỉnh Tuyên Quang.", "page": 160, "evidence": "Đại hội đại biểu lần thứ II của Đẳng họp từ ngày 11 đến ngày 19/2/1951, tại xã Vĩnh Quang (nay là Kim Bình), huyện Chiêm Hóa, tỉnh Tuyên Quang. Tham dự Đại hội có 158 đại biểu chính thức, ð3 đại biểu dự khuyết,", "type": "mcq"}, {"id": "c2-q019", "section": "c2-s3", "prompt": "Đại hội II quyết định Đảng ở Việt Nam ra hoạt động công khai với tên gọi nào?", "options": ["An Nam Cộng sản Đảng", "Đảng Nhân dân Lào", "Đảng Lao động Việt Nam", "Đông Dương Cộng sản Đảng"], "answer": 2, "explanation": "Đại hội quyết định mỗi nước Đông Dương cần có đảng riêng; ở Việt Nam là Đảng Lao động Việt Nam.", "page": 161, "evidence": "Ở Việt Nam, Đảng ra hoạt động công khai, lấy tên là Đảng Lao động Việt Nam'. Báo cáo chính trị do Chủ tịch Hồ Chí Minh trình bày tại Đại hội đã tổng kết phong trào cách mạng thế giới và cách mạng Việt Nam trong", "type": "mcq"}, {"id": "c2-q020", "section": "c2-s3", "prompt": "Theo Chính cương năm 1951, những giai cấp nào là động lực của cách mạng Việt Nam?", "options": ["Công nhân, nông dân, địa chủ phản động và tư sản mại bản", "Nông dân, tiểu tư sản, tư sản mại bản và đế quốc", "Công nhân, tư sản mại bản, địa chủ phản động và đế quốc", "Công nhân, nông dân, tiểu tư sản và tư sản dân tộc"], "answer": 3, "explanation": "Chính cương xác định bốn giai cấp, đồng thời tranh thủ thân sĩ yêu nước, tiến bộ; giai cấp công nhân giữ vai trò lãnh đạo.", "page": 163, "evidence": "Động lực của cách mạng Việt Nam được xác định gồm có bốn giai cấp là: công nhân, nông dân, tiểu tư sản và tư sản dân tộc, ngoài ra còn có những thân sĩ (thân hào, địa chủ) yêu nước và tiến bộ, Trong đó, lấy nền", "type": "mcq"}, {"id": "c2-q021", "section": "c2-s3", "prompt": "Chính cương năm 1951 xác định nhiệm vụ chính lúc đó là gì?", "options": ["Đấu tranh chống xâm lược, hoàn thành giải phóng dân tộc", "Hoàn thành ngay chủ nghĩa xã hội trên cả nước", "Từ bỏ nhiệm vụ thống nhất dân tộc", "Chỉ tập trung phát triển kinh tế tư bản tư doanh"], "answer": 0, "explanation": "Các nhiệm vụ có quan hệ khăng khít, nhưng nhiệm vụ chính là giải phóng dân tộc.", "page": 163, "evidence": "nhiệm vụ chính lúc này là tập trung đấu tranh chống xâm lược, hoàn thành công cuộc giải phóng dân tộc. - Động lực của cách mạng Việt Nam được xác định gồm có bốn giai cấp là: công nhân, nông dân, tiểu tư sản và", "type": "mcq"}, {"id": "c2-q022", "section": "c2-s3", "prompt": "Kế hoạch Nava dự kiến thực hiện trong bao lâu để tìm cách chuyển bại thành thắng?", "options": ["10 năm", "18 tháng", "3 tháng", "5 năm"], "answer": 1, "explanation": "Kế hoạch Nava dự kiến trong 18 tháng, tập trung binh lực để tìm một thắng lợi quân sự quyết định.", "page": 169, "evidence": "Kế hoạch Nava dự kiến thực hiện trong vòng 18 tháng nhằm “chuyển bại thành thắng”. Nava chủ trương tăng cường tập trung bình lực, hình thành những “quả đấm thép” để quyết chiến với chủ lực của Việt Minh. Chi phí vật chất của kế hoạch Nava phần lớn đo Mỹ thực hiện.", "type": "mcq"}, {"id": "c2-q023", "section": "c2-s3", "prompt": "Ai được giao trực tiếp làm Tư lệnh kiêm Bí thư Đảng ủy Chiến dịch Điện Biên Phủ?", "options": ["Đồng chí Tôn Đức Thắng", "Đồng chí Nguyễn Lương Bằng", "Đại tướng Võ Nguyên Giáp", "Đồng chí Nguyễn Hữu Thọ"], "answer": 2, "explanation": "Bộ Chính trị giao Đại tướng Võ Nguyên Giáp trực tiếp chỉ huy chiến dịch.", "page": 170, "evidence": "giao Đại tướng Võ Nguyên Giáp - Bộ trưởng Bộ Quốc phòng, Tổng Tư lệnh quân đội trực tiếp làm Tư lệnh kiêm Bí thư Đảng ủy chiến địch. Phối hợp với mặt trận Điện Biên Phủ và tạo điều kiện cho trận quyết chiến chiến lược ở Điện Biên Phủ, lực lượng quân sự tổ chức nghi binh, kéo đấn lực lượng địch trên toàn chiến trường Đông Dương, mở nhiều cuộc tấn công địch đồng loạt trên các hướng chiến lược quan trọng, như: Lai Châu (12/1958); Trung Lào (12/1953), Hạ Lào và Đông Bắc Campuchia (12/1953); mặt trận Tây Nguyên (1/1954); Thượng Lào (1/1954).", "type": "mcq"}, {"id": "c2-q024", "section": "c2-s3", "prompt": "Phương châm tác chiến được thực hiện trong Chiến dịch Điện Biên Phủ là gì?", "options": ["Đánh nhanh bằng mọi giá", "Chỉ bao vây mà không tiến công", "Không tập trung lực lượng chủ lực", "Đánh chắc, tiến chắc"], "answer": 3, "explanation": "Giáo trình nêu phương châm đánh chắc, tiến chắc, đánh chắc thắng.", "page": 171, "evidence": "Với phương châm “đánh chắc, tiến chắc”, “đánh chắc thắng” ngày 13/3/1954, 1. Chỉ thị của Chủ tịch Hồ Chí Minh cho Đại tướng Võ Nguyên Giáp (12/1958), 171", "type": "mcq"}, {"id": "c2-q025", "section": "c2-s3", "prompt": "Chiến dịch Điện Biên Phủ kết thúc thắng lợi vào ngày nào?", "options": ["7/5/1954", "19/12/1946", "21/7/1954", "30/4/1975"], "answer": 0, "explanation": "Sau 56 ngày đêm với ba đợt tiến công lớn, quân ta đánh chiếm hầm chỉ huy chiều 7/5/1954.", "page": 172, "evidence": "Trải qua 56 ngày đêm, với 3 đợt tiến công lớn, đến 17 giờ 30 phút chiều 7/5/1954, Quân đội nhân dân Việt Nam đã đánh chiếm hầm chỉ huy, bắt sống tướng Đờ Cátơri (Chiristian de Castries), Chỉ huy trưởng và Bộ Chỉ huy tập đoàn cứ điểm Điện Biên Phủ.", "type": "mcq"}, {"id": "c2-q026", "section": "c2-s3", "prompt": "Hiệp định đình chỉ chiến sự ở Việt Nam tại Hội nghị Giơnevơ được ký vào ngày nào theo giáo trình?", "options": ["6/3/1946", "21/7/1954", "8/5/1954", "27/1/1973"], "answer": 1, "explanation": "Theo giáo trình, Việt Nam đồng ý ký với Pháp Hiệp định đình chỉ chiến sự ngày 21/7/1954.", "page": 174, "evidence": "nên ta đồng ý chấp nhận ký kết với Pháp bản Hiệp định đình chỉ chiến sự ở Việt Nam vào ngày 21/7/1954. Trong quá trình diễn ra Hội nghị, Mỹ đã gây sức ép buộc Pháp chấp nhận đưa Ngô Đình Diệm về nước làm Thủ tướng trong chính quyền Bảo Đại nhằm xây đựng một chính quyền thân Mỹ thay thế chính quyền thân Pháp.", "type": "mcq"}, {"id": "c2-q027", "section": "c2-s4", "prompt": "Thắng lợi kháng chiến chống Pháp tạo tiền đề trực tiếp nào cho cách mạng Việt Nam?", "options": ["Kết thúc mọi nhiệm vụ giải phóng miền Nam", "Hoàn tất cải tạo xã hội chủ nghĩa trên cả nước", "Giải phóng hoàn toàn miền Bắc, tạo điều kiện đưa miền Bắc quá độ lên chủ nghĩa xã hội", "Hoàn thành ngay thống nhất nhà nước trong năm 1954"], "answer": 2, "explanation": "Miền Bắc được giải phóng và trở thành hậu phương lớn cho sự nghiệp giải phóng miền Nam.", "page": 175, "evidence": "Thắng lợi của cuộc kháng chiến đưa đến việc giải phóng hoàn toàn miền Bắc, tạo tiền đề về chính trị - xã hội quan trọng để Đảng quyết định đưa miền Bắc quá độ lên chủ nghĩa xã hội, xây dựng, bảo vệ vững chắc miền Bắc thành hậu phương lớn, chỉ viện cho tiền tuyến lớn miền Nam.", "type": "mcq"}, {"id": "c2-q028", "section": "c2-s5", "prompt": "Nhiệm vụ chủ yếu trước mắt của miền Bắc được Bộ Chính trị nêu tháng 9/1954 là gì?", "options": ["Chấm dứt mọi hoạt động sản xuất nông nghiệp", "Tiến hành ngay cuộc Tổng tiến công mùa xuân 1975", "Chỉ phát triển kinh tế đối ngoại, không ổn định đời sống", "Hàn gắn vết thương chiến tranh và phục hồi kinh tế, trước hết là nông nghiệp"], "answer": 3, "explanation": "Khôi phục sản xuất và ổn định đời sống là nhiệm vụ cấp thiết sau chín năm chiến tranh.", "page": 182, "evidence": "Tháng 9/1954, Bộ Chính trị đề ra nhiệm vụ chủ yếu trước mắt của miền Bắc là hàn gắn vết thương chiến tranh, phục hồi kinh tế quốc dân, trước hết là phục hồi và phát triển sản xuất nông nghiệp, ổn định xã hội, ổn định đời sống nhân dân, tăng cường và mở rộng hoạt động quan hệ quốc tế.", "type": "mcq"}, {"id": "c2-q029", "section": "c2-s5", "prompt": "Đảng đã xử lý những sai lầm trong cải cách ruộng đất bằng cách nào được giáo trình nêu?", "options": ["Kiểm điểm, công khai tự phê bình và chỉ đạo sửa sai", "Phủ nhận hoàn toàn sự tồn tại của sai lầm", "Đình chỉ mọi việc khắc phục hậu quả", "Chỉ thay đổi tên gọi của chính sách"], "answer": 0, "explanation": "Giáo trình nêu việc kiểm điểm nghiêm khắc, tự phê bình và tổ chức sửa sai có kế hoạch.", "page": 185, "evidence": "đã nghiêm khắc kiểm điểm những sai lầm trong cải cách ruộng đất và chỉnh đến tể chức, công khai tự phê bình trước nhân dân, thi hành kỷ luật đối với một số Ủy viên Bộ Chính trị và Ủy viên Trung ương Đảng. Công ", "type": "mcq"}, {"id": "c2-q030", "section": "c2-s5", "prompt": "Nghị quyết Trung ương 15 năm 1959 xác định phương hướng đấu tranh ở miền Nam như thế nào?", "options": ["Chuyển toàn bộ lực lượng vào sản xuất công nghiệp", "Kết hợp lực lượng chính trị và vũ trang, đấu tranh chính trị với quân sự", "Chỉ đấu tranh nghị trường, không xây dựng lực lượng", "Chỉ chờ tổng tuyển cử mà không đấu tranh"], "answer": 1, "explanation": "Nghị quyết mở đường cho khởi nghĩa từng phần, sử dụng bạo lực cách mạng để giành chính quyền về tay nhân dân.", "page": 191, "evidence": "Tháng 1/1959, Hội nghị Trung ương 15 (mở rộng) đã ra nghị quyết về tình hình cách mạng miền Nam với tỉnh thần cơ bản là tiếp tục cuộc cách mạng dân tộc dân chủ nhân dân, sử dụng bạo lực cách mạng với hai lực lượng chính trị và vũ trang, kết hợp đấu tranh chính trị với đấu tranh quân sự, tiến tới khỏi nghĩa vũ tranh giành chính quyền về tay nhân dân... Nghị quyết 15 đã vạch rõ phương hướng tiến lên cho cách mạng miền Nam, tạo đà cho cuộc khởi nghĩa từng phần nổ ra ngày càng rộng lớn.", "type": "mcq"}, {"id": "c2-q031", "section": "c2-s5", "prompt": "Phong trào Đồng khởi ở Bến Tre bùng nổ vào ngày nào?", "options": ["2/1/1963", "30/4/1975", "17/1/1960", "20/12/1960"], "answer": 2, "explanation": "Đồng khởi bùng nổ tại huyện Mỏ Cày, Bến Tre ngày 17/1/1960 và nhanh chóng lan rộng.", "page": 191, "evidence": "Ngày 17/1/1960, ở Bến Tre, hình thức khởi nghĩa đồng loạt (đồng khỏi) bùng nổ do đồng chí Nguyễn Thị Định lãnh đạo ổ huyện Mô Cày, 191", "type": "mcq"}, {"id": "c2-q032", "section": "c2-s5", "prompt": "Ý nghĩa bước ngoặt của phong trào Đồng khởi là gì?", "options": ["Kết thúc hoàn toàn cuộc kháng chiến chống Mỹ", "Mở đầu kháng chiến toàn quốc chống Pháp", "Hoàn thành thống nhất nhà nước", "Chuyển cách mạng miền Nam từ giữ gìn lực lượng sang thế tiến công"], "answer": 3, "explanation": "Đồng khởi tạo bước nhảy vọt, đưa cách mạng miền Nam sang thế tiến công.", "page": 192, "evidence": "chuyển cách mạng miền Nam từ thế giữ gìn lực lượng sang thế tiến công, từ khởi nghĩa từng phần sang chiến tranh cách mạng chống chủ nghĩa thực dân mới của Mỹ. 192", "type": "mcq"}, {"id": "c2-q033", "section": "c2-s5", "prompt": "Mặt trận Dân tộc giải phóng miền Nam Việt Nam được thành lập vào ngày nào?", "options": ["20/12/1960", "25/11/1945", "19/12/1946", "27/1/1973"], "answer": 0, "explanation": "Mặt trận được thành lập tại Tân Lập, Tây Ninh ngày 20/12/1960, do Nguyễn Hữu Thọ làm Chủ tịch.", "page": 192, "evidence": "ngày 20/12/1960, tại xã Tân Lập (Tây Ninh), Mặt trận Dân tộc giải phóng miền Nam Việt Nam được thành lập do Luật sư Nguyễn Hữu Thọ làm Chủ tịch, tập hợp rộng rãi quần chúng nhân dân đoàn kết đấu tranh theo chương trình thuộc địa trá hình của đế quốc Mỹ và chính quyền độc tài Ngô Đình Diệm, xây dựng một miền Nam độc lập, dân chủ, hoà bình, trung lập, tiến tới thống nhất nước nhà.", "type": "mcq"}, {"id": "c2-q034", "section": "c2-s6", "prompt": "Đại hội III năm 1960 xác định đồng thời hai chiến lược cách mạng nào?", "options": ["Chỉ đấu tranh ngoại giao trên cả nước", "Cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam", "Cách mạng tư sản ở cả hai miền", "Chỉ xây dựng kinh tế ở miền Bắc, không tiến hành cách mạng miền Nam"], "answer": 1, "explanation": "Hai chiến lược khác nhau về nhiệm vụ cụ thể nhưng cùng hướng tới thống nhất đất nước.", "page": 193, "evidence": "phải thực hiện đồng thời hai chiến lược cách mạng khác nhau ở hai miền: Một là, đẩy mạnh cách mạng xã hội chủ nghĩa ở miền Bắc; Hai là, tiến hành cách mạng dân tộc dân chủ nhân dân ở miền Nam, thực 1, Hồ Chí Minh: Toàn tập, Sđd, t.", "type": "mcq"}, {"id": "c2-q035", "section": "c2-s6", "prompt": "Đại hội III xác định quan hệ về vai trò của cách mạng hai miền như thế nào?", "options": ["Hai miền hoàn toàn tách rời, không hỗ trợ nhau", "Miền Bắc chỉ có vai trò ngoại giao", "Miền Bắc quyết định nhất đối với toàn bộ cách mạng; miền Nam quyết định trực tiếp đối với giải phóng miền Nam", "Miền Nam quyết định nhất, miền Bắc không có vai trò"], "answer": 2, "explanation": "Cần phân biệt quyết định nhất của cách mạng miền Bắc với quyết định trực tiếp của cách mạng miền Nam.", "page": 194, "evidence": "nên giữ vai trò quyết định nhất đối với sự phát triển của toàn bộ cách mạng Việt Nam và đối với sự nghiệp thống nhất nước nhà. Còn cách mạng dân tộc dân chủ nhân đân ở miền Nam giữ vai trò quyết định trực tiếp đối với sự nghiệp giải phóng miền Nam khỏi ách thống trị của đế quốc Mỹ và bè 1ñ tay sai, thực hiện hòa bình, thống nhất nước nhà. Về hòa bình, thống nhất Tổ quốc, Đại hội chủ trương kiên quyết giữ vững đường lối hòa bình để thống nhất nước nhà, vì chủ trương đó phù hợp với nguyện vọng và lợi ích của nhân dân cả nước cũng như của nhân dân yêu chuộng hòa bình thế giới.", "type": "mcq"}, {"id": "c2-q036", "section": "c2-s6", "prompt": "Kế hoạch nhà nước 5 năm lần thứ nhất ở miền Bắc được thực hiện trong thời gian nào?", "options": ["1945–1950", "1954–1956", "1976–1980", "1961–1965"], "answer": 3, "explanation": "Kế hoạch 1961–1965 nhằm xây dựng bước đầu cơ sở vật chất, kỹ thuật của chủ nghĩa xã hội.", "page": 198, "evidence": "5 năm lần thứ nhất (1961 - 1965) nhằm xây dựng bước đầu cơ số vật chất - kỹ thuật của chủ nghĩa xã hội, thực hiện một bước công nghiệp hóa xã hội chủ nghĩa và hoàn thành công cuộc cải tạo xã hội chủ nghĩa, tiếp", "type": "mcq"}, {"id": "c2-q037", "section": "c2-s6", "prompt": "Đặc điểm lực lượng của chiến lược Chiến tranh đặc biệt là gì?", "options": ["Cố vấn, vũ khí Mỹ kết hợp quân chủ lực Việt Nam Cộng hòa", "Quân Mỹ trực tiếp giữ vai trò chủ yếu trên chiến trường", "Không sử dụng quân đội Sài Gòn", "Chỉ dùng không quân, không sử dụng bộ binh"], "answer": 0, "explanation": "Giáo trình phân biệt công thức của Chiến tranh đặc biệt với việc quân chiến đấu Mỹ trực tiếp tham chiến trong Chiến tranh cục bộ.", "page": 201, "evidence": "cố vấn, vũ khí Mỹ và quân chủ lực Việt Nam Cộng hòa”, Mỹ và ngụy quyền Ngô Đình Diệm triển khai thực hiện kế hoạch bình định miền Nam trong vòng 18 tháng, đự định lập 17.000 ấp chiến lược là “quốc sách”. Chúng ", "type": "mcq"}, {"id": "c2-q038", "section": "c2-s6", "prompt": "Ba mũi giáp công trong đấu tranh ở miền Nam gồm những mũi nào?", "options": ["Không quân, hải quân và tên lửa", "Quân sự, chính trị và binh vận", "Kinh tế, giáo dục và y tế", "Ngoại giao, thương mại và tài chính"], "answer": 1, "explanation": "Ba mũi giáp công kết hợp trên các vùng chiến lược để phát huy sức mạnh tổng hợp.", "page": 201, "evidence": "ba mũi giáp công: quân sự, chính trị và binh vận. Trên thực tế, đây là quyết định chuyển cuộc đấu tranh của nhân dân miền Nam từ khởi nghĩa từng phần sang chiến tranh cách mạng và chỉ rõ những nhiệm 201", "type": "mcq"}, {"id": "c2-q039", "section": "c2-s6", "prompt": "Chiến thắng Ấp Bắc diễn ra vào ngày nào?", "options": ["7/5/1954", "27/1/1973", "2/1/1963", "17/1/1960"], "answer": 2, "explanation": "Chiến thắng Ấp Bắc, Mỹ Tho ngày 2/1/1963 thể hiện hiệu quả kết hợp đấu tranh vũ trang, chính trị và binh vận.", "page": 202, "evidence": "Chiến thắng vang dội ở Ấp Bắc (Mỹ Tho) ngày 2/1/1963 đã thể hiện sức mạnh và hiệu quả của 1. Đảng bộ miền Nam của Đảng có danh nghĩa công khai là Đảng Nhân đân cách mạng miền Nam Việt Nam. 202", "type": "mcq"}, {"id": "c2-q040", "section": "c2-s7", "prompt": "Lực lượng nào giữ vai trò chủ yếu trên chiến trường miền Nam trong Chiến tranh cục bộ?", "options": ["Chỉ lực lượng cố vấn Mỹ", "Chỉ dân quân địa phương Việt Nam Cộng hòa", "Chỉ lực lượng cảnh sát đô thị", "Quân chiến đấu Mỹ và quân đồng minh trực tiếp tham chiến"], "answer": 3, "explanation": "Khác Chiến tranh đặc biệt, Chiến tranh cục bộ đưa quân chiến đấu Mỹ và đồng minh trực tiếp tham chiến.", "page": 205, "evidence": "Trước nguy cơ thất bại hoàn toàn của chiến lược “Chiến tranh đặc biệt, để cứu vấn cơ đồ chủ nghĩa thực dân mới, ngăn chặn sự sụp đổ của chính quyền và quân đội Sài Gòn, chính quyền của Tổng thống Mỹ L. Giônxơn quyết định tiến hành chiến lược “Chiến tranh cục bộ” (Local War Strategy) ở miền Nam. “Chiến tranh cục bộ” là một hình thức chiến tranh trong chiến lược toàn cẩu “Phản ứng linh hoạ? của đế quốc Mỹ, mục đích là đưa quân chiến đấu Mỹ và quân các nước đồng minh của Mỹ", "type": "mcq", "sourcePages": [205, 206], "evidenceExtra": [{"page": 206, "evidence": "vào trực tiếp tham chiến, đóng vai trò chủ yếu trên chiến trường miền.Nam; quân đội Sài Gòn đóng vai trò hỗ trợ quân Mỹ và thực hiện bình định."}]}, {"id": "c2-q041", "section": "c2-s7", "prompt": "Nghị quyết Trung ương 11 và 12 năm 1965 tiếp tục giương cao hai ngọn cờ nào?", "options": ["Độc lập dân tộc và chủ nghĩa xã hội", "Chủ nghĩa thực dân và quân chủ", "Tự do thương mại và bảo hộ kinh tế", "Trung lập quân sự và từ bỏ thống nhất"], "answer": 0, "explanation": "Đường lối tiếp tục đồng thời hai chiến lược cách mạng, quyết tâm giải phóng miền Nam, thống nhất Tổ quốc.", "page": 209, "evidence": "hai ngọn cờ độc lập dân tộc và chủ nghĩa xã hội, tiếp tục tiến hành đồng thời hai chiến lược cách mạng của Đảng và quyết tâm đánh thắng giặc Mỹ xâm lược, giải phóng miền Nam, thống nhất Tổ quốc của dân tộc ta. ", "type": "mcq"}, {"id": "c2-q042", "section": "c2-s7", "prompt": "Trong kháng chiến chống Mỹ, quan hệ giữa hai miền được khái quát như thế nào?", "options": ["Hai miền không có quan hệ chi viện", "Miền Bắc là hậu phương lớn, miền Nam là tiền tuyến lớn", "Miền Bắc là tiền tuyến lớn, miền Nam là hậu phương lớn", "Hai miền đều không làm nhiệm vụ hậu phương"], "answer": 1, "explanation": "Bảo vệ, xây dựng miền Bắc gắn chặt với chi viện và giải phóng miền Nam.", "page": 208, "evidence": "miền Nam là tiền tuyến lớn, miền Bắc là hậu phương lớn. Phải nắm vững mối quan hệ giữa nhiệm vụ bảo vệ miền Bắc và giải phóng miền Nam. Bảo vệ miền Bắc là nhiệm vụ của cả nước, vì miền Bắc xã hội chủ nghĩa là thành quả chung rất to lớn của nhân dân cả nước ta, là hậu phương vững chắc trong cuộc chiến tranh chống Mỹ.", "type": "mcq"}, {"id": "c2-q043", "section": "c2-s7", "prompt": "Phong trào nào tiêu biểu cho thanh niên miền Bắc trong cao trào chống Mỹ, cứu nước?", "options": ["Bình dân học vụ", "Tuần lễ vàng", "Ba sẵn sàng", "Đồng khởi"], "answer": 2, "explanation": "Giáo trình nêu thanh niên có phong trào Ba sẵn sàng, phụ nữ có phong trào Ba đảm đang.", "page": 211, "evidence": "Thanh niên có phong trào “Ba sẵn sàng” phụ nữ có phong trào “Ba đảm đang” nông dân có phong trào “Tay cày, tay súng”, công nhân có phong trào “Fay búa, tay súng”, trong chiến đấu có “Nhằm thẳng quân thù mà bắn”", "type": "mcq"}, {"id": "c2-q044", "section": "c2-s7", "prompt": "Chiến thắng Vạn Tường năm 1965 gắn với cuộc đấu tranh chống chiến lược nào?", "options": ["Kế hoạch Nava", "Chiến tranh đơn phương", "Việt Nam hóa chiến tranh", "Chiến tranh cục bộ"], "answer": 3, "explanation": "Vạn Tường là một trong những thắng lợi khi quân dân miền Nam trực tiếp đánh quân chiến đấu Mỹ.", "page": 214, "evidence": "chống lại chiến lược “Chiến tranh cục bộ” của Mỹ và tay sai. Quân và dân miền Nam đã đánh thắng quân chiến đấu Mỹ ở Núi Thành (5/1965), Vạn Tường (8/1965), Plâyme (11/1965)... bể gẫy cuộc phản công chiến lược mùa khô 1965 - 1966, làm thất bại kế hoạch “tìm diệt và “bình định” nhằm giành quyền chủ động trên chiến trường của quân Mỹ và quân đội Sài Gòn.", "type": "mcq"}, {"id": "c2-q045", "section": "c2-s7", "prompt": "Hội nghị Trung ương 13 tháng 1/1967 quyết định mở thêm mặt trận nào?", "options": ["Ngoại giao, tạo cục diện vừa đánh vừa đàm", "Chỉ sản xuất lương thực", "Chỉ đấu tranh nghị trường ở Quốc hội Pháp", "Chỉ đấu tranh văn hóa"], "answer": 0, "explanation": "Mở mặt trận ngoại giao nhằm tranh thủ quốc tế và phát huy sức mạnh tổng hợp.", "page": 216, "evidence": "ngày 28/1/1967, Hội nghị lần thứ 13 Ban Chấp hành Trung ương Đảng khóa TII đã quyết định mỏ mặt trận ngoại giao nhằm tranh thủ sự ủng hộ của quốc tế, bè bạn, mở ra cục diện vừa đánh, vừa đàm, phát huy sức mạnh ", "type": "mcq"}, {"id": "c2-q046", "section": "c2-s7", "prompt": "Tổng tiến công và nổi dậy Tết Mậu Thân 1968 tác động thế nào đến chiến lược của Mỹ?", "options": ["Dẫn đến thành lập Quốc hội đầu tiên năm 1946", "Góp phần làm phá sản Chiến tranh cục bộ, buộc Mỹ chấp nhận đàm phán ở Pari", "Khiến Mỹ hoàn thành mục tiêu bình định miền Nam", "Làm chấm dứt ngay mọi chiến sự trong năm 1968"], "answer": 1, "explanation": "Giáo trình đánh giá đây là bước ngoặt, khởi đầu quá trình đi đến thất bại hoàn toàn của Mỹ và chính quyền Sài Gòn.", "page": 218, "evidence": "Chiến lược “Chiến tranh cục bộ” của đế quốc Mỹ phá sản, Mỹ buộc phải chấp nhận đàm phán với Việt Nam tại Hội nghị Pari (Pháp) từ ngày 13/5/1968. Phái đoàn đàm phán của Chính phủ Việt Nam Dân chủ Cộng hòa do Bộ ", "type": "mcq"}, {"id": "c2-q047", "section": "c2-s7", "prompt": "Giáo trình nêu hạn chế nào trong chỉ đạo sau đợt tiến công Tết Mậu Thân 1968?", "options": ["Từ bỏ toàn bộ hoạt động ngoại giao", "Chỉ tập trung phát triển nông nghiệp ở miền Nam", "Chủ quan trong đánh giá tình hình và tiếp tục tiến công đô thị khi không còn yếu tố bất ngờ", "Không tổ chức bất kỳ đợt tiến công nào"], "answer": 2, "explanation": "Giáo trình nhìn nhận cả thắng lợi và hạn chế, nhất là việc chưa rút kinh nghiệm và đánh giá đúng tương quan lực lượng.", "page": 219, "evidence": "đã có biểu hiện chủ quan trong việc đánh giá tình hình, để ra yêu cầu chưa sát với thực tế, Đặc biệt là sau đợt tấn công trong Tết Mậu Thân, ta đã không kiểm điểm, rút kinh nghiệm kịp thời, không đánh giá đúng ", "type": "mcq"}, {"id": "c2-q048", "section": "c2-s7", "prompt": "Thủ đoạn chủ yếu của chiến lược Việt Nam hóa chiến tranh là gì?", "options": ["Loại bỏ hoàn toàn quân đội Sài Gòn", "Chấm dứt mọi can thiệp vào Việt Nam ngay lập tức", "Chỉ tiến hành chiến tranh bằng quân Pháp", "Dùng người Việt Nam đánh người Việt Nam"], "answer": 3, "explanation": "Mỹ tìm cách tiếp tục chiến tranh thực dân mới thông qua củng cố chính quyền và quân đội Sài Gòn.", "page": 224, "evidence": "dùng người Việt Nam đánh người Việt Nam” để tiếp tục cuộc chiến tranh xâm lược thực dân mới của Mỹ ở miền Nam. Quá trình triển khai chiến lược mới, Mỹ đã áp dụng một loạt biện pháp như: ra sức củng cố ngụy quyền, xây dựng ngụy quân đông và hiện đại; ráo riết thực hiện chương trình bình định; tiến hành chiến tranh phá hoại miền Bắc nhằm chặn đứng sự chỉ viện cho miền Nam; tìm mọi cách thỏa hiệp với Trung Quốc, hòa hoãn với Liên Xô hòng cắt giảm nguồn viện trợ chủ yếu của Việt Nam.", "type": "mcq"}, {"id": "c2-q049", "section": "c2-s7", "prompt": "Thắng lợi Đường 9 – Nam Lào năm 1971 gắn với việc đánh bại cuộc hành quân nào?", "options": ["Lam Sơn 719", "Nava", "Linebacker II", "Hirondelle"], "answer": 0, "explanation": "Quân dân Việt Nam phối hợp với quân dân Lào đánh bại Lam Sơn 719, bảo vệ tuyến chi viện chiến lược.", "page": 226, "evidence": "Năm 1971, quân và dân Việt Nam phối hợp với quân và dân Lào chủ động đánh bại cuộc hành quân quy mô lớn “Lam Sơn 719” của Mỹ - ngụy đánh vào Đường 9 - Nam Lào nhằm cắt đứt đường mòn Hồ Chí Minh, cắt đứt con đường tiếp tế quan trọng của miền Bắc đối với miền Nam và phong trào kháng chiến Campuchia.", "type": "mcq"}, {"id": "c2-q050", "section": "c2-s7", "prompt": "Cuộc tiến công chiến lược năm 1972 bắt đầu từ hướng chủ yếu nào?", "options": ["Biên giới Việt – Trung", "Trị – Thiên", "Sài Gòn – Gia Định", "Đồng bằng sông Cửu Long"], "answer": 1, "explanation": "Hướng chủ yếu là Trị – Thiên; sau đó phát triển ở Tây Nguyên, Đông Nam Bộ và các hướng khác.", "page": 227, "evidence": "Cuộc tiến công chiến lược được bắt đầu từ hướng chủ yếu là Trị - Thiên, đánh thẳng vào tuyến phòng ngự của địch ỏ Đường 9, tiếp theo là các hướng Tây Nguyên, miền Đông Nam Bộ, rồi đến đồng bằng Khu V và đồng bằng sông Cửu Long.", "type": "mcq"}, {"id": "c2-q051", "section": "c2-s7", "prompt": "Trận Điện Biên Phủ trên không diễn ra trong thời điểm nào?", "options": ["Mùa thu năm 1947", "Tháng 4/1975", "12 ngày đêm cuối năm 1972", "56 ngày đêm mùa xuân 1954"], "answer": 2, "explanation": "Quân dân miền Bắc đánh trả cuộc tập kích chiến lược bằng B.52 cuối tháng 12/1972.", "page": 222, "evidence": "12 ngày đêm cuối năm 1972, lập nên trận “Điện Biên Phủ trên không”, đánh bại hoàn toàn cuộc chiến tranh phá hoại của Mỹ. Riêng trong 12 ngày đêm (từ ngày 18 đến ngày 30/12/1972) đánh trả cuộc tập kích chiến lược bằng máy bay B.", "type": "mcq"}, {"id": "c2-q052", "section": "c2-s7", "prompt": "Hiệp định về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký tại Pari ngày nào?", "options": ["21/7/1954", "14/9/1946", "30/4/1975", "27/1/1973"], "answer": 3, "explanation": "Trang 227 xác định ngày ký Hiệp định Pari là 27/1/1973 sau quá trình đàm phán kéo dài.", "page": 227, "evidence": "kết thúc vào ngày 27/1/1973 với việc ký kết “Hiệp định về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam”. 227", "type": "mcq"}, {"id": "c2-q053", "section": "c2-s7", "prompt": "Chiến thắng Phước Long đầu năm 1975 có ý nghĩa gì trong nhận định chiến lược của Bộ Chính trị?", "options": ["Một đòn thăm dò chiến lược, củng cố cơ sở quyết tâm giải phóng miền Nam", "Chứng minh quân Mỹ đã quay trở lại trực tiếp tham chiến", "Làm chấm dứt cuộc kháng chiến chống Pháp", "Đánh dấu việc hoàn thành Kế hoạch 5 năm lần thứ nhất"], "answer": 0, "explanation": "Phước Long cung cấp thêm cơ sở thực tiễn để đánh giá thời cơ giải phóng miền Nam.", "page": 231, "evidence": "Chiến thắng Phước Long có ý nghĩa như một đòn thăm đồ chiến lược, tạo thêm cơ sở để Bộ Chính trị đi tới nhận định: Chưa bao giờ ta có điều kiện đầy đủ về quân sự, chính trị, có thời cơ chiến lược to lớn như hiện nay để hoàn thành cách mạng dân tộc dân chủ nhân dân ở miền Nam, tiến tới hòa bình thống nhất Tổ quốc.", "type": "mcq"}, {"id": "c2-q054", "section": "c2-s7", "prompt": "Lá cờ chiến thắng được cắm trên Dinh Độc Lập vào thời điểm nào?", "options": ["Ngày 20/12/1960", "11 giờ 30 phút ngày 30/4/1975", "17 giờ 30 phút ngày 7/5/1954", "20 giờ ngày 19/12/1946"], "answer": 1, "explanation": "Giáo trình ghi mốc 11 giờ 30 phút ngày 30/4/1975 khi Sài Gòn được giải phóng.", "page": 232, "evidence": "vào 11 giờ 30 phút ngày 30/4/1975, lá cờ chiến thắng đã được cắm trên Dinh Độc Lập. Toàn bộ lực lượng quân sự và bộ máy chính quyền địch ở Quân khu TI, Quân đoàn IH bị tiêu diệt. Sài Gòn được giải phóng. 232", "type": "mcq"}, {"id": "c2-q055", "section": "c2-s8", "prompt": "Kinh nghiệm lãnh đạo kháng chiến chống Mỹ được giáo trình nhấn mạnh là gì?", "options": ["Chỉ dựa vào một hình thức đấu tranh", "Không cần xây dựng Đảng và lực lượng cách mạng", "Giương cao độc lập dân tộc và chủ nghĩa xã hội, huy động sức mạnh toàn dân", "Tách rời độc lập dân tộc khỏi chủ nghĩa xã hội"], "answer": 2, "explanation": "Bài học đầu tiên là giương cao hai ngọn cờ để huy động toàn dân, cả nước đánh Mỹ.", "page": 235, "evidence": "ngọn cờ độc lập dân tộc và chủ nghĩa xã hội nhằm huy động sức mạnh toàn dân đánh Mỹ, cả nước đánh Mỹ. Hai là, tìm ra phương pháp đấu tranh đúng đắn, sáng tạo, thực hiện khởi nghĩa toàn dân và chiến tranh nhân dân, sử dụng phương pháp cách mạng tổng hợp.", "type": "mcq"}], "mindmap": {"title": "Hai cuộc kháng chiến và thống nhất đất nước (1945–1975)", "branches": [{"id": "c2-b1", "title": "Bảo vệ chính quyền mới", "page": 131, "summary": "Giải quyết khó khăn trong nước và nguy cơ xâm lược.", "children": [{"title": "Kháng chiến kiến quốc", "page": 131, "note": "Ngày 25/11/1945; xác định kẻ thù chính là thực dân Pháp xâm lược."}, {"title": "Chống đói, chống dốt", "page": 133, "note": "Tăng gia sản xuất, tiết kiệm và xóa nạn mù chữ."}, {"title": "Xây dựng nhà nước", "page": 134, "note": "Tổng tuyển cử 6/1/1946; Quốc hội và Chính phủ chính thức."}, {"title": "Hiến pháp 1946", "page": 135, "note": "Thông qua ngày 9/11/1946."}]}, {"id": "c2-b2", "title": "Đấu tranh và hòa hoãn 1946", "page": 140, "summary": "Nhân nhượng có nguyên tắc để bảo vệ độc lập và chuẩn bị lực lượng.", "children": [{"title": "Hiệp định Sơ bộ", "page": 141, "note": "Quốc gia tự do có chính phủ, nghị viện, tài chính và quân đội riêng."}, {"title": "Hòa để tiến", "page": 141, "note": "Hòa hoãn nhưng luôn cảnh giác, sẵn sàng kháng chiến."}, {"title": "Tạm ước 14/9", "page": 142, "note": "Tiếp tục đấu tranh ngoại giao, nhân nhượng thêm một số quyền lợi kinh tế và văn hóa."}]}, {"id": "c2-b3", "title": "Đường lối kháng chiến chống Pháp", "page": 150, "summary": "Toàn dân, toàn diện, lâu dài, dựa vào sức mình là chính.", "children": [{"title": "Toàn dân", "page": 150, "note": "Huy động sức dân; quân đội làm nòng cốt."}, {"title": "Toàn diện", "page": 150, "note": "Kết hợp quân sự, chính trị, kinh tế, văn hóa, tư tưởng và ngoại giao."}, {"title": "Lâu dài", "page": 151, "note": "Chuyển yếu thành mạnh, vẫn tranh thủ thời cơ."}, {"title": "Tự lực là chính", "page": 151, "note": "Phát huy nội lực và tranh thủ giúp đỡ quốc tế."}]}, {"id": "c2-b4", "title": "Từ Việt Bắc đến Biên giới", "page": 154, "summary": "Bảo vệ căn cứ rồi chủ động mở cục diện mới.", "children": [{"title": "Việt Bắc 1947", "page": 154, "note": "Bảo toàn cơ quan đầu não, căn cứ địa; đánh bại đánh nhanh thắng nhanh."}, {"title": "Xây dựng hậu phương", "page": 156, "note": "Phát triển văn hóa, giáo dục, kinh tế và hoạt động ngoại giao."}, {"title": "Biên giới 1950", "page": 160, "note": "Kết thúc thời kỳ chiến đấu trong vòng vây."}]}, {"id": "c2-b5", "title": "Đại hội II và Chính cương 1951", "page": 160, "summary": "Hoàn chỉnh đường lối cách mạng dân tộc dân chủ nhân dân.", "children": [{"title": "Đảng Lao động Việt Nam", "page": 161, "note": "Ra hoạt động công khai; mỗi nước Đông Dương có đảng riêng."}, {"title": "Nhiệm vụ trung tâm", "page": 163, "note": "Chống xâm lược, hoàn thành giải phóng dân tộc."}, {"title": "Động lực cách mạng", "page": 163, "note": "Công nhân, nông dân, tiểu tư sản, tư sản dân tộc và lực lượng yêu nước tiến bộ."}, {"title": "Triển vọng", "page": 163, "note": "Từ cách mạng dân tộc dân chủ nhân dân tiến lên chủ nghĩa xã hội."}]}, {"id": "c2-b6", "title": "Điện Biên Phủ và Giơnevơ", "page": 170, "summary": "Kết hợp thắng lợi quân sự với đấu tranh ngoại giao.", "children": [{"title": "Đông Xuân 1953–1954", "page": 170, "note": "Giữ chủ động, tiêu diệt địch và buộc địch phân tán lực lượng."}, {"title": "Điện Biên Phủ", "page": 172, "note": "56 ngày đêm, ba đợt tiến công; thắng lợi ngày 7/5/1954."}, {"title": "Giơnevơ", "page": 174, "note": "Hiệp định đình chỉ chiến sự 21/7/1954; tôn trọng các quyền dân tộc cơ bản."}]}, {"id": "c2-b7", "title": "Kinh nghiệm kháng chiến chống Pháp", "page": 176, "summary": "Đường lối phù hợp thực tiễn gắn với sức mạnh của nhân dân.", "children": [{"title": "Kháng chiến và kiến quốc", "page": 177, "note": "Kết hợp hai nhiệm vụ xuyên suốt; xây dựng hậu phương vững chắc."}, {"title": "Lực lượng ba thứ quân", "page": 178, "note": "Bộ đội chủ lực, bộ đội địa phương, dân quân du kích."}, {"title": "Xây dựng Đảng", "page": 179, "note": "Nêu gương, củng cố niềm tin; khắc phục chủ quan và giáo điều."}]}, {"id": "c2-b8", "title": "Miền Bắc và Đồng khởi", "page": 182, "summary": "Xây dựng hậu phương, chuyển thế cách mạng miền Nam.", "children": [{"title": "Khôi phục kinh tế", "page": 182, "note": "Hàn gắn vết thương chiến tranh, ưu tiên nông nghiệp và đời sống."}, {"title": "Sửa sai cải cách ruộng đất", "page": 185, "note": "Kiểm điểm, tự phê bình và khắc phục hậu quả."}, {"title": "Nghị quyết 15", "page": 191, "note": "Kết hợp đấu tranh chính trị với đấu tranh quân sự."}, {"title": "Đồng khởi 1960", "page": 192, "note": "Từ giữ gìn lực lượng sang tiến công; Mặt trận Dân tộc giải phóng miền Nam ra đời."}]}, {"id": "c2-b9", "title": "Hai chiến lược cách mạng", "page": 193, "summary": "Thống nhất mục tiêu, khác nhau về nhiệm vụ cụ thể ở mỗi miền.", "children": [{"title": "Miền Bắc", "page": 194, "note": "Cách mạng xã hội chủ nghĩa; vai trò quyết định nhất."}, {"title": "Miền Nam", "page": 194, "note": "Cách mạng dân tộc dân chủ nhân dân; vai trò quyết định trực tiếp."}, {"title": "Kế hoạch 1961–1965", "page": 198, "note": "Xây dựng bước đầu cơ sở vật chất, kỹ thuật của chủ nghĩa xã hội."}, {"title": "Ba mũi giáp công", "page": 201, "note": "Quân sự, chính trị, binh vận trên ba vùng chiến lược."}]}, {"id": "c2-b10", "title": "Cả nước chống Mỹ 1965–1968", "page": 206, "summary": "Bảo vệ miền Bắc, giải phóng miền Nam và kết hợp các mặt trận.", "children": [{"title": "Quyết tâm chiến lược", "page": 207, "note": "Đánh bại chiến tranh xâm lược trong bất kỳ tình huống nào."}, {"title": "Hậu phương và tiền tuyến", "page": 208, "note": "Miền Bắc là hậu phương lớn; miền Nam là tiền tuyến lớn."}, {"title": "Vừa đánh vừa đàm", "page": 216, "note": "Mở mặt trận ngoại giao từ năm 1967."}, {"title": "Tết Mậu Thân 1968", "page": 218, "note": "Bước ngoặt làm phá sản Chiến tranh cục bộ; xem cả hạn chế ở trang 219."}]}, {"id": "c2-b11", "title": "Từ Việt Nam hóa chiến tranh đến Pari", "page": 224, "summary": "Phối hợp quân sự, chính trị và ngoại giao để tạo thời cơ mới.", "children": [{"title": "Việt Nam hóa chiến tranh", "page": 224, "note": "Thủ đoạn dùng người Việt Nam đánh người Việt Nam."}, {"title": "Đường 9 – Nam Lào", "page": 226, "note": "Năm 1971 đánh bại Lam Sơn 719."}, {"title": "Tiến công 1972", "page": 227, "note": "Hướng chủ yếu Trị – Thiên; phá vỡ những tuyến phòng ngự mạnh."}, {"title": "Điện Biên Phủ trên không", "page": 222, "note": "12 ngày đêm cuối năm 1972."}, {"title": "Hiệp định Pari", "page": 227, "note": "Ký ngày 27/1/1973, tạo cơ hội tiến tới thắng lợi hoàn toàn."}]}, {"id": "c2-b12", "title": "Mùa xuân 1975 và bài học", "page": 231, "summary": "Nắm đúng thời cơ, giải phóng miền Nam, mở ra kỷ nguyên mới.", "children": [{"title": "Phước Long", "page": 231, "note": "Đòn thăm dò chiến lược; củng cố nhận định thời cơ."}, {"title": "Tây Nguyên, Huế – Đà Nẵng", "page": 232, "note": "Phát triển nhanh cuộc tiến công; giải phóng miền Nam trong năm 1975."}, {"title": "Chiến dịch Hồ Chí Minh", "page": 232, "note": "Mở ngày 26/4; Sài Gòn được giải phóng ngày 30/4/1975."}, {"title": "Ý nghĩa", "page": 233, "note": "Hoàn thành cách mạng dân tộc dân chủ nhân dân trên cả nước."}, {"title": "Kinh nghiệm", "page": 235, "note": "Hai ngọn cờ, phương pháp cách mạng tổng hợp, tổ chức lực lượng và đoàn kết quốc tế."}]}]}, "timeline": [{"year": "25/11/1945", "title": "Chỉ thị Kháng chiến kiến quốc", "page": 131, "description": "Định hướng xây dựng và bảo vệ chính quyền cách mạng."}, {"year": "6/1/1946", "title": "Tổng tuyển cử đầu tiên", "page": 134, "description": "Bầu Quốc hội của Nhà nước Việt Nam Dân chủ Cộng hòa."}, {"year": "19/12/1946", "title": "Toàn quốc kháng chiến", "page": 147, "description": "Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến."}, {"year": "1947", "title": "Việt Bắc thu đông", "page": 154, "description": "Bảo vệ cơ quan đầu não và căn cứ địa, đánh bại đánh nhanh thắng nhanh."}, {"year": "1950", "title": "Chiến dịch Biên giới", "page": 160, "description": "Phá thế bị bao vây, mở cục diện phát triển cao hơn."}, {"year": "2/1951", "title": "Đại hội II", "page": 160, "description": "Hoàn chỉnh đường lối, thông qua Chính cương; ra hoạt động công khai với tên Đảng Lao động Việt Nam."}, {"year": "7/5/1954", "title": "Chiến thắng Điện Biên Phủ", "page": 172, "description": "Kết thúc 56 ngày đêm chiến đấu và ba đợt tiến công lớn."}, {"year": "21/7/1954", "title": "Hiệp định Giơnevơ", "page": 174, "description": "Ký Hiệp định đình chỉ chiến sự ở Việt Nam."}, {"year": "17/1/1960", "title": "Đồng khởi Bến Tre", "page": 191, "description": "Khởi nghĩa đồng loạt bùng nổ tại Mỏ Cày, sau đó lan rộng."}, {"year": "9/1960", "title": "Đại hội III", "page": 193, "description": "Xác định đồng thời hai chiến lược cách mạng ở hai miền."}, {"year": "1968", "title": "Tổng tiến công và nổi dậy Tết Mậu Thân", "page": 218, "description": "Tạo bước ngoặt, góp phần làm phá sản Chiến tranh cục bộ."}, {"year": "12/1972", "title": "Điện Biên Phủ trên không", "page": 222, "description": "Đánh trả cuộc tập kích chiến lược bằng máy bay B.52 của Mỹ."}, {"year": "27/1/1973", "title": "Hiệp định Pari", "page": 227, "description": "Ký Hiệp định về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam."}, {"year": "30/4/1975", "title": "Giải phóng Sài Gòn", "page": 232, "description": "Chiến dịch Hồ Chí Minh giành thắng lợi; tiếp đó các địa phương còn lại được giải phóng."}], "reviewPrompts": [{"prompt": "Đường lối và sự chỉ đạo của Đảng trong cuộc kháng chiến chống thực dân Pháp xâm lược và can thiệp Mỹ 1945 - 1954.", "page": 235}, {"prompt": "Ý nghĩa lịch sử và những kinh nghiệm lãnh đạo của Đảng trong cuộc kháng chiến chống Pháp và can thiệp Mỹ 1945 - 1954.", "page": 235}, {"prompt": "Sự phát triển đường lối và khái quát quá trình chỉ đạo thực hiện của Đảng trong kháng chiến chống Mỹ, cứu nước 1954 - 1975.", "page": 236}, {"prompt": "Đặc điểm, ý nghĩa thắng lợi và những kinh nghiệm lãnh đạo của Đảng trong kháng chiến chống Mỹ, cứu nước 1954 - 1975.", "page": 236}, {"prompt": "Cách mạng xã hội chủ nghĩa và những thành quả xây dựng chủ nghĩa xã hội ở miền Bắc 1954 - 1975.", "page": 236}], "sourceCorrections": [{"page": 191, "ocr": "huyện Mô Cày", "corrected": "huyện Mỏ Cày", "verified": "Đã đối chiếu ảnh scan gốc."}, {"page": 193, "ocr": "Đại hội đại biểu toàn quốc lần thứ TỊ", "corrected": "Đại hội đại biểu toàn quốc lần thứ III", "verified": "Đã đối chiếu ảnh scan gốc."}, {"page": 206, "ocr": "Ngày 8/3/1985", "corrected": "Ngày 8/3/1965", "verified": "Đã đối chiếu ảnh scan gốc."}, {"page": 206, "ocr": "Hội nghị lần thứ 12 (12/1985)", "corrected": "Hội nghị lần thứ 12 (12/1965)", "verified": "Đã đối chiếu ảnh scan gốc."}, {"page": 232, "ocr": "Buôn Ma Thuột ngày 10/8/1975", "corrected": "Buôn Ma Thuột ngày 10/3/1975", "verified": "Đã đối chiếu ảnh scan gốc."}, {"page": 232, "ocr": "Ngày 26/8, thành phố Huế", "corrected": "Ngày 26/3, thành phố Huế", "verified": "Đã đối chiếu ảnh scan gốc."}], "sourceNotes": [{"page": 222, "note": "Bản in ở trang này ghi ngày 21/1/1973 cho Hiệp định Pari; ngân hàng câu hỏi dùng mốc 27/1/1973 được ghi ở trang 227."}]}, {"id": "c3", "label": "Chương 3", "title": "Đảng lãnh đạo cả nước quá độ lên chủ nghĩa xã hội và tiến hành công cuộc đổi mới (từ năm 1975 đến nay)", "period": "1975–2021", "startPage": 237, "endPage": 408, "summary": "Từ thống nhất đất nước về mặt nhà nước đến quá trình tìm tòi và khởi xướng đường lối đổi mới. Theo dõi sự phát triển đường lối qua các Đại hội IV–XIII và tổng kết thành tựu, hạn chế, bài học theo giáo trình năm 2021.", "sections": [{"id": "c3-s1", "title": "Hoàn thành thống nhất đất nước về mặt nhà nước", "pages": [238, 242], "summary": "Sau năm 1975, nhiệm vụ đầu tiên, bức thiết là thống nhất nước nhà về mặt nhà nước.", "points": ["Hội nghị Trung ương 24 khóa III chủ trương hoàn thành thống nhất nước nhà.", "Tổng tuyển cử ngày 25/4/1976 bầu Quốc hội chung của cả nước.", "Kỳ họp đầu tiên của Quốc hội thống nhất quyết định tên nước và các biểu tượng quốc gia."]}, {"id": "c3-s2", "title": "Đại hội IV, xây dựng chủ nghĩa xã hội và bảo vệ Tổ quốc", "pages": [242, 251], "summary": "Đại hội IV xác định đường lối đưa cả nước lên chủ nghĩa xã hội; thực tiễn đặt ra yêu cầu điều chỉnh quản lý kinh tế.", "points": ["Đại hội IV họp tháng 12/1976, đổi tên Đảng thành Đảng Cộng sản Việt Nam.", "Hội nghị Trung ương 6 tháng 8/1979 mở bước đột phá đầu tiên về đổi mới kinh tế.", "Khoán 100 và các quyết định về quyền chủ động của xí nghiệp tạo động lực sản xuất.", "Bảo vệ biên giới Tây Nam, biên giới phía Bắc và thực hiện nghĩa vụ quốc tế."]}, {"id": "c3-s3", "title": "Đại hội V và các bước đột phá tiếp tục đổi mới kinh tế", "pages": [251, 260], "summary": "Đại hội V xác định hai nhiệm vụ chiến lược; quá trình tìm tòi tiếp tục dẫn tới các đột phá năm 1985 và 1986.", "points": ["Đại hội V họp tháng 3/1982, coi nông nghiệp là mặt trận hàng đầu.", "Hội nghị Trung ương 8 tháng 6/1985 chọn giá, lương, tiền làm khâu đột phá.", "Kết luận của Bộ Chính trị tháng 8/1986 là bước đột phá thứ ba, góp phần trực tiếp hình thành đường lối đổi mới.", "Tổng kết cả thành tựu và sai lầm, khuyết điểm của giai đoạn 1975–1986."]}, {"id": "c3-s4", "title": "Đại hội VI và đường lối đổi mới toàn diện", "pages": [260, 272], "summary": "Đại hội VI tháng 12/1986 khởi xướng đường lối đổi mới toàn diện, trước hết là đổi mới tư duy kinh tế.", "points": ["Nhìn thẳng vào sự thật, đánh giá đúng sự thật, nói rõ sự thật.", "Phát triển nhiều thành phần kinh tế, kết hợp kế hoạch với thị trường.", "Tập trung ba chương trình kinh tế: lương thực–thực phẩm, hàng tiêu dùng, hàng xuất khẩu.", "Khoán 10 năm 1988 tiếp tục đổi mới quản lý kinh tế nông nghiệp."]}, {"id": "c3-s5", "title": "Đại hội VII, Cương lĩnh 1991 và mở rộng quan hệ đối ngoại", "pages": [272, 285], "summary": "Đại hội VII thông qua Cương lĩnh 1991; đường lối đổi mới được bổ sung trong kinh tế, chính trị và đối ngoại.", "points": ["Cương lĩnh 1991 nêu sáu đặc trưng của xã hội xã hội chủ nghĩa và bảy phương hướng lớn.", "Khẳng định chủ nghĩa Mác–Lênin và tư tưởng Hồ Chí Minh là nền tảng tư tưởng.", "Hội nghị giữa nhiệm kỳ năm 1994 chỉ rõ bốn nguy cơ.", "Việt Nam gia nhập ASEAN và thiết lập quan hệ ngoại giao với Hoa Kỳ năm 1995."]}, {"id": "c3-s6", "title": "Đại hội VIII và đẩy mạnh công nghiệp hóa, hiện đại hóa", "pages": [285, 296], "summary": "Sau mười năm đổi mới, Đại hội VIII xác định chuyển sang thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa.", "points": ["Đại hội VIII họp từ ngày 28/6 đến 1/7/1996.", "Phát huy nguồn lực con người; khoa học và công nghệ là động lực công nghiệp hóa, hiện đại hóa.", "Phát triển kinh tế gắn với tiến bộ và công bằng xã hội.", "Xây dựng nền văn hóa tiên tiến, đậm đà bản sắc dân tộc; phát huy dân chủ ở cơ sở."]}, {"id": "c3-s7", "title": "Đại hội IX và mô hình kinh tế tổng quát", "pages": [296, 310], "summary": "Đại hội IX cụ thể hóa đường lối phát triển đất nước trong những năm đầu thế kỷ XXI.", "points": ["Đại hội IX họp tháng 4/2001.", "Kinh tế thị trường định hướng xã hội chủ nghĩa là mô hình kinh tế tổng quát trong thời kỳ quá độ.", "Bỏ qua chế độ tư bản chủ nghĩa không có nghĩa là bỏ qua những thành tựu khoa học, công nghệ của nhân loại.", "Chủ động hội nhập kinh tế quốc tế; phát huy đại đoàn kết toàn dân tộc."]}, {"id": "c3-s8", "title": "Đại hội X và hội nhập kinh tế quốc tế", "pages": [310, 335], "summary": "Đại hội X tổng kết hai mươi năm đổi mới, nhấn mạnh xây dựng, chỉnh đốn Đảng và đẩy mạnh đổi mới toàn diện.", "points": ["Đại hội X họp tháng 4/2006.", "Công nghiệp hóa, hiện đại hóa gắn với phát triển kinh tế tri thức.", "Quan tâm đồng bộ nông nghiệp, nông dân, nông thôn; đội ngũ công nhân, thanh niên và trí thức.", "Việt Nam trở thành thành viên thứ 150 của WTO; hội nhập phải giữ vững độc lập, chủ quyền."]}, {"id": "c3-s9", "title": "Đại hội XI và Cương lĩnh bổ sung, phát triển năm 2011", "pages": [335, 367], "summary": "Đại hội XI thông qua Cương lĩnh bổ sung, phát triển năm 2011, làm rõ hơn mô hình và con đường đi lên chủ nghĩa xã hội.", "points": ["Cương lĩnh 2011 nêu tám đặc trưng, tám phương hướng cơ bản và tám mối quan hệ lớn.", "Ba đột phá chiến lược về thể chế, nguồn nhân lực và kết cấu hạ tầng.", "Đổi mới căn bản, toàn diện giáo dục và đào tạo; xây dựng văn hóa, con người.", "Tăng cường xây dựng Đảng, phòng chống tham nhũng, công tác dân vận; bảo vệ Tổ quốc và hội nhập quốc tế."]}, {"id": "c3-s10", "title": "Đại hội XII và đổi mới toàn diện, đồng bộ", "pages": [367, 386], "summary": "Đại hội XII tổng kết ba mươi năm đổi mới và xác định sáu nhiệm vụ trọng tâm.", "points": ["Nâng cao chất lượng tăng trưởng, năng suất lao động và sức cạnh tranh.", "Phát triển kinh tế tư nhân thành một động lực quan trọng của nền kinh tế.", "Tăng cường xây dựng, chỉnh đốn Đảng; sắp xếp bộ máy và xây dựng đội ngũ cán bộ.", "Phát triển bền vững kinh tế biển, chăm sóc sức khỏe, cải cách chính sách xã hội."]}, {"id": "c3-s11", "title": "Đại hội XIII và tầm nhìn phát triển", "pages": [386, 394], "summary": "Đại hội XIII đầu năm 2021 tổng kết ba mươi lăm năm đổi mới và xác định mục tiêu, nhiệm vụ phát triển trong giai đoạn mới.", "points": ["Kiên định mục tiêu độc lập dân tộc và chủ nghĩa xã hội, đường lối đổi mới và các nguyên tắc xây dựng Đảng.", "Khơi dậy khát vọng phát triển, phát huy sức mạnh con người và đại đoàn kết toàn dân tộc.", "Sáu nhiệm vụ trọng tâm, ba đột phá chiến lược; chú trọng chuyển đổi số và đổi mới sáng tạo.", "Các mục tiêu tới năm 2025, 2030 và tầm nhìn 2045 được trình bày là mục tiêu trong giáo trình năm 2021."]}, {"id": "c3-s12", "title": "Thành tựu, hạn chế và bài học của công cuộc đổi mới", "pages": [394, 408], "summary": "Giáo trình tổng kết thành tựu trên các lĩnh vực, đồng thời nêu hạn chế, nguyên nhân và bài học kinh nghiệm.", "points": ["Chuyển đổi mô hình kinh tế, phát triển giáo dục, văn hóa, xã hội; củng cố quốc phòng, an ninh và đối ngoại.", "Đánh giá khách quan cả thành tựu lẫn hạn chế; nguyên nhân chủ quan của hạn chế là chủ yếu.", "Xây dựng, chỉnh đốn Đảng; dân là gốc; tổ chức thực hiện hiệu quả.", "Giải quyết hài hòa các quan hệ lớn, chủ động dự báo và giữ vững độc lập, tự chủ trong hội nhập."]}], "questions": [{"id": "c3-q001", "section": "c3-s1", "prompt": "Sau đại thắng mùa Xuân 1975, nhiệm vụ đầu tiên, bức thiết nhất được Đảng đặt ra là gì?", "options": ["Thống nhất nước nhà về mặt nhà nước", "Tiến hành Tổng khởi nghĩa trên cả nước", "Thành lập Mặt trận Việt Minh", "Ký Hiệp định Giơnevơ"], "answer": 0, "explanation": "Giáo trình xác định thống nhất về mặt nhà nước là nhiệm vụ đầu tiên, bức thiết sau khi đất nước được giải phóng.", "page": 238, "evidence": "độ này, rất nhiều nhiệm vụ được Đảng đặt ra nhưng nhiệm vụ đầu tiên, bức thiết nhất là lãnh đạo thống nhất 238", "type": "mcq"}, {"id": "c3-q002", "section": "c3-s1", "prompt": "Cuộc Tổng tuyển cử bầu Quốc hội chung của nước Việt Nam thống nhất diễn ra ngày nào?", "options": ["6/1/1946", "2/9/1945", "30/4/1975", "25/4/1976"], "answer": 3, "explanation": "Ngày 25/4/1976, cử tri cả nước bầu Quốc hội chung của nước Việt Nam thống nhất.", "page": 240, "evidence": " trách nhiệm cho các cấp ủy lãnh đạo cuộc bầu cử. Ngày 25/4/1976, cuộc Tổng tuyển cử bầu Quốc hội chung của nước Việt Nam thống nhất được tiến hành. Hơn 23 triệu cử tri, đạt tỷ lệ 98,77% tổng số cử trí đi bầu, đã bầu ra 492 đại biểu gồm đủ các ", "type": "mcq"}, {"id": "c3-q003", "section": "c3-s1", "prompt": "Kỳ họp thứ nhất Quốc hội nước Việt Nam thống nhất năm 1976 quyết định tên nước là gì?", "options": ["Việt Nam Dân chủ Cộng hòa", "Cộng hòa miền Nam Việt Nam", "Cộng hòa xã hội chủ nghĩa Việt Nam", "Việt Nam Độc lập Đồng minh"], "answer": 2, "explanation": "Quốc hội quyết định tên nước là Cộng hòa xã hội chủ nghĩa Việt Nam tại kỳ họp từ 24/6 đến 3/7/1976.", "page": 241, "evidence": ", Từ ngày 24/6 đến ngày 3/7/1976, kỳ họp thứ nhất Quốc hội nước Việt Nam thống nhất đã họp tại Thủ đô Hà Nội. Quốc hội quyết định đặt tên nước ta là nước Cộng hoà xã hội chủ nghĩa Việt Nam, Quốc kỳ nền đỏ sao vàng ð cánh, Thủ đô là Hà Nội, Quốc ca là bài Tiến quân ca, Quốc huy mang dòng chữ Cộng hòa xã hội chủ nghĩa Việt", "type": "mcq"}, {"id": "c3-q004", "section": "c3-s2", "prompt": "Đại hội đại biểu toàn quốc lần thứ IV của Đảng họp vào thời gian nào?", "options": ["27–31/3/1982", "14–20/12/1976", "15–18/12/1986", "24–27/6/1991"], "answer": 1, "explanation": "Đại hội IV họp tại Hà Nội từ ngày 14 đến 20/12/1976.", "page": 242, "evidence": "b) Đại hội đại biểu toàn quốc lần thứ TV của Đảng và quá trình xây dựng chủ nghĩa xã hội và bảo vệ Tổ quốc Đại hội lần thứ IV của Đảng họp từ ngày 14 đến ngày 20/12/1976, tại Hà Nội. Dự Đại hội eó 1.008 đại biểu, thay mặt cho hơn 1,5 triệu đẳng viên trên cả nước, có 29 đoàn đại biểu của các đảng và tổ chức quốc tế tham dự. Đại hội thông qua Báo cáo chính trị, Báo cáo về phương hướng, nhiệm vụ và mục tiêu Kế hoạch nhà nước ð năm (1976 - 1980), Báo cáo tổng kết công tác xây dựng Đảng; quyết định đổi tên Đảng Lao động Việt Nam thành Đảng Cộng sản Việt Nam và sửa đổi Điều lệ Đảng, bầu Ban Chấp hành Trung ương gồm 101 ủy viên chính thức, 32 ủy viên dự khuyết, bầu đẳng chí Lê Duẩn làm Tổng Bí thư của Đảng.", "type": "mcq"}, {"id": "c3-q005", "section": "c3-s2", "prompt": "Đại hội IV quyết định đổi tên Đảng Lao động Việt Nam thành tên nào?", "options": ["Đảng Cộng sản Việt Nam", "Đông Dương Cộng sản Đảng", "Đảng Cộng sản Đông Dương", "An Nam Cộng sản Đảng"], "answer": 0, "explanation": "Đại hội IV quyết định dùng tên Đảng Cộng sản Việt Nam và sửa đổi Điều lệ Đảng.", "page": 242, "evidence": "- 1980), Báo cáo tổng kết công tác xây dựng Đảng; quyết định đổi tên Đảng Lao động Việt Nam thành Đảng Cộng sản Việt Nam và sửa đổi Điều lệ Đảng, bầu Ban Chấp hành Trung ương gồm 101 ủy viên chính thức, 32 ủy viên dự khuyết, bầu đẳng chí Lê Duẩn làm Tổng Bí thư của Đảng.", "type": "mcq"}, {"id": "c3-q006", "section": "c3-s2", "prompt": "Trong ba cuộc cách mạng được Đại hội IV nêu ra, cuộc cách mạng nào được xác định là then chốt?", "options": ["Cách mạng về quan hệ sản xuất", "Cách mạng tư tưởng và văn hóa", "Cách mạng giải phóng dân tộc", "Cách mạng khoa học–kỹ thuật"], "answer": 3, "explanation": "Đường lối Đại hội IV xác định cách mạng khoa học–kỹ thuật là then chốt trong ba cuộc cách mạng tiến hành đồng thời.", "page": 244, "evidence": "kỹ thuật, cách mạng tư tưởng và văn hoá, trong đó cách mạng khoa học - kỹ thuật là then chốt; đẩy mạnh công nghiệp hóa xã hội chủ nghĩa là nhiệm vụ trung tâm của cả thời kỷ quá độ lên chủ nghĩa xã hội: xây dựng chế độ làm chủ tập thể xã hội chủ nghĩa, xây dựng nền sản xuất lớn xã hội chủ nghĩa, xây dựng nền văn hoá mới, xây dựng con người mới xã hội chủ nghĩa; xóa bỏ chế độ người bóc lột người, xoá bỏ nghèo nàn và lạc hậu; không ngừng đề cao cảnh giác, thường xuyên củng cố quốc phòng, giữ gìn an ninh chính trị và trật tự xã hội; xây dựng thành công Tổ quốc Việt Nam hòa bình, độc lập, thống nhất và xã hội chủ nghĩa; góp phần tích cực vào cuộc đấu tranh của nhân dân thế giới vì hòa bình, độc lập dân tộc, dân chủ và chủ nghĩa xã hộ?", "type": "mcq"}, {"id": "c3-q007", "section": "c3-s2", "prompt": "Bước đột phá đầu tiên về đổi mới kinh tế của Đảng gắn với hội nghị nào?", "options": ["Hội nghị Trung ương 8 tháng 6/1985", "Hội nghị Bộ Chính trị tháng 8/1986", "Hội nghị Trung ương 6 tháng 8/1979", "Hội nghị Trung ương 7 tháng 8/2008"], "answer": 2, "explanation": "Hội nghị Trung ương 6 tháng 8/1979 được giáo trình đánh giá là bước đột phá đầu tiên về đổi mới kinh tế.", "page": 246, "evidence": "'Triển khai thực hiện Nghị quyết Đại hội IV, Ban Chấp hành Trung ương Đảng đã tập trung chủ yếu vào chỉ đạo phát triển nông nghiệp, thủ công nghiệp và phân phối lưu thông. Hội nghị Trung ương 6 (8/1979) được cho là bước đột phá đầu tiên đổi mới kinh tế của Đảng với chủ trương khắc phục những khuyết điểm, sai lầm trong quản lý kinh 246", "type": "mcq"}, {"id": "c3-q008", "section": "c3-s2", "prompt": "Chỉ thị 100-CT/TW ngày 13/1/1981 đề ra nội dung chủ yếu nào?", "options": ["Thực hiện cơ chế một giá trên toàn quốc", "Khoán sản phẩm đến nhóm và người lao động trong hợp tác xã nông nghiệp", "Quốc hữu hóa toàn bộ hoạt động thương mại", "Đổi tiền đồng loạt trong cả nước"], "answer": 1, "explanation": "Khoán 100 nhằm tạo động lực sản xuất thông qua khoán sản phẩm đến nhóm và người lao động.", "page": 247, "evidence": "ban hành Chỉ thị số 100-CT/TW (ngày 13/1/1981) về khoán sản phẩm đến nhóm và người lao động trong các hợp tác xã nông nghiệp (gọi tắt là Khoán 100). Theo Chỉ thị, mỗi xã viên nhận mức khoán theo điện tích và tự mình làm các khâu cấy, chăm sóc và thu hoạch, còn những khâu", "type": "mcq"}, {"id": "c3-q009", "section": "c3-s2", "prompt": "Quyết định 25/CP tháng 1/1981 hướng tới việc mở rộng quyền gì của xí nghiệp quốc doanh?", "options": ["Chủ động sản xuất kinh doanh và tự chủ về tài chính", "Quyết định đường lối đối ngoại quốc gia", "Tự tổ chức tổng tuyển cử địa phương", "Ban hành luật đầu tư nước ngoài"], "answer": 0, "explanation": "Quyết định 25/CP đề cập quyền chủ động sản xuất kinh doanh và quyền tự chủ tài chính của xí nghiệp quốc doanh.", "page": 247, "evidence": "Trong lĩnh vực công nghiệp, trước các hiện tượng “xé rào” bù giá vào lương ở Thành phố Hồ Chí Minh và tỉnh Long An, Chính phủ ban hành Quyết định số 25/CP (1/1981) về quyền chủ động sản xuất kinh doanh và quyền tự chủ về tài chính của các xí nghiệp quốc doanh và Quyết định số 26/CP về việc mở rộng hình thức trả lương khoán, 247", "type": "mcq"}, {"id": "c3-q010", "section": "c3-s2", "prompt": "Theo giáo trình, ngày giải phóng Phnôm Pênh, đánh đổ chế độ diệt chủng Pôn Pốt là ngày nào?", "options": ["17/2/1979", "25/4/1976", "28/7/1995", "7/1/1979"], "answer": 3, "explanation": "Quân tình nguyện Việt Nam phối hợp, giúp đỡ lực lượng cách mạng Campuchia tiến công, giải phóng Phnôm Pênh ngày 7/1/1979.", "page": 249, "evidence": "phối hợp và giúp đố Campuchia tổng tiến công, đến ngày 7/1/1979 giải phóng Phnôm Pênh, đánh đổ chế độ diệt chúng Pôn Pốt. Ngày 18/2/1979, Việt Nam và Campuchia ký Hiệp ước hòa bình, hữu nghị và hợp tác. Theo Hiệp ước, quân đội Việt Nam có mặt ở Campuchia để giúp bạn bảo vệ độc lập, chủ quyền, toàn vẹn lãnh thổ và hồi sinh đất nước.", "type": "mcq"}, {"id": "c3-q011", "section": "c3-s2", "prompt": "Cuộc tiến công của Trung Quốc trên toàn tuyến biên giới phía Bắc Việt Nam bắt đầu ngày nào?", "options": ["7/1/1979", "30/4/1975", "17/2/1979", "19/12/1946"], "answer": 2, "explanation": "Giáo trình nêu cuộc tiến công trên tuyến biên giới phía Bắc bắt đầu ngày 17/2/1979; quân dân Việt Nam chiến đấu bảo vệ Tổ quốc.", "page": 250, "evidence": "quan hệ Trung Quốc - Việt Nam xấu đi rõ rệt. Ngày 17/2/1979, Trung Quốc huy động hơn 60 vạn quân đồng loạt tấn công toàn tuyến biên giới nước ta từ Lai Châu đến Quảng Ninh, gây ra những thiệt hại rất nặng nề. Quân dân Việt Nam, nhất là quân dân các tỉnh biên giới phía Bắc, được nhân dân thế giới ủng hộ đã kiên cường chiến đấu bảo vệ đất nước.", "type": "mcq"}, {"id": "c3-q012", "section": "c3-s3", "prompt": "Đại hội V của Đảng diễn ra vào thời gian nào?", "options": ["14–20/12/1976", "27–31/3/1982", "15–18/12/1986", "28/6–1/7/1996"], "answer": 1, "explanation": "Đại hội V họp từ ngày 27 đến 31/3/1982.", "page": 251, "evidence": "Nghị quyết Đại hội Đại hội V của Đảng họp từ ngày 27 đến ngày 31/3/1982 trong bối cảnh tình hình thế giới và trong nước 251", "type": "mcq"}, {"id": "c3-q013", "section": "c3-s3", "prompt": "Hai nhiệm vụ chiến lược được Đại hội V xác định là gì?", "options": ["Xây dựng thành công chủ nghĩa xã hội và bảo vệ vững chắc Tổ quốc xã hội chủ nghĩa", "Tổng khởi nghĩa và kháng chiến chống Pháp", "Cải cách ruộng đất và giải phóng miền Nam", "Công nghiệp hóa và thay thế hoàn toàn nông nghiệp"], "answer": 0, "explanation": "Hai nhiệm vụ xây dựng chủ nghĩa xã hội và bảo vệ Tổ quốc có quan hệ mật thiết với nhau.", "page": 253, "evidence": "Đại hội chỉ rõ: “Kinh nghiệm của õ năm 1976 - 1980 cho thấy sự cần thiết phải cụ thể hoá đường lối của Đẳng - đường lối chung của cách mạng xã hội chủ nghĩa và đường lối xây dựng nền kinh tế xã hội chủ nghĩa ở nước ta - vạch ra chiến lược kinh tế - xã hội cho chặng đường đầu tiên của quá trình công nghiệp hóa xã hội chủ nghĩa”. Cách mạng Việt Nam có hai nhiệm vụ chiến lược là: xây dựng thành công chủ nghĩa xã hội và bảo vệ vững chắc Tổ quốc Việt Nam xã hội chủ nghĩa. Hai nhiệm vụ chiến lược có quan hệ mật thiết với nhau: “Trong khi không một phút lơi lỏng nhiệm vụ củng cố quốc phòng, bảo vệ Tổ quốc, Đảng ta và nhân dân ta phải đặt lên hàng đầu nhiệm vụ xây dựng chủ nghĩa xã hộ?", "type": "mcq"}, {"id": "c3-q014", "section": "c3-s3", "prompt": "Trong chặng đường đầu tiên, Đại hội V xác định lĩnh vực nào là mặt trận hàng đầu?", "options": ["Công nghiệp nặng quy mô lớn", "Dịch vụ tài chính quốc tế", "Du lịch biển", "Nông nghiệp"], "answer": 3, "explanation": "Đại hội V chủ trương tập trung phát triển nông nghiệp, coi nông nghiệp là mặt trận hàng đầu.", "page": 254, "evidence": "là mặt trận hàng đầu, đưa nông nghiệp một bước lên sản xuất lớn xã hội chủ nghĩa, ra sức đẩy mạnh sản xuất hàng tiêu dùng và tiếp tục xây dựng một số ngành công nghiệp nặng quan trọng; kết hợp nông nghiệp, công nghiệp hàng tiêu đùng và công nghiệp nặng trong cơ cấu công - nông nghiệp hợp lý.", "type": "mcq", "sourcePages": [253, 254], "evidenceExtra": [{"page": 253, "evidence": "Nội dung, bước đi, cách làm để thực hiện công nghiệp hoá xã hội chủ nghĩa trong chặng đường đầu tiên là; tập trung sức phát triển mạnh nông nghiệp, coi nông nghiệp"}]}, {"id": "c3-q015", "section": "c3-s3", "prompt": "Bước đột phá thứ hai về đổi mới kinh tế, tháng 6/1985, chọn khâu nào làm đột phá?", "options": ["Đối ngoại–quốc phòng–an ninh", "Giáo dục–y tế–văn hóa", "Giá–lương–tiền", "Tổ chức–cán bộ–kiểm tra"], "answer": 2, "explanation": "Hội nghị Trung ương 8 tháng 6/1985 chủ trương xóa bỏ cơ chế tập trung quan liêu bao cấp, lấy giá–lương–tiền làm khâu đột phá.", "page": 255, "evidence": "bỏ oơ chế tập trung quan liêu hành chính bao cấp, lấy giá - lương - tiền là khâu đột phá để chuyển sang cơ chế hạch toán, kinh doanh xã hội chủ nghĩa. Nội dung xoá bỏ cơ chế quan liệu, bao cấp trong giá và lương là tính đủ chi phí hợp lý trong giá thành sản phẩm; giá ", "type": "mcq"}, {"id": "c3-q016", "section": "c3-s3", "prompt": "Bước đột phá thứ ba về đổi mới kinh tế gắn với sự kiện nào?", "options": ["Chỉ thị Khoán 100 tháng 1/1981", "Kết luận của Hội nghị Bộ Chính trị tháng 8/1986", "Hội nghị Trung ương 6 tháng 8/1979", "Đại hội IV tháng 12/1976"], "answer": 1, "explanation": "Kết luận tháng 8/1986 là bước đột phá thứ ba, góp phần quyết định cho sự ra đời đường lối đổi mới.", "page": 256, "evidence": "Cuộc điều chỉnh giá, lương, tiền đã làm cho cuộc khủng hoảng kinh tế - xã hội trầm trọng sâu sắc hơn. Hội nghị Bộ Chính trị khoá V (8/1986) đưa ra kết luận đối với một số vấn đề thuộc về quan điểm kinh tế. Đây là bước đột phá thứ ba về đổi mới kinh tế, đồng thời cũng là bước quyết định cho sự ra đời của đường lối đối ", "type": "mcq"}, {"id": "c3-q017", "section": "c3-s3", "prompt": "Kết luận của Bộ Chính trị tháng 8/1986 yêu cầu tập trung vào ba chương trình nào?", "options": ["Lương thực–thực phẩm, hàng tiêu dùng thiết yếu, hàng xuất khẩu", "Công nghiệp nặng, quân sự, khai khoáng", "Văn học, nghệ thuật, thể thao", "Ngân hàng, chứng khoán, bảo hiểm"], "answer": 0, "explanation": "Ba chương trình tập trung giải quyết nhu cầu thiết yếu và tạo nguồn hàng xuất khẩu.", "page": 257, "evidence": "Cần tập trung lực lượng, trước hết là vốn và vật tư, thực hiện cho được ba chương trình quan trọng nhất về lương thực, thực phẩm, hàng tiêu dùng thiết yếu và hàng xuất khẩu. Về cải tạo xã hội chú nghĩa, Hội nghị cho rằng, do chưa nắm vững quy luật đẩy mạnh cải tạo xã hội chủ nghĩa là nhiệm vụ thường xuyên, liên tục trong suốt thời kỳ quá độ lên chủ nghĩa xã hội, nên chúng ta đã phạm nhiều khuyết điểm trong cải tạo xã hội chủ nghĩa.", "type": "mcq"}, {"id": "c3-q018", "section": "c3-s4", "prompt": "Đại hội VI khởi xướng đường lối đổi mới toàn diện diễn ra khi nào?", "options": ["14–20/12/1976", "27–31/3/1982", "12–19/1/2011", "15–18/12/1986"], "answer": 3, "explanation": "Đại hội VI họp tại Hà Nội từ ngày 15 đến 18/12/1986, khởi xướng đường lối đổi mới toàn diện.", "page": 260, "evidence": "Đổi mới toàn diện, đưa đất nước ra khỏi khủng hoảng kinh tế - xã hội 1986 - 1996 a) Đại hội đại biểu toàn quốc lần thứ VI của Đảng và thực hiện đường lối đổi mới toàn diện Đại hội VI của Đảng diễn ra tại Hà Nội từ ngày lõ đến ngày 18/12/1986, trong bối cảnh cuộc cách mạng khoa học - kỹ thuật đang phát triển mạnh, xu thế đối thoại trên thế giới đang dẫn thay thế xu thế đối đầu. Đổi mới đã trở thành xu thế của thời đại.", "type": "mcq"}, {"id": "c3-q019", "section": "c3-s4", "prompt": "Ai được bầu làm Tổng Bí thư tại Đại hội VI?", "options": ["Lê Duẩn", "Đỗ Mười", "Nguyễn Văn Linh", "Nông Đức Mạnh"], "answer": 2, "explanation": "Đại hội VI bầu đồng chí Nguyễn Văn Linh làm Tổng Bí thư của Đảng.", "page": 261, "evidence": "Chính trị gồm 13 ủy viên chính thức; bầu đồng chí Nguyễn Văn Linh làm Tổng Bí thư của Đảng. Đường lối đổi mới toàn điện do Đại hội VI đề ra thể hiện trên các lĩnh vực nổi bật như sau: Đại hội đã nhìn thẳng vào sự thật, đánh giá đúng sự thật, nói rõ sự thật, đánh giá thành tựu, nghiêm túc kiểm điểm, chỉ rõ những sai lầm, khuyết điểm của Đảng trong thời kỳ 1975 - 1986.", "type": "mcq"}, {"id": "c3-q020", "section": "c3-s4", "prompt": "Bài học đầu tiên được Đại hội VI rút ra là quán triệt tư tưởng nào?", "options": ["Ưu tiên tuyệt đối công nghiệp nặng", "Lấy dân làm gốc", "Tách chính sách kinh tế khỏi đời sống nhân dân", "Chỉ dựa vào nguồn lực bên ngoài"], "answer": 1, "explanation": "Trong bốn bài học của Đại hội VI, bài học đầu tiên nhấn mạnh tư tưởng lấy dân làm gốc.", "page": 262, "evidence": "Đại hội rút ra bốn bài học quý báu: Một là, trong toàn bộ hoạt động của mình, Đảng phải quán triệt tư tưởng “lấy dân làm gốc”. Hai là, Đảng phải luôn luôn xuất phát từ thực tế, tôn trọng và hành động theo quy luật khách quan. Ba la, phải biết kết hợp sức mạnh dân tộc với sức mạnh thời đại trong điều kiện mới.", "type": "mcq"}, {"id": "c3-q021", "section": "c3-s4", "prompt": "Ba chương trình kinh tế lớn được Đại hội VI nhấn mạnh gồm những gì?", "options": ["Lương thực–thực phẩm, hàng tiêu dùng, hàng xuất khẩu", "Công nghiệp quốc phòng, khai khoáng, tài chính", "Hàng nhập khẩu, bất động sản, chứng khoán", "Du lịch, thể thao, điện ảnh"], "answer": 0, "explanation": "Đại hội VI coi ba chương trình này là sự cụ thể hóa nội dung công nghiệp hóa trong chặng đường đầu của thời kỳ quá độ.", "page": 262, "evidence": "Nhiệm vụ bao trùm, mục tiêu tổng quát trong những năm còn lại của chặng đường đầu tiên là: Sản xuất đủ tiêu dùng và có tích lũy; bước đầu tạo ra một cơ cấu kinh tế hợp lý, trong đó đặc biệt chú trọng ba chương trình kinh tế lớn là lương thực - thực phẩm, hàng tiêu dùng và hàng xuất khẩu, coi đó là sự cụ thể hóa nội dung công nghiệp hoá trong chặng đường đầu của thời kỳ quá độ. Thực hiện cải tạo xã hội chủ nghĩa thường xuyên với hình thức, bước đi thích hợp, làm cho quan hệ sản xuất phù hợp và lực lượng sản xuất phát triển.", "type": "mcq"}, {"id": "c3-q022", "section": "c3-s4", "prompt": "Đại hội VI chủ trương đổi mới cơ chế quản lý kinh tế theo hướng nào?", "options": ["Loại bỏ mọi thành phần kinh tế ngoài quốc doanh", "Chỉ phân phối sản phẩm bằng hiện vật", "Duy trì nguyên trạng cơ chế bao cấp", "Xóa bỏ tập trung quan liêu bao cấp, kết hợp kế hoạch với thị trường"], "answer": 3, "explanation": "Đổi mới cơ chế quản lý gắn với phát triển nhiều thành phần kinh tế và chuyển sang hạch toán, kinh doanh.", "page": 262, "evidence": "Đổi mới cơ chế quần lý, xóa bỏ cơ chế tập trung quan liêu, hành chính, bao cấp, chuyển sang hạch toán, kinh doanh, kết hợp kế hoạch với thị trường. Nhiệm vụ bao trùm, mục tiêu tổng quát trong những năm còn lại của chặng đường đầu tiên là: Sản xuất đủ tiêu dùng và có tích lũy; bước đầu tạo ra một cơ cấu kinh tế hợp lý, trong ", "type": "mcq"}, {"id": "c3-q023", "section": "c3-s4", "prompt": "Theo Đại hội VI, đổi mới sự lãnh đạo của Đảng trước hết cần đổi mới điều gì?", "options": ["Tên gọi của tất cả cơ quan nhà nước", "Địa giới toàn bộ các tỉnh", "Tư duy, trước hết là tư duy kinh tế", "Quốc kỳ và Quốc ca"], "answer": 2, "explanation": "Đại hội VI đặt đổi mới tư duy, trước hết là tư duy kinh tế, trong yêu cầu đổi mới sự lãnh đạo của Đảng.", "page": 264, "evidence": "mới sự lãnh đạo của Đảng cần phải đổi mới tư duy, trước hết là tư duy kinh tế, đổi mới công tác tư tưởng; đổi mới công tác cán bộ và phong cách làm việc, giữ vững các nguyên tắc tổ chức và sinh hoạt Đảng; tăng cường đoàn kết nhất trí trong Đảng. Đảng cần phát huy quyền làm chủ tập thể của nhân dân lao động, thực hiện “dân biết, dân bàn, dân làm, dân kiểm tra”; tăng cường hiệu lực quản lý của Nhà nước là điều kiện tất yếu để huy động lực lượng của quần chúng.", "type": "mcq"}, {"id": "c3-q024", "section": "c3-s4", "prompt": "Khoán 10 gắn với nghị quyết nào của Bộ Chính trị?", "options": ["Chỉ thị 100-CT/TW ngày 13/1/1981", "Nghị quyết 10-NQ/TW ngày 5/4/1988 về đổi mới quản lý kinh tế nông nghiệp", "Nghị quyết về Chiến lược biển năm 2018", "Nghị quyết về văn hóa năm 1998"], "answer": 1, "explanation": "Nghị quyết 10-NQ/TW ngày 5/4/1988 của Bộ Chính trị được gọi tắt là Khoán 10.", "page": 266, "evidence": "Trong nông nghiệp, nổi bật là Nghị quyết số 10- NQ/TW ngày 5/4/1988 của Bộ Chính trị về “Đổi mới quản lý kinh tế nông nghiệp” (gọi tắt là Khoán 10). Theo đó, người nông dân được nhận khoán và canh tác trên diện tích ổn định trong 15 năm; bảo đảm có thu nhập từ 40% sắn lượng khoán trở lên.", "type": "mcq"}, {"id": "c3-q025", "section": "c3-s5", "prompt": "Đại hội nào thông qua Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội năm 1991?", "options": ["Đại hội VII", "Đại hội IV", "Đại hội VI", "Đại hội IX"], "answer": 0, "explanation": "Đại hội VII tháng 6/1991 thông qua Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội.", "page": 272, "evidence": "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội được Đại hội VH thông qua (gọi tắt là Cương lĩnh năm 1991) đã tổng kết hơn 60 năm Đảng lãnh đạo cách mạng Việt Nam; chỉ ra những thành công, khuyết điểm, sai lầm và nêu ra năm bài học lớn: Một là, 272", "type": "mcq"}, {"id": "c3-q026", "section": "c3-s5", "prompt": "Cương lĩnh năm 1991 nêu bao nhiêu đặc trưng cơ bản của xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng?", "options": ["Bốn đặc trưng", "Tám đặc trưng", "Mười đặc trưng", "Sáu đặc trưng"], "answer": 3, "explanation": "Cương lĩnh 1991 nêu sáu đặc trưng cơ bản; cần phân biệt với tám đặc trưng trong Cương lĩnh bổ sung, phát triển năm 2011.", "page": 273, "evidence": "Cương lĩnh đã khái quất xu thế phát triển của thế giới, đặc điểm của thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam; nêu rõ xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng là một xã hội có sầu đặc trưng cơ bản: “Đo nhân dân lao động làm chủ. Có một nền kinh tế phát triển cao dựa trên lực lượng sản xuất hiện đại và chế độ công hữu VỀ các tư liệu sản xuất chủ yếu. Có nền văn hóa tiên tiến", "type": "mcq"}, {"id": "c3-q027", "section": "c3-s5", "prompt": "Cương lĩnh 1991 khẳng định nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng là gì?", "options": ["Chỉ các kinh nghiệm quản lý kinh tế thị trường", "Chỉ các học thuyết quân sự truyền thống", "Chủ nghĩa Mác–Lênin và tư tưởng Hồ Chí Minh", "Chỉ các thành tựu khoa học kỹ thuật"], "answer": 2, "explanation": "Cương lĩnh khẳng định chủ nghĩa Mác–Lênin và tư tưởng Hồ Chí Minh là nền tảng tư tưởng, kim chỉ nam cho hành động.", "page": 275, "evidence": "chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh làm nền tảng tư tưởng, kim chỉ nam cho hành động, lấy tập trung đân chủ làm nguyên tắc tổ chức cơ bản. Xây dựng Đảng trong sạch, vững mạnh về chính trị, tư tưởng và tổ chức. Cương lĩnh năm 1991 đã giải", "type": "mcq"}, {"id": "c3-q028", "section": "c3-s5", "prompt": "Việt Nam trở thành thành viên đầy đủ của ASEAN vào ngày nào?", "options": ["11/7/1995", "28/7/1995", "28/7/1994", "1/1/1988"], "answer": 1, "explanation": "Giáo trình ghi Việt Nam trở thành thành viên đầy đủ của ASEAN ngày 28/7/1995.", "page": 281, "evidence": " viên đầy đủ của Hiệp hội các quốc gia Đông Nam Á ngày 28/7/1995 (ASEAN) và thiết lập quan hệ ngoại giao Việt Nam - Hoa Kỳ ngày 11/7/1995. Đến cuối năm 1995, Việt Nam có quan hệ ngoại giao với 160 nước, quan hệ thương mại quốc tế buôn bán với trên 100 nước.", "type": "mcq"}, {"id": "c3-q029", "section": "c3-s5", "prompt": "Theo giáo trình, Việt Nam và Hoa Kỳ thiết lập quan hệ ngoại giao vào ngày nào?", "options": ["11/7/1995", "28/7/1995", "21/7/1954", "27/1/1973"], "answer": 0, "explanation": "Giáo trình sử dụng mốc ngày 11/7/1995 cho việc thiết lập quan hệ ngoại giao Việt Nam–Hoa Kỳ.", "page": 281, "evidence": "và thiết lập quan hệ ngoại giao Việt Nam - Hoa Kỳ ngày 11/7/1995. Đến cuối năm 1995, Việt Nam có quan hệ ngoại giao với 160 nước, quan hệ thương mại quốc tế buôn bán với trên 100 nước... Các công ty của hơn 50 nước và vùng lãnh thổ đã đầu tư trực tiếp vào Việt Nam.", "type": "mcq"}, {"id": "c3-q030", "section": "c3-s5", "prompt": "Nguy cơ nào thuộc bốn nguy cơ được Hội nghị giữa nhiệm kỳ khóa VII năm 1994 chỉ ra?", "options": ["Chỉ thiếu hàng tiêu dùng trong một mùa vụ", "Không còn nhu cầu hội nhập quốc tế", "Không còn yêu cầu xây dựng Đảng", "Tụt hậu xa hơn về kinh tế so với nhiều nước"], "answer": 3, "explanation": "Bốn nguy cơ gồm tụt hậu kinh tế, chệch hướng xã hội chủ nghĩa, tham nhũng và quan liêu, diễn biến hòa bình.", "page": 283, "evidence": "và những cơ hội lớn. Hội nghị chỉ rõ các nguy cơ: nguy cơ tụt hậu xa hơn về kinh tế so với nhiều nước trong khu vực và trên thế giới do điểm xuất phát thấp, nhịp độ tăng trưởng chưa cao và chưa vững chắc, lại phải đi lên trong môi trường cạnh tranh gay gắt; nguy ", "type": "mcq"}, {"id": "c3-q031", "section": "c3-s6", "prompt": "Đại hội VIII của Đảng diễn ra năm nào?", "options": ["1986", "1991", "1996", "2001"], "answer": 2, "explanation": "Đại hội VIII họp tại Hà Nội từ ngày 28/6 đến 1/7/1996.", "page": 285, "evidence": "VHI của Đảng họp tại Hà Nội từ ngày 28/6 đến ngày 1/7/1996, trong bối cảnh cuộc cách mạng khoa học và công nghệ phát triển với trình độ cao hơn, chủ nghĩa xã hội hiện thực lâm vào thoái trào. Sau 10 năm đổi mới, nhân dân Việt Nam đã giành", "type": "mcq"}, {"id": "c3-q032", "section": "c3-s6", "prompt": "Đánh giá tổng kết mười năm đổi mới tại Đại hội VIII nêu kết quả lớn nào?", "options": ["Đã hoàn tất mọi mục tiêu của thời kỳ quá độ", "Đất nước ra khỏi khủng hoảng kinh tế–xã hội, nhưng một số mặt chưa vững chắc", "Không còn bất kỳ hạn chế kinh tế nào", "Đã chấm dứt nhu cầu công nghiệp hóa"], "answer": 1, "explanation": "Đại hội VIII đánh giá đất nước ra khỏi khủng hoảng kinh tế–xã hội, tạo tiền đề chuyển sang thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa.", "page": 286, "evidence": "tựu to lớn, có ý nghĩa rất quan trọng. Nước ta đã ra khỏi khủng hoảng kinh tế - xã hội, nhưng một số mặt còn chưa vững chắc. Con đường đi lên chủ nghĩa xã hội ngày càng được xác định rõ hơn. Nhiệm vụ đề ra cho chặng đường đầu của thời kỳ quá độ là chuẩn bị tiền đề cho công nghiệp hóa đã cơ bản hoàn thành, cho phép chuyển sang thời kỳ mới: đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước.", "type": "mcq"}, {"id": "c3-q033", "section": "c3-s6", "prompt": "Theo quan điểm công nghiệp hóa thời kỳ mới tại Đại hội VIII, động lực của công nghiệp hóa, hiện đại hóa là gì?", "options": ["Khoa học và công nghệ", "Chỉ tăng số lượng lao động giản đơn", "Chỉ mở rộng khai thác tài nguyên", "Chỉ tăng quy mô trợ cấp"], "answer": 0, "explanation": "Đại hội VIII coi khoa học và công nghệ là động lực; phát huy nguồn lực con người là yếu tố cơ bản cho phát triển nhanh, bền vững.", "page": 287, "evidence": "tố cơ bản cho sự phát triển nhanh và bền vững. 4) Khoa học và công nghệ là động lực của công nghiệp hóa, hiện đại hóa; kết hợp công nghệ truyền thống với công nghệ hiện đại, tranh thủ đi nhanh vào hiện đại ở những khâu quyết định. 5) Lấy hiệu quả kinh tế - xã hội", "type": "mcq"}, {"id": "c3-q034", "section": "c3-s6", "prompt": "Quan điểm về văn hóa được Hội nghị Trung ương 5 khóa VIII nhấn mạnh là gì?", "options": ["Một hoạt động chỉ xuất hiện sau khi phát triển kinh tế xong", "Một lĩnh vực hoàn toàn tách khỏi con người", "Một bộ phận chỉ phục vụ trao đổi thương mại", "Nền tảng tinh thần của xã hội, vừa là mục tiêu vừa là động lực phát triển kinh tế–xã hội"], "answer": 3, "explanation": "Quan điểm này gắn xây dựng nền văn hóa tiên tiến, đậm đà bản sắc dân tộc với phát triển con người và kinh tế–xã hội.", "page": 294, "evidence": "đã ban hành Nghị quyết số 08-NQ/TW ngày 16/7/1998 về xây dựng và phát triển nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc, với quan điểm: Văn hóa là nền tảng tính thần của xã hội, vừa là mục tiêu vừa là động lực thúc đẩy sự phát triển kinh tế - xã hội. Xây dựng và phát triển kinh tế phải nhằm mục tiêu văn hóa, vì xã hội công bằng, văn minh, con người phát triển toàn diện. Nền văn hóa mà chúng ta xây dựng là nền văn hóa tiên tiến, đậm đà bản sắc dân tộc.", "type": "mcq"}, {"id": "c3-q035", "section": "c3-s7", "prompt": "Đại hội IX của Đảng họp vào thời gian nào?", "options": ["18–25/4/2006", "12–19/1/2011", "19–22/4/2001", "20–28/1/2016"], "answer": 2, "explanation": "Đại hội IX họp tại Hà Nội từ ngày 19 đến 22/4/2001, mở đầu thế kỷ XXI.", "page": 296, "evidence": " quốc lần thứ TX của Đảng họp tại Hà Nội, từ ngày 19 đến ngày 22/4/2001, là Đại hội mở đầu thế kỷ XXI cách mạng khoa học và công nghệ, kinh tế trì thức, toàn cầu hóa diễn ra mạnh mẽ. Sau sự kiện ngày 11/9/2001 ở Mỹ, một số nước lớn đã lợi dụng cuộc chiến chống khủng bố để tăng cường oan thiệp vào công việc nội bộ của nhiều nước.", "type": "mcq"}, {"id": "c3-q036", "section": "c3-s7", "prompt": "Mô hình kinh tế tổng quát của Việt Nam trong thời kỳ quá độ được Đại hội IX xác định là gì?", "options": ["Kinh tế tự cung tự cấp", "Kinh tế thị trường định hướng xã hội chủ nghĩa", "Kinh tế tập trung bao cấp không có thị trường", "Kinh tế chỉ có một hình thức sở hữu"], "answer": 1, "explanation": "Đại hội IX xác định thực hiện nhất quán, lâu dài nền kinh tế thị trường định hướng xã hội chủ nghĩa.", "page": 300, "evidence": "Đảng, Nhà nước chủ trương thực hiện nhất quán và lâu dài nền kinh tế thị trường định hướng xã hội chủ nghĩa; coi đây là mô hình kinh tế tổng quất của nước ta trong thời kỳ quá độ đi lên chủ nghĩa xã hội. Đó là nền kinh tế hàng hóa nhiều thành phần vận động theo cơ chế thị trường có sự quản lý của Nhà nước theo định hướng xã", "type": "mcq"}, {"id": "c3-q037", "section": "c3-s7", "prompt": "Theo nhận thức về con đường quá độ được nêu ở Đại hội IX, bỏ qua chế độ tư bản chủ nghĩa có đồng nghĩa bỏ qua thành tựu khoa học, công nghệ của nhân loại không?", "options": ["Không; vẫn tiếp thu, kế thừa thành tựu để phát triển lực lượng sản xuất", "Có; phải từ chối toàn bộ thành tựu khoa học", "Có; chỉ được sử dụng kỹ thuật sản xuất thủ công", "Có; không cần xây dựng nền kinh tế hiện đại"], "answer": 0, "explanation": "Bỏ qua việc xác lập vị trí thống trị của quan hệ sản xuất và kiến trúc thượng tầng tư bản chủ nghĩa, đồng thời kế thừa các thành tựu của nhân loại.", "page": 299, "evidence": " và kiến trúc thượng tầng tư bản chủ nghĩa, nhưng tiếp thu, kế thừa những thành tựu mà nhân loại đã đạt được dưới chế độ tư bản chủ nghĩa, đặc biệt về khoa học và công nghệ, để phát triển nhanh lực lượng sản xuất, xây dựng nền kinh tế hiện đại. Xây dựng chủ nghĩa", "type": "mcq"}, {"id": "c3-q038", "section": "c3-s8", "prompt": "Đại hội X của Đảng họp trong bối cảnh đất nước đã trải qua bao nhiêu năm đổi mới?", "options": ["10 năm", "30 năm", "35 năm", "20 năm"], "answer": 3, "explanation": "Đại hội X tháng 4/2006 diễn ra sau hai mươi năm tiến hành công cuộc đổi mới.", "page": 310, "evidence": "c) Đại hội đại biểu toàn quốc lần thứ X của Đảng và quá trình thực hiện Nghị quyết Đại hội Đại hội đại biểu toàn quốc lần thứ X của Đảng họp tại Hà Nội, từ ngày 18 đến ngày 25/4/2006, vào thời điểm đất nước đã trải qua 20 năm đổi mới, đạt những thành tựu to lớn có ý nghĩa lịch sử. Đất nước có sự thay đổi cơ bản, toàn điện, thế và lực, uy tín quốc tế tăng lên nhiều so với trước. Tình hình quốc tế điễn biến nhanh chóng, phức tạp, khó lường.", "type": "mcq"}, {"id": "c3-q039", "section": "c3-s8", "prompt": "Đại hội X xác định nhiệm vụ then chốt là gì?", "options": ["Chỉ phát triển công nghiệp nặng", "Chỉ mở rộng các hoạt động xuất khẩu", "Xây dựng, chỉnh đốn Đảng", "Thay đổi toàn bộ mục tiêu đổi mới"], "answer": 2, "explanation": "Xây dựng, chỉnh đốn Đảng được Đại hội X đặt ở vị trí nhiệm vụ then chốt.", "page": 312, "evidence": "chủ, văn minh; do nhân đân làm chủ; có nền kinh tế phát triển cao, đựa trên lực lượng sản xuất hiện đại và quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất; có nền văn hóa tiên tiến, đậm đà bản sắc dân tộc; con người được giải phóng khỏi áp bức, bất công, có cuộc sống ấm no, tự do, hạnh phúc, phát triển toàn diện; các dân tộc trong cộng đồng Việt Nam bình đẳng, đoàn kết, tương trợ và giúp đỡ nhau cùng tiến bộ; có Nhà nước pháp quyền xã hội chủ nghĩa của nhân dân, do nhân dân, vì nhân dân dưới sự lãnh đạo của Đảng Cộng sản; có quan hệ hữu nghị và hợp tác với nhân dân các nước trên thế giới. Đại hội X xác định nhiệm vụ then chốt là xây dựng, chỉnh đốn Đảng. Đây là thành tố đầu tiên của chủ đề Đại hội. Chính vì Đảng Cộng sản Việt Nam là Đảng cầm quyền duy nhất lãnh đạo cách mạng Việt Nam; mọi thành tựu và khuyết điểm ", "type": "mcq"}, {"id": "c3-q040", "section": "c3-s8", "prompt": "Đại hội X nhấn mạnh công nghiệp hóa, hiện đại hóa gắn với yếu tố nào?", "options": ["Duy trì sản xuất nhỏ tự cấp", "Phát triển kinh tế tri thức", "Thu hẹp ứng dụng khoa học", "Ngừng trao đổi kinh tế quốc tế"], "answer": 1, "explanation": "Đại hội X đề ra hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa và công nghiệp hóa, hiện đại hóa gắn kinh tế tri thức.", "page": 314, "evidence": "chủ nghĩa, đẩy mạnh công nghiệp hóa, hiện đại hóa gắn với phát triển kinh tế tri thức. Mở rộng quan hệ đối ngoại, chủ động, tích cực hội nhập kinh tế quốc tế, Việt Nam là bạn, đối tác tin cậy của các nước trong cộng đồng quốc tế. Đại hội X của Đảng là dấu mốc quan ", "type": "mcq"}, {"id": "c3-q041", "section": "c3-s8", "prompt": "Quan điểm của Hội nghị Trung ương 7 khóa X về nông nghiệp, nông dân, nông thôn là gì?", "options": ["Có vị trí chiến lược, cần giải quyết đồng bộ cả ba vấn đề", "Chỉ là nhiệm vụ của riêng ngành nông nghiệp", "Không liên quan tới công nghiệp hóa", "Chỉ tập trung sản lượng, không quan tâm đời sống nông dân"], "answer": 0, "explanation": "Nông nghiệp, nông dân, nông thôn có vị trí chiến lược; việc giải quyết phải đồng bộ và gắn với công nghiệp hóa, hiện đại hóa.", "page": 318, "evidence": "Quan điểm chỉ đạo của Trung ương là: Nông nghiệp, nông dân, nông thôn có vị trí chiến lược trong sự nghiệp công nghiệp hóa, hiện đại hóa, xây dựng và bảo vệ Tổ quốc, là cơ sở và lực lượng quan trọng để phát triển kinh tế - xã hội bền vững, giữ vững ổn định chính trị, đảm bảo an ninh, quốc phòng; giữ gìn, phát huy bản sắc văn hóa dân tộc và bảo vệ môi trường sinh thái của đất nước. Các vấn đề nông nghiệp, nông dân, nông thôn phải được giải quyết đồng bộ, gắn với quá trình đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước.", "type": "mcq"}, {"id": "c3-q042", "section": "c3-s8", "prompt": "Xây dựng đội ngũ trí thức được Hội nghị Trung ương 7 khóa X xem là đầu tư cho điều gì?", "options": ["Chỉ tăng số lượng bằng cấp", "Chỉ phục vụ một lĩnh vực thương mại", "Giảm vai trò nghiên cứu sáng tạo", "Phát triển bền vững"], "answer": 3, "explanation": "Giáo trình nêu xây dựng đội ngũ trí thức trực tiếp nâng tầm trí tuệ dân tộc, sức mạnh đất nước và là đầu tư cho phát triển bền vững.", "page": 328, "evidence": "Xây dựng đội ngũ trí thức vững mạnh là trực tiếp nâng tầm trí tuệ của dân tộc, sức mạnh của đất nước, nâng cao năng lực lãnh đạo của Đảng và chất lượng hoạt động của hệ thống chính trị. Đầu tư xây dựng đội ngũ trí thức là đầu tư cho phát triển bền vững. Xây dựng đội ngũ trí thức là trách nhiệm chung của toàn xã hội, của cả hệ thống chính trị, trong đó trách nhiệm của Đảng và Nhà nước giữ vai trò quyết định. Thực hành dân chủ, tôn trọng và phát huy tự do tư tưởng trong hoạt động nghiên cứu, sáng tạo của trí thức vì mục tiêu dân giàu, nước mạnh, xã hội công bằng, dân chủ, văn minh.", "type": "mcq"}, {"id": "c3-q043", "section": "c3-s8", "prompt": "Việt Nam trở thành thành viên thứ bao nhiêu của Tổ chức Thương mại thế giới (WTO)?", "options": ["100", "125", "150", "193"], "answer": 2, "explanation": "Giáo trình ghi Việt Nam trở thành thành viên thứ 150 của WTO trong giai đoạn thực hiện Nghị quyết Đại hội X.", "page": 334, "evidence": "nghiệm để phát triển đất nước. Việt Nam đã trở thành thành viên 150 của tổ chức WTO; đăng cai và tổ chức thành công tuần lễ cao cấp APEC (Diễn đàn kinh tế châu Á - Thái Bình Dương) lần thứ 14 (11/2006). Đến năm 2010, Việt Nara có quan hệ thương mại đầu tư với 230 nước và vùng lãnh thổ, trong đó các đối tác lớn nhất là Trung Quốc và Mỹ.", "type": "mcq"}, {"id": "c3-q044", "section": "c3-s9", "prompt": "Nội dung nổi bật của Đại hội XI năm 2011 là thông qua văn kiện nào?", "options": ["Cương lĩnh chính trị đầu tiên năm 1930", "Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội, bổ sung, phát triển năm 2011", "Chính cương Đảng Lao động Việt Nam năm 1951", "Luận cương chính trị tháng 10/1930"], "answer": 1, "explanation": "Đại hội XI thông qua Cương lĩnh bổ sung, phát triển năm 2011 trên cơ sở Cương lĩnh năm 1991.", "page": 335, "evidence": "Nội dung nổi bật của Đại hội XI là thông qua Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011); Chiến lược, phát triển kinh tế - xã hội 2011 - 2030. Đại hội đã bầu ra Ban Chấp hành Trung ương gồm 175 ủy viên chính thức và 2ð ủy viên dự khuyết, Bộ Chính trị gồm 14 đồng chí,", "type": "mcq"}, {"id": "c3-q045", "section": "c3-s9", "prompt": "Đặc trưng tổng quát nào thuộc mô hình xã hội mà Cương lĩnh năm 2011 nêu ra?", "options": ["Dân giàu, nước mạnh, dân chủ, công bằng, văn minh", "Chỉ phát triển kinh tế, không xét văn hóa", "Tách quyền làm chủ của nhân dân khỏi phát triển", "Từ bỏ mục tiêu công bằng xã hội"], "answer": 0, "explanation": "Cương lĩnh 2011 nêu mô hình xã hội dân giàu, nước mạnh, dân chủ, công bằng, văn minh; đặc trưng này được bổ sung so với Cương lĩnh 1991.", "page": 339, "evidence": " chủ nghĩa mà nhân dân ta xây dựng là một xã hội: Dân giàu, nước mạnh, dân chủ, công bằng, văn minh; do nhân dân làm chủ; có nền kinh tế phát triển cao dựa trên lực lượng sản xuất hiện đại và quan hệ sản xuất tiến bộ phù hợp; có nền văn hóa tiên tiến, đậm đà bản sắc dân tộc; con", "type": "mcq"}, {"id": "c3-q046", "section": "c3-s9", "prompt": "Cương lĩnh năm 2011 nêu bao nhiêu phương hướng cơ bản xây dựng chủ nghĩa xã hội?", "options": ["Năm phương hướng", "Sáu phương hướng", "Bảy phương hướng", "Tám phương hướng"], "answer": 3, "explanation": "Cương lĩnh bổ sung, phát triển năm 2011 nêu tám phương hướng cơ bản xây dựng chủ nghĩa xã hội.", "page": 340, "evidence": "Mục tiêu đến giữa thế kỷ XXI là xây dựng nước ta trở thành một nước công nghiệp hiện đại, theo định hướng xã hội chủ nghĩa. Cương lĩnh năm 2011 chỉ rõ tầm phương hướng cơ bản xây dựng chủ nghĩa xã hội ở nước ta: Một là, đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước gắn với phát triển kinh tế tri thức, bảo vệ tài nguyên, môi trường. Hai là, phát triển", "type": "mcq"}, {"id": "c3-q047", "section": "c3-s9", "prompt": "Mối quan hệ nào nằm trong tám mối quan hệ lớn nêu ở Cương lĩnh 2011?", "options": ["Giữa giảm giáo dục và tăng văn hóa", "Giữa đóng cửa đối ngoại và ngừng hợp tác", "Giữa đổi mới, ổn định và phát triển", "Giữa từ bỏ độc lập và tăng trưởng"], "answer": 2, "explanation": "Cương lĩnh 2011 yêu cầu giải quyết tốt các mối quan hệ lớn, trong đó có đổi mới, ổn định và phát triển.", "page": 341, "evidence": " 2011 yêu cầu giải quyết tốt tắm mối quan hệ lớn: Quan hệ giữa đổi mới, ổn định và phát triển; giữa đổi mới kinh tế và đổi mới chính trị; giữa kinh tế thị trường và định hướng xã hội chủ nghĩa; giữa phát triển lực lượng sản xuất và xây dựng, hoàn thiện từng bước quan hệ sản xuất xã hội chủ nghĩa; giữa tăng trưởng kinh tế và phát triển văn hóa, thực hiện tiến bộ và công bằng xã hội; giữa xây dựng chủ nghĩa xã hội và bảo vệ Tổ quốc xã hội chủ nghĩa; giữa độc lập, tự chủ và hội nhập quốc tế; giữa Đảng lãnh đạo, Nhà nước quản lý, nhân dân làm chủ.", "type": "mcq"}, {"id": "c3-q048", "section": "c3-s9", "prompt": "Theo Cương lĩnh 2011 được trình bày trong giáo trình, kinh tế tư nhân có vai trò gì?", "options": ["Thành phần không được pháp luật cho phép", "Một trong những động lực của nền kinh tế", "Bộ phận không có đóng góp lâu dài", "Thay thế mọi chức năng của Nhà nước"], "answer": 1, "explanation": "Cương lĩnh 2011 khẳng định kinh tế tư nhân là một trong những động lực của nền kinh tế; kinh tế nhà nước giữ vai trò chủ đạo.", "page": 342, "evidence": "Kinh tế nhà nước cùng với kinh tế tập thể ngày càng trở thành nền tảng vững chắc của nền kinh tế quốc dân; kinh tế tư nhân là một trong những động lực của nền kinh tế. Kinh tế có vốn đầu tư nước ngoài được khuyến khích phát triển”!, Phát triển kinh tế là nhiệm vụ trung tâm, thực hiện công nghiệp hóa, hiện đại hóa đất nước gắn với phát triển kinh tế trị thức, bảo vệ tài nguyên, môi trường; xây dựng œơ cấu kinh tế hợp lý, hiện đại, có hiệu quả và bền vững, gắn kết chặt chẽ công nghiệp, nông nghiệp, dịch vụ.", "type": "mcq"}, {"id": "c3-q049", "section": "c3-s9", "prompt": "Theo Cương lĩnh 2011, quyền lực nhà nước được tổ chức theo nguyên tắc nào?", "options": ["Thống nhất, có phân công, phối hợp và kiểm soát giữa các cơ quan thực hiện ba quyền", "Ba quyền hoạt động hoàn toàn không liên quan", "Chỉ có quyền hành pháp", "Chỉ phân quyền mà không có phối hợp hay kiểm soát"], "answer": 0, "explanation": "Quyền lực nhà nước là thống nhất; có phân công, phối hợp, kiểm soát trong thực hiện quyền lập pháp, hành pháp, tư pháp.", "page": 346, "evidence": "ngũ trí thức, do Đảng Cộng sản Việt Nam lãnh đạo. Quyền lực nhà nước là thống nhất; có sự phân công, phối hợp và kiểm soất giữa các cơ quan trong việc thực hiện các quyền lập pháp, hành pháp, tư pháp. Nhà nước ban hành pháp luật; tổ chức, quản lý xã hội bằng pháp luật, không ngừng tăng cường pháp chế xã hội chủ nghĩa.", "type": "mcq"}, {"id": "c3-q050", "section": "c3-s9", "prompt": "Ba đột phá chiến lược được Đại hội XI nêu ra tập trung vào những lĩnh vực nào?", "options": ["Quốc kỳ, Quốc ca, Quốc huy", "Giá, lương, tiền", "Quân sự, chính trị, binh vận", "Thể chế, nguồn nhân lực, kết cấu hạ tầng"], "answer": 3, "explanation": "Ba đột phá gồm hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa, phát triển nguồn nhân lực và xây dựng kết cấu hạ tầng đồng bộ.", "page": 349, "evidence": "Ba đột phá chiến lược: 1) Hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa, trọng tâm là tạo lập môi trường cạnh tranh bình đẳng và cải cách hành chính; 3) Phát triển nhanh nguồn nhân lực, nhất là nguồn nhân lực chất lượng cao, tập trung vào việc đổi mới căn bản và toàn diện nền giáo dục quốc đân; gắn kết chặt chẽ phát triển nguồn nhân lực với phát triển và ứng dụng khoa học, công nghệ; 3) Xây dựng hệ thống kết cấu hạ tầng đồng bộ với một số công trình hiện đại, tập trung vào hệ thống giao thông và hạ tầng đô thị lớn.", "type": "mcq"}, {"id": "c3-q051", "section": "c3-s9", "prompt": "Định hướng đổi mới giáo dục được nêu trong giai đoạn khóa XI là chuyển từ chủ yếu trang bị kiến thức sang điều gì?", "options": ["Chỉ ghi nhớ máy móc khối lượng kiến thức", "Chỉ đào tạo một nghề cố định", "Phát triển toàn diện năng lực và phẩm chất người học", "Tách giáo dục khỏi nhu cầu xã hội"], "answer": 2, "explanation": "Đổi mới căn bản, toàn diện giáo dục hướng tới phát triển năng lực và phẩm chất, gắn với nhu cầu phát triển kinh tế–xã hội.", "page": 361, "evidence": "trình giáo đục từ chủ yếu trang bị kiến thức sang phát triển toàn diện năng lực và phẩm chất người học; gắn với nhu cầu phát triển kinh tế - xã hội và bảo vệ Tổ quốc, với tiến bộ khoa học và công nghệ, Đổi mới hệ thống giáo dục theo hướng mở, linh hoạt, liên thông giữa các bậc học,", "type": "mcq"}, {"id": "c3-q052", "section": "c3-s9", "prompt": "Vấn đề trọng tâm, xuyên suốt và cấp bách nhất trong Nghị quyết Trung ương 4 khóa XI về xây dựng Đảng là gì?", "options": ["Chỉ thay đổi tên gọi các cơ quan", "Ngăn chặn, đẩy lùi suy thoái tư tưởng chính trị, đạo đức, lối sống", "Chỉ xây mới cơ sở vật chất", "Chỉ điều chỉnh địa giới hành chính"], "answer": 1, "explanation": "Nghị quyết nêu ba vấn đề cấp bách, trong đó vấn đề thứ nhất về chống suy thoái được xác định là trọng tâm, xuyên suốt, cấp bách nhất.", "page": 355, "evidence": "Nghị quyết chỉ rõ: tập trung cao độ lãnh đạo, chỉ đạo thực hiện tốt ba vấn đề cấp bách về xây dựng Đảng: Một là, kiên quyết đấu tranh ngăn chặn, đẩy lùi tình trạng suy thoái về tư tưởng chính trị, đạo đức, lối sống của một bộ phận không nhỏ cán bộ, đẳng viên, trước hết là cán bộ lãnh đạo, quản lý các cấp để nâng cao năng lực lãnh đạo, sức chiến đấu của Đảng, củng cố niềm tin của đẳng viên và của nhân dân đối với Đảng. Hai là, xây dựng đội ngũ cán bộ lãnh đạo, quản lý các cấp, nhất là cấp trung ương, đáp ứng yêu cầu của sự nghiệp công nghiệp hóa, hiện đại hóa và hội nhập quốc tế. Ba là, xác định rõ thẩm quyền, trách nhiệm người đứng đầu cấp ủy, chính quyền trong mối quan hệ với tập thể cấp ủy, cơ quan, đơn vị; tiếp tục đổi mới phương thức lãnh đạo của Đảng. Trong ba vấn đề trên, vấn để thứ nhất là trọng tâm, xuyên suốt và cấp bách nhất.", "type": "mcq"}, {"id": "c3-q053", "section": "c3-s9", "prompt": "Ban Chỉ đạo Trung ương về phòng, chống tham nhũng được nêu trong giai đoạn khóa XI trực thuộc cơ quan nào?", "options": ["Bộ Chính trị", "Một doanh nghiệp nhà nước", "Một tổ chức thương mại quốc tế", "Một hợp tác xã"], "answer": 0, "explanation": "Giáo trình nêu Ban Chỉ đạo trực thuộc Bộ Chính trị, do Tổng Bí thư làm Trưởng ban.", "page": 356, "evidence": "Ban Chỉ đạo Trung ương về phòng, chống tham nhũng trực thuộc Bộ Chính trị, do Tổng Bí thư làm Trưởng ban; lập lại Ban Nội chính Trung ương là cơ quan thường trực của Ban Chỉ đạo Trung ương về phòng, chống tham những. Sau một năm kiểm điểm, tự phê bình theo Nghị quyết Trung ương 4 khóa XI về xây dựng Đảng, Hội nghị Trung ương 6 khóa XI (10/2012) đã đánh giá kết quả kiểm điểm tự phê bình, phê bình khẳng định những thành tựu, ưu điểm, khuyết điểm của Bộ Chính trị, Ban Bí thư.", "type": "mcq"}, {"id": "c3-q054", "section": "c3-s9", "prompt": "Quan điểm văn hóa được Hội nghị Trung ương 9 khóa XI năm 2014 nhấn mạnh là gì?", "options": ["Văn hóa hoàn toàn đứng ngoài phát triển đất nước", "Chỉ phát triển kinh tế, chưa cần quan tâm con người", "Chỉ bảo tồn, không cần phát triển văn hóa", "Văn hóa phải được đặt ngang hàng với kinh tế, chính trị, xã hội"], "answer": 3, "explanation": "Nghị quyết về văn hóa, con người nhấn mạnh vị trí của văn hóa đối với phát triển bền vững đất nước.", "page": 361, "evidence": " mục tiêu, động lực phát triển bền vững đất nước. Văn hóa phải được đặt ngang hàng với kinh tế, chính trị, xã hội. Xây dựng nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc, thống nhất trong đa đạng của cộng đồng các dân tộc Việt Nam, với các đặc trưng dân", "type": "mcq"}, {"id": "c3-q055", "section": "c3-s10", "prompt": "Đại hội XII của Đảng họp vào thời gian nào?", "options": ["12–19/1/2011", "18–25/4/2006", "20–28/1/2016", "25/1–1/2/2021"], "answer": 2, "explanation": "Đại hội XII diễn ra từ 20 đến 28/1/2016, trong bối cảnh đất nước đã qua ba mươi năm đổi mới.", "page": 367, "evidence": "d) Đại hội đại biểu toàn quốc lần thứ XI đấy mạnh toàn điện, đồng bộ công cuộc đổi mồi, tích cực, chủ động hội nhập quốc tế Đại hội XH của Đảng họp từ ngày 20 đến ngày 28/1/2016, trong bối cảnh tình hình thế giới, khu vực diễn biến nhanh, rất phức tạp, khó lường. Đất nước đã qua 30 năm đổi mới, thế và lực tăng lên rõ rệt, có cả những thuận lợi, thời cơ đan xen với những khó khăn, thách thức gay gắt.", "type": "mcq"}, {"id": "c3-q056", "section": "c3-s10", "prompt": "Đại hội XII đặc biệt nhấn mạnh thực hiện bao nhiêu nhiệm vụ trọng tâm?", "options": ["Ba nhiệm vụ", "Sáu nhiệm vụ", "Bốn nhiệm vụ", "Tám nhiệm vụ"], "answer": 1, "explanation": "Sáu nhiệm vụ trọng tâm được trình bày từ trang 370 đến trang 371 của giáo trình.", "page": 370, "evidence": " tập trung lãnh đạo, chỉ đạo thực hiện có kết quả sáu nhiệm vụ trọng tâm: (1) Tăng cường xây đựng, chỉnh đốn Đảng; ngăn chặn, đẩy lùi sự suy thoái về tư tưởng chính trị, đạo đức, lối sống, biểu hiện “tự điễn biến”, “tự chuyển hóa” trong nội bộ. Tập trung xây dựng đội ngũ cán bộ, nhất là đội ngũ cần bộ cấp chiến lược, đủ năng lực, phẩm chất và uy tín, ngang tầm nhiệm vụ.", "type": "mcq"}, {"id": "c3-q057", "section": "c3-s10", "prompt": "Theo tổng kết tại Đại hội XII, nhiệm vụ nào là trung tâm?", "options": ["Phát triển kinh tế–xã hội", "Xây dựng Đảng", "Thay đổi Quốc ca", "Tổ chức lại toàn bộ địa giới"], "answer": 0, "explanation": "Đại hội XII gắn kết các nhiệm vụ: phát triển kinh tế–xã hội là trung tâm; xây dựng Đảng là then chốt; văn hóa là nền tảng tinh thần.", "page": 368, "evidence": "Ba là, gắn kết chặt chẽ và triển khai đồng bộ các nhiệm vụ phát triển kinh tế - xã hội là trung tâm; xây dựng Đảng là then chốt; phát triển văn hóa - nền tảng tình thần của xã hội; bảo đảm quốc phòng và an ninh là nhiệm vụ trọng yếu, thường xuyên. Bốn là, kiên trì thực hiện các ", "type": "mcq"}, {"id": "c3-q058", "section": "c3-s10", "prompt": "Đổi mới mô hình tăng trưởng theo chủ trương năm 2016 cần ngày càng dựa nhiều hơn vào yếu tố nào?", "options": ["Chỉ tăng lượng lao động và vốn đầu tư", "Chỉ tăng khai thác tài nguyên thô", "Chỉ tăng bao cấp bằng ngân sách", "Tăng năng suất lao động, khoa học–công nghệ và sử dụng hiệu quả nguồn lực"], "answer": 3, "explanation": "Chủ trương chú trọng chất lượng tăng trưởng, năng suất, sức cạnh tranh và phát triển bền vững cả kinh tế, xã hội, môi trường.", "page": 372, "evidence": " ngày càng dựa nhiều hơn vào các nhân tố thúc đẩy tăng năng suất lao động, sử dụng hiệu quả các nguồn lực, đặc biệt là phát huy tĩnh thần yêu nước, lòng tự hào, tự tôn dân tộc, trí sáng tạo của eon người Việt Nam và thành tựu khoa học - công nghệ của nhân loại, mọi tiềm năng, lợi thế của các ngành, lĩnh vực, các địa phương và cả nước.", "type": "mcq"}, {"id": "c3-q059", "section": "c3-s10", "prompt": "Chủ trương năm 2017 xác định kinh tế tư nhân cần trở thành yếu tố nào của nền kinh tế thị trường định hướng xã hội chủ nghĩa?", "options": ["Thành phần duy nhất được tồn tại", "Một lĩnh vực chỉ được hoạt động ở nông nghiệp", "Một động lực quan trọng", "Bộ phận không cần tuân thủ pháp luật"], "answer": 2, "explanation": "Phát triển kinh tế tư nhân thành một động lực quan trọng phải gắn với kinh tế tư nhân lành mạnh, đúng định hướng và tuân thủ pháp luật.", "page": 378, "evidence": " 3/6/2017 về phát triển kinh tế tư nhân trở thành một động lực quan trọng của nền kinh tế thị trường định hướng xã hội chủ nghĩa. Quan điểm chỉ đạo của Trung ương là: Phát triển kinh tế tư nhân lành mạnh theo eơ chế thị trường là một yêu cầu khách quan,", "type": "mcq"}, {"id": "c3-q060", "section": "c3-s10", "prompt": "Chiến lược kinh tế biển năm 2018 nhấn mạnh nguyên tắc nào?", "options": ["Phát triển kinh tế biển tách khỏi bảo vệ môi trường", "Phát triển bền vững kinh tế biển gắn với quốc phòng, an ninh và bảo vệ chủ quyền", "Khai thác biển không cần hợp tác quốc tế", "Chỉ khai thác tài nguyên, không quan tâm an toàn"], "answer": 1, "explanation": "Giáo trình gắn phát triển kinh tế biển bền vững với bảo đảm quốc phòng, an ninh, độc lập, chủ quyền và hợp tác quốc tế.", "page": 380, "evidence": "Việt Nam phải trở thành quốc gia mạnh về biển, giàu từ biển, phát triển bền vững, thịnh vượng, an ninh và an toàn; phất triển bền vững kinh tế biển gắn liền với bảo đầm quốc phồng, an ninh, giữ vững độc lập, chủ quyền và toàn vẹn lãnh thổ, tăng cường đối ngoại, hợp tác quốc tế về biển, góp phần duy trì môi trường hòa bình; ổn định cho phát triển.", "type": "mcq"}, {"id": "c3-q061", "section": "c3-s10", "prompt": "Chỉ thị 05-CT/TW ngày 15/5/2016 yêu cầu đẩy mạnh học tập và làm theo nội dung nào?", "options": ["Tư tưởng, đạo đức, phong cách Hồ Chí Minh", "Chỉ các phương pháp quản lý tài chính", "Chỉ kỹ thuật sản xuất công nghiệp", "Chỉ quy chế thương mại quốc tế"], "answer": 0, "explanation": "Chỉ thị 05 mở rộng nội dung học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh, gắn với xây dựng, chỉnh đốn Đảng.", "page": 381, "evidence": "TW ngày 15/5/2016 về đẩy mạnh học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh, coi đây là nội dung quan trọng của công tác xây dựng, chỉnh đốn Đảng; góp phần xây dựng Đẳng trong sạch, vững mạnh về chính trị, tư tưởng, tổ chức và đạo đức, xây dựng đội ngũ cần bộ, nhất là đội ngũ cán bộ cấp chiến lược đủ năng lực, phẩm chất, ngang tầm nhiệm vụ.", "type": "mcq"}, {"id": "c3-q062", "section": "c3-s11", "prompt": "Đại hội XIII của Đảng diễn ra vào thời gian nào?", "options": ["20–28/1/2016", "12–19/1/2011", "19–22/4/2001", "25/1–1/2/2021"], "answer": 3, "explanation": "Đại hội XIII diễn ra tại Hà Nội từ ngày 25/1 đến 1/2/2021.", "page": 386, "evidence": "e) Đại hội đại biểu toàn quốc lần thứ XIH của Đảng, tiếp tục đẩy mạnh toàn diện, đồng bộ công cuộc đổi mới, phấn đấu đến giữa thế kỷ XXIL nước ta trở thành nước phát triển theo định hướng xã hội chủ nghĩa Đại hội XIII của Đẳng diễn ra từ ngày 25/1 đến ngày 1/2/2021 tại Thủ đô Hà Nội, trong bối cảnh đất nước đang đứng trước nhiều thời cơ và thách thức đan xen, nhiều vấn để chiến lược mới đặt ra cần phải giải quyết, từ tình hình quốc tế, khu vực dự báo tiếp tục điễn biến phức tạp, khó lường đến các thách thức mang tính toàn cầu về biến đổi khí hậu, thiên tai, dịch bệnh và cả những thành tựu ngoạn mục của tiến bộ khoa học và công nghệ đang tác động, ảnh hưởng mạnh mẽ tới đời sống kinh tế - xã hội của đất nước ta cũng như toàn thế giới.", "type": "mcq"}, {"id": "c3-q063", "section": "c3-s11", "prompt": "Đại hội XIII gắn đánh giá việc thực hiện Nghị quyết Đại hội XII với tổng kết bao nhiêu năm đổi mới?", "options": ["15 năm", "20 năm", "35 năm", "25 năm"], "answer": 2, "explanation": "Đại hội XIII đánh giá ba mươi lăm năm đổi mới, ba mươi năm thực hiện Cương lĩnh 1991 và mười năm thực hiện Cương lĩnh 2011.", "page": 387, "evidence": "Đại hội XHI của Đảng đã tổng kết việc thực hiện Nghị quyết Đại hội lần thứ XIT gắn với việc đánh giá 35 năm tiến hành công cuộc đổi mới, 30 năm thực hiện Cương lĩnh năm 1991, 10 năm thực hiện Cương lĩnh (bổ sung, phát triển năm 2011), Chiến lược phát triển kinh tế - xã hội 2011 - 2020: đề ra phương hướng, nhiệm vụ", "type": "mcq"}, {"id": "c3-q064", "section": "c3-s11", "prompt": "Theo quan điểm chỉ đạo Đại hội XIII được ghi trong giáo trình, mục tiêu nào phải được bảo đảm cao nhất?", "options": ["Lợi ích riêng của từng nhóm nhỏ", "Lợi ích quốc gia–dân tộc", "Tăng trưởng bằng mọi giá, không xét môi trường", "Chỉ mở rộng số lượng doanh nghiệp"], "answer": 1, "explanation": "Đại hội XIII nhấn mạnh lợi ích quốc gia–dân tộc trên cơ sở các nguyên tắc Hiến chương Liên hợp quốc và luật pháp quốc tế.", "page": 388, "evidence": "vệ vững chắc Tổ quốc Việt Nam xã hội chủ nghĩa. - Bảo đảm cao nhất lợi ích quốc gia - đân tộc trên cơ sở các nguyên tắc cơ bản của Hiến chương Liên hợp quốc và luật pháp quốc tế, bình đẳng, hợp tác, cùng có lợi. Tiếp tục phát triển nhanh và bền vững đất nước; gắn", "type": "mcq"}, {"id": "c3-q065", "section": "c3-s11", "prompt": "Nhiệm vụ về ứng dụng thành tựu Cách mạng công nghiệp lần thứ tư trong Đại hội XIII bao gồm nội dung nào?", "options": ["Chuyển đổi số quốc gia, phát triển kinh tế số", "Ngừng đổi mới sáng tạo", "Chỉ sử dụng thông tin dạng giấy", "Tách doanh nghiệp khỏi ứng dụng khoa học"], "answer": 0, "explanation": "Đại hội XIII chú trọng chuyển đổi số quốc gia, phát triển kinh tế số để nâng cao năng suất, chất lượng, hiệu quả và sức cạnh tranh.", "page": 391, "evidence": " cuộc Cách mạng công nghiệp lần thứ tư, thực hiện chuyển đổi số quốc gia, phát triển kinh tế số, nâng cao năng suất, chất lượng, hiệu quả, sức cạnh tranh của nền kinh tế; huy động, phân bổ, sử dụng có hiệu quả các nguồn lực, tạo động lực để phát triển ", "type": "mcq"}, {"id": "c3-q066", "section": "c3-s12", "prompt": "Theo mục tiêu được ghi trong giáo trình năm 2021, Việt Nam phấn đấu đạt vị thế nào vào năm 2030?", "options": ["Nước phát triển, thu nhập cao", "Nước đang phát triển, vượt mức thu nhập trung bình thấp", "Nước đã kết thúc toàn bộ thời kỳ quá độ", "Nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao"], "answer": 3, "explanation": "Đây là mục tiêu đến năm 2030 được trình bày trong giáo trình, không phải khẳng định về kết quả hiện tại.", "page": 407, "evidence": " hiện đại, vượt qua mức thu nhập trung bình thấp; đến năm 2030, là nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao; đến năm 2045, trở thành nước phát triển, thu nhập cao. C. CÂU HỎI ÔN TẬP. 1. Khái quát quá trình xây dựng chủ nghĩa xã hội trên cả nước và quá trình tìm con đường đổi mới đất nước?", "type": "mcq"}, {"id": "c3-q067", "section": "c3-s12", "prompt": "Theo tầm nhìn được ghi trong giáo trình, mục tiêu đến năm 2045 là gì?", "options": ["Chỉ đạt mức thu nhập trung bình thấp", "Bắt đầu công cuộc đổi mới", "Trở thành nước phát triển, thu nhập cao", "Chỉ hoàn thành thống nhất nhà nước"], "answer": 2, "explanation": "Giáo trình năm 2021 nêu mục tiêu đến năm 2045 trở thành nước phát triển, thu nhập cao.", "page": 407, "evidence": "có công nghiệp hiện đại, thu nhập trung bình cao; đến năm 2045, trở thành nước phát triển, thu nhập cao. C. CÂU HỎI ÔN TẬP. 1. Khái quát quá trình xây dựng chủ nghĩa xã hội trên cả nước và quá trình tìm con đường đổi mới đất nước? 407", "type": "mcq"}, {"id": "c3-q068", "section": "c3-s12", "prompt": "Mối quan hệ lớn mới được bổ sung tại Đại hội XIII là gì?", "options": ["Giảm dân chủ để tăng mọi loại thủ tục", "Thực hành dân chủ với tăng cường pháp chế, bảo đảm kỷ cương xã hội", "Tăng trưởng kinh tế với bỏ qua bảo vệ môi trường", "Hội nhập quốc tế với từ bỏ độc lập"], "answer": 1, "explanation": "Đại hội XIII bổ sung mối quan hệ giữa thực hành dân chủ và tăng cường pháp chế, bảo đảm kỷ cương xã hội.", "page": 402, "evidence": "hệ sản xuất xã hội chủ nghĩa; giữa nhà nước, thị trường và xã hội; giữa tăng trưởng kinh tế và phát triển văn hóa, thực hiện tiến bộ và công bằng xã hội, bảo vệ môi trường; giữa xây dựng và bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa; giữa độc lập, tự chủ và hội nhập quốt tế: giữa Đảng lãnh đạo, Nhà nước quần lý và nhân dân làm chủ; và đặc biệt, mối quan hệ mới được bổ sung lần này là mối quan hệ giữa thực hành dân chủ và tăng cường pháp chế, bảo đảm kỷ cương xã hội). Những mối quan hệ lớn phản ánh những quy luật mang tính biện chứng, những vấn đề lý", "type": "mcq"}, {"id": "c3-q069", "section": "c3-s12", "prompt": "Trong các nguyên nhân của hạn chế, khuyết điểm trong đổi mới được giáo trình tổng kết, nguyên nhân nào là chủ yếu?", "options": ["Nguyên nhân chủ quan", "Chỉ do thiên tai", "Chỉ do tình hình thế giới", "Chỉ do thiếu tài nguyên"], "answer": 0, "explanation": "Giáo trình phân tích cả nguyên nhân khách quan và chủ quan, nhấn mạnh nguyên nhân chủ quan là chủ yếu.", "page": 403, "evidence": "nhân khách quan và nguyên nhân chủ quan, trong đó nguyên nhân chủ quan là chủ yếu Về khách quan: Đổi mới là một sự nghiệp to lớn, toàn diện, lâu dài, rất khó khăn, phức tạp, chưa có tiền lệ trong lịch sử. Tình hình thế giới và khu vực có những mặt tác động không thuận lợi; sự chống phá quyết liệt của các thế lực thù địch, phản động và cơ hội chính trị.", "type": "mcq"}, {"id": "c3-q070", "section": "c3-s12", "prompt": "Bài học về nhân dân trong tổng kết công cuộc đổi mới nhấn mạnh quan điểm nào?", "options": ["Nhân dân chỉ là người thụ hưởng, không tham gia", "Chủ trương không cần xét nguyện vọng nhân dân", "Chỉ cần nguồn lực bên ngoài để phát triển", "Dân là gốc; nhân dân là trung tâm, là chủ thể của công cuộc đổi mới"], "answer": 3, "explanation": "Mọi chủ trương, chính sách phải xuất phát từ yêu cầu, nguyện vọng, quyền và lợi ích hợp pháp, chính đáng của nhân dân.", "page": 405, "evidence": "Hailà, trong mọi công việc của Đảng và Nhà nước, phải luôn quán triệt sâu sắc, thực hiện nghiêm túc quan điểm “dân là gốc”; thật sự tin tưởng, tôn trọng và phát huy quyền làm chủ của nhân dân, kiên trì thực hiện phương châm “đân biết, dân bàn, dân làm, dân kiểm tra, dân giám sát, dân thụ hưởng” Nhân dân là trung tâm, là chủ thể của công cuộc đổi mới, xây dựng và bảo vệ Tổ quốc;", "type": "mcq"}], "mindmap": {"title": "Từ thống nhất đến đổi mới", "branches": [{"id": "c3-b1", "title": "Thống nhất về mặt nhà nước", "page": 240, "summary": "Tạo điều kiện thống nhất trên các lĩnh vực khác.", "children": [{"title": "25/4/1976", "page": 240, "note": "Tổng tuyển cử bầu Quốc hội chung."}, {"title": "Kỳ họp Quốc hội thống nhất", "page": 241, "note": "Tên nước: Cộng hòa xã hội chủ nghĩa Việt Nam."}, {"title": "Ý nghĩa", "page": 242, "note": "Cơ sở phát huy sức mạnh toàn diện, đưa cả nước lên chủ nghĩa xã hội."}]}, {"id": "c3-b2", "title": "Đại hội IV và bước đột phá 1979", "page": 242, "summary": "Đường lối xây dựng chủ nghĩa xã hội sau thống nhất.", "children": [{"title": "Đại hội IV", "page": 242, "note": "14–20/12/1976; đổi tên Đảng."}, {"title": "Trung ương 6", "page": 246, "note": "Tháng 8/1979, bước đột phá đầu tiên về đổi mới kinh tế."}, {"title": "Khoán 100", "page": 247, "note": "Khoán sản phẩm đến nhóm và người lao động."}]}, {"id": "c3-b3", "title": "Bảo vệ Tổ quốc", "page": 248, "summary": "Gắn xây dựng đất nước với quốc phòng và nghĩa vụ quốc tế.", "children": [{"title": "Biên giới Tây Nam", "page": 249, "note": "Đánh đuổi quân xâm lược, giúp Campuchia thoát chế độ diệt chủng."}, {"title": "Biên giới phía Bắc", "page": 250, "note": "Chiến đấu bảo vệ Tổ quốc từ tháng 2/1979."}, {"title": "Nghĩa vụ quốc tế", "page": 249, "note": "Hợp tác, giúp đỡ Campuchia bảo vệ và hồi sinh đất nước."}]}, {"id": "c3-b4", "title": "Đại hội V và tìm đường đổi mới", "page": 251, "summary": "Hai nhiệm vụ chiến lược và những bước điều chỉnh kinh tế.", "children": [{"title": "Đại hội V", "page": 253, "note": "Xây dựng chủ nghĩa xã hội gắn với bảo vệ Tổ quốc."}, {"title": "Đột phá thứ hai", "page": 255, "note": "Tháng 6/1985, giá–lương–tiền."}, {"title": "Đột phá thứ ba", "page": 256, "note": "Tháng 8/1986, kết luận về các quan điểm kinh tế."}]}, {"id": "c3-b5", "title": "Đại hội VI: đổi mới toàn diện", "page": 260, "summary": "Đổi mới tư duy, trước hết là tư duy kinh tế.", "children": [{"title": "Kinh tế nhiều thành phần", "page": 262, "note": "Xóa bao cấp, kết hợp kế hoạch với thị trường."}, {"title": "Ba chương trình kinh tế", "page": 262, "note": "Lương thực–thực phẩm, hàng tiêu dùng, hàng xuất khẩu."}, {"title": "Khoán 10", "page": 266, "note": "Nghị quyết ngày 5/4/1988 về quản lý kinh tế nông nghiệp."}]}, {"id": "c3-b6", "title": "Đại hội VII và Cương lĩnh 1991", "page": 272, "summary": "Cụ thể hóa con đường quá độ lên chủ nghĩa xã hội.", "children": [{"title": "Sáu đặc trưng", "page": 273, "note": "Mô hình xã hội xã hội chủ nghĩa trong Cương lĩnh 1991."}, {"title": "Nền tảng tư tưởng", "page": 275, "note": "Chủ nghĩa Mác–Lênin và tư tưởng Hồ Chí Minh."}, {"title": "Mở rộng đối ngoại", "page": 281, "note": "ASEAN và quan hệ ngoại giao với Hoa Kỳ năm 1995."}, {"title": "Bốn nguy cơ", "page": 283, "note": "Tụt hậu, chệch hướng, tham nhũng–quan liêu, diễn biến hòa bình."}]}, {"id": "c3-b7", "title": "Đại hội VIII: công nghiệp hóa", "page": 285, "summary": "Chuyển sang thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa.", "children": [{"title": "Tiền đề mới", "page": 286, "note": "Ra khỏi khủng hoảng kinh tế–xã hội, một số mặt chưa vững chắc."}, {"title": "Con người và khoa học", "page": 287, "note": "Nguồn lực con người là yếu tố cơ bản; khoa học–công nghệ là động lực."}, {"title": "Văn hóa", "page": 294, "note": "Tiên tiến, đậm đà bản sắc dân tộc; nền tảng tinh thần của xã hội."}]}, {"id": "c3-b8", "title": "Đại hội IX: mô hình kinh tế", "page": 296, "summary": "Phát triển và cụ thể hóa đường lối đầu thế kỷ XXI.", "children": [{"title": "Mô hình tổng quát", "page": 300, "note": "Kinh tế thị trường định hướng xã hội chủ nghĩa."}, {"title": "Con đường quá độ", "page": 299, "note": "Bỏ qua chế độ tư bản chủ nghĩa nhưng kế thừa thành tựu nhân loại."}, {"title": "Hội nhập", "page": 300, "note": "Độc lập tự chủ, đa phương hóa, đa dạng hóa quan hệ quốc tế."}]}, {"id": "c3-b9", "title": "Đại hội X: đổi mới và hội nhập", "page": 310, "summary": "Nâng cao năng lực lãnh đạo, phát huy sức mạnh toàn dân tộc.", "children": [{"title": "Nhiệm vụ then chốt", "page": 312, "note": "Xây dựng, chỉnh đốn Đảng."}, {"title": "Kinh tế tri thức", "page": 314, "note": "Gắn với công nghiệp hóa, hiện đại hóa."}, {"title": "Nông nghiệp, nông dân, nông thôn", "page": 318, "note": "Giải quyết đồng bộ, có vị trí chiến lược."}, {"title": "WTO", "page": 334, "note": "Việt Nam là thành viên thứ 150."}]}, {"id": "c3-b10", "title": "Đại hội XI và Cương lĩnh 2011", "page": 335, "summary": "Bổ sung nhận thức về mô hình, phương hướng và các quan hệ lớn.", "children": [{"title": "Tám đặc trưng", "page": 339, "note": "Mô hình xã hội xã hội chủ nghĩa được bổ sung, phát triển."}, {"title": "Tám phương hướng", "page": 340, "note": "Cương lĩnh năm 2011 nêu tám phương hướng cơ bản xây dựng chủ nghĩa xã hội; nội dung tiếp ở trang 341."}, {"title": "Tám mối quan hệ lớn", "page": 341, "note": "Giải quyết các quan hệ giữa đổi mới, ổn định, phát triển; kinh tế và chính trị; xây dựng và bảo vệ; độc lập và hội nhập cùng các quan hệ lớn khác."}, {"title": "Ba đột phá", "page": 349, "note": "Thể chế, nguồn nhân lực, kết cấu hạ tầng."}, {"title": "Xây dựng, chỉnh đốn Đảng", "page": 355, "note": "Ngăn chặn, đẩy lùi suy thoái về tư tưởng chính trị, đạo đức, lối sống là vấn đề trọng tâm, xuyên suốt và cấp bách nhất."}, {"title": "Đổi mới giáo dục", "page": 361, "note": "Chuyển từ chủ yếu trang bị kiến thức sang phát triển toàn diện năng lực và phẩm chất người học."}, {"title": "Văn hóa và con người", "page": 361, "note": "Văn hóa là nền tảng tinh thần, mục tiêu và động lực phát triển bền vững; phải đặt ngang hàng với kinh tế, chính trị, xã hội."}]}, {"id": "c3-b11", "title": "Đại hội XII: đồng bộ công cuộc đổi mới", "page": 367, "summary": "Tăng chất lượng tăng trưởng, xây dựng Đảng và bảo vệ Tổ quốc.", "children": [{"title": "Sáu nhiệm vụ trọng tâm", "page": 370, "note": "Gắn kinh tế, xây dựng Đảng, quốc phòng, xã hội và con người."}, {"title": "Kinh tế tư nhân", "page": 378, "note": "Một động lực quan trọng của nền kinh tế."}, {"title": "Kinh tế biển", "page": 380, "note": "Phát triển bền vững gắn bảo vệ chủ quyền."}, {"title": "Học tập và làm theo Hồ Chí Minh", "page": 381, "note": "Tư tưởng, đạo đức, phong cách gắn xây dựng Đảng."}]}, {"id": "c3-b12", "title": "Đại hội XIII: khát vọng phát triển", "page": 386, "summary": "Đánh giá 35 năm đổi mới, xác định mục tiêu và tầm nhìn.", "children": [{"title": "Lợi ích quốc gia–dân tộc", "page": 388, "note": "Bảo đảm cao nhất trên cơ sở luật pháp quốc tế."}, {"title": "Đổi mới sáng tạo", "page": 391, "note": "Chuyển đổi số quốc gia, phát triển kinh tế số."}, {"title": "Tầm nhìn 2045", "page": 407, "note": "Mục tiêu nước phát triển, thu nhập cao được ghi trong giáo trình 2021."}]}, {"id": "c3-b13", "title": "Thành tựu và hạn chế", "page": 394, "summary": "Đánh giá toàn diện, không chỉ liệt kê thành tích.", "children": [{"title": "Thành tựu", "page": 394, "note": "Chuyển đổi kinh tế; phát triển đất nước trên nhiều lĩnh vực."}, {"title": "Hạn chế", "page": 402, "note": "Thể chế, năng suất, chất lượng tăng trưởng và nhiều lĩnh vực còn bất cập."}, {"title": "Nguyên nhân", "page": 403, "note": "Có nguyên nhân khách quan và chủ quan, chủ quan là chủ yếu."}]}, {"id": "c3-b14", "title": "Bài học của đổi mới", "page": 404, "summary": "Kết nối xây dựng Đảng, nhân dân, tổ chức thực hiện và hội nhập.", "children": [{"title": "Xây dựng Đảng", "page": 405, "note": "Cán bộ là then chốt của then chốt; đề cao trách nhiệm nêu gương."}, {"title": "Dân là gốc", "page": 405, "note": "Nhân dân là trung tâm, chủ thể của công cuộc đổi mới."}, {"title": "Thực hiện và thể chế", "page": 406, "note": "Quyết tâm, hành động hiệu quả, giải quyết hài hòa các quan hệ."}, {"title": "Dự báo và hội nhập", "page": 407, "note": "Chủ động, giữ vững độc lập tự chủ, phát huy sức mạnh tổng hợp."}]}]}, "timeline": [{"year": "1976", "title": "Thống nhất về mặt nhà nước", "page": 240, "description": "Tổng tuyển cử 25/4 và kỳ họp Quốc hội thống nhất."}, {"year": "1976", "title": "Đại hội IV", "page": 242, "description": "Đường lối đưa cả nước lên chủ nghĩa xã hội."}, {"year": "1979", "title": "Bước đột phá đầu tiên", "page": 246, "description": "Hội nghị Trung ương 6 tháng 8/1979."}, {"year": "1981", "title": "Khoán 100", "page": 247, "description": "Khoán sản phẩm đến nhóm và người lao động."}, {"year": "1982", "title": "Đại hội V", "page": 251, "description": "Xác định hai nhiệm vụ chiến lược."}, {"year": "1985–1986", "title": "Hai bước đột phá tiếp theo", "page": 255, "description": "Giá–lương–tiền và kết luận về quan điểm kinh tế."}, {"year": "1986", "title": "Đại hội VI", "page": 260, "description": "Khởi xướng đường lối đổi mới toàn diện."}, {"year": "1988", "title": "Khoán 10", "page": 266, "description": "Đổi mới quản lý kinh tế nông nghiệp."}, {"year": "1991", "title": "Đại hội VII", "page": 272, "description": "Thông qua Cương lĩnh 1991."}, {"year": "1995", "title": "Mở rộng quan hệ quốc tế", "page": 281, "description": "Gia nhập ASEAN, thiết lập quan hệ ngoại giao với Hoa Kỳ."}, {"year": "1996", "title": "Đại hội VIII", "page": 285, "description": "Đẩy mạnh công nghiệp hóa, hiện đại hóa."}, {"year": "2001", "title": "Đại hội IX", "page": 296, "description": "Cụ thể hóa mô hình kinh tế tổng quát."}, {"year": "2006", "title": "Đại hội X", "page": 310, "description": "Tổng kết 20 năm đổi mới, đẩy mạnh hội nhập."}, {"year": "2011", "title": "Đại hội XI", "page": 335, "description": "Bổ sung, phát triển Cương lĩnh 1991."}, {"year": "2016", "title": "Đại hội XII", "page": 367, "description": "Đổi mới toàn diện, đồng bộ."}, {"year": "2021", "title": "Đại hội XIII", "page": 386, "description": "Tổng kết 35 năm đổi mới, xác định tầm nhìn phát triển."}], "reviewPrompts": [{"prompt": "Khái quát quá trình xây dựng chủ nghĩa xã hội trên cả nước và quá trình tìm con đường đổi mới đất nước?", "page": 407}, {"prompt": "Nội dung đường lối đổi mới toàn diện của Đại hội VI của Đảng (12/1986) và quá trình thực hiện?", "page": 408}, {"prompt": "Nội dung Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (năm 1991 và bổ sung, phát triển năm 2011)?", "page": 408}, {"prompt": "Vai trò lãnh đạo của Đảng đối với sự nghiệp đổi mới, công nghiệp hóa hiện đại hóa đất nước và hội nhập quốc tế?", "page": 408}, {"prompt": "Thành tựu, ý nghĩa lịch sử và kinh nghiệm lãnh đạo của Đảng trong sự nghiệp đổi mới?", "page": 408}], "sourceCorrections": [{"page": 238, "ocr": "Sau đại thắng mùa xuân năm 1976", "corrected": "Sau đại thắng mùa xuân năm 1975"}, {"page": 242, "ocr": "Đại hội đại biểu toàn quốc lần thứ TV", "corrected": "Đại hội đại biểu toàn quốc lần thứ IV"}, {"page": 251, "ocr": "đổi mới kinh tế 1985 - 1986", "corrected": "đổi mới kinh tế 1982 - 1986"}, {"page": 260, "ocr": "từ ngày lõ đến ngày 18/12/1986", "corrected": "từ ngày 15 đến ngày 18/12/1986"}, {"page": 272, "ocr": "Đại hội đại biểu toàn quốc lần thứ VHI", "corrected": "Đại hội đại biểu toàn quốc lần thứ VII"}, {"page": 273, "ocr": "sầu đặc trưng cơ bản", "corrected": "sáu đặc trưng cơ bản"}, {"page": 275, "ocr": "Đại hội VI lần đầu tiên thông qua Chiến lược", "corrected": "Đại hội VII lần đầu tiên thông qua Chiến lược"}, {"page": 285, "ocr": "lần thứ VHI", "corrected": "lần thứ VIII"}, {"page": 294, "ocr": "Nghị quyết số 08-NQ/TW ngày 16/7/1998", "corrected": "Nghị quyết số 03-NQ/TW ngày 16/7/1998"}, {"page": 296, "ocr": "lần thứ TX", "corrected": "lần thứ IX"}, {"page": 335, "ocr": "Chiến lược, phát triển kinh tế - xã hội 2011 - 2030", "corrected": "Chiến lược, phát triển kinh tế - xã hội 2011 - 2020"}, {"page": 340, "ocr": "tầm phương hướng cơ bản", "corrected": "tám phương hướng cơ bản"}, {"page": 349, "ocr": "3) Phát triển nhanh nguồn nhân lực", "corrected": "2) Phát triển nhanh nguồn nhân lực"}, {"page": 367, "ocr": "lần thứ XI đấy mạnh", "corrected": "lần thứ XII đẩy mạnh"}, {"page": 367, "ocr": "Đại hội XH của Đảng", "corrected": "Đại hội XII của Đảng"}, {"page": 386, "ocr": "lần thứ XIH", "corrected": "lần thứ XIII"}, {"page": 387, "ocr": "hành Trung ương Đảng khóa XII", "corrected": "hành Trung ương Đảng khóa XIII"}]}, {"id": "kl", "label": "Kết luận", "title": "Những thắng lợi và bài học kinh nghiệm", "period": "Tổng kết", "startPage": 409, "endPage": 434, "summary": "Kết nối các thời kỳ lịch sử qua ba nhóm thắng lợi lớn và năm bài học về sự lãnh đạo của Đảng. Nội dung tổng kết bám giáo trình năm 2021, gắn với truyền thống đoàn kết, tự phê bình và liên hệ mật thiết với nhân dân.", "sections": [{"id": "kl-s1", "title": "Khái quát tiến trình lịch sử", "pages": [409, 413], "summary": "Nhìn lại các thời kỳ từ tìm đường cứu nước, thành lập Đảng đến cách mạng, kháng chiến và đổi mới.", "points": ["Chuẩn bị điều kiện thành lập Đảng, lãnh đạo đấu tranh giành chính quyền.", "Lãnh đạo bảo vệ chính quyền và các cuộc kháng chiến.", "Lãnh đạo xây dựng chủ nghĩa xã hội và công cuộc đổi mới."]}, {"id": "kl-s2", "title": "Những thắng lợi vĩ đại", "pages": [413, 423], "summary": "Ba nhóm thắng lợi lớn gắn với các bước chuyển căn bản của cách mạng Việt Nam.", "points": ["Cách mạng Tháng Tám 1945, thành lập Nhà nước Việt Nam Dân chủ Cộng hòa.", "Các cuộc kháng chiến giải phóng dân tộc, bảo vệ Tổ quốc, thống nhất đất nước.", "Đổi mới và từng bước đưa đất nước quá độ lên chủ nghĩa xã hội."]}, {"id": "kl-s3", "title": "Những bài học lớn về sự lãnh đạo của Đảng", "pages": [423, 432], "summary": "Năm bài học kết nối mục tiêu, lực lượng, đoàn kết, quốc tế và sự lãnh đạo.", "points": ["Độc lập dân tộc gắn liền với chủ nghĩa xã hội.", "Sự nghiệp cách mạng của nhân dân, do nhân dân, vì nhân dân.", "Củng cố đoàn kết; kết hợp sức mạnh dân tộc với sức mạnh thời đại.", "Sự lãnh đạo đúng đắn của Đảng là nhân tố hàng đầu quyết định thắng lợi."]}, {"id": "kl-s4", "title": "Truyền thống và ý nghĩa tổng kết", "pages": [432, 434], "summary": "Lịch sử Đảng làm nổi bật truyền thống, sự hy sinh và những kinh nghiệm cần tiếp tục phát huy.", "points": ["Kiên cường, bất khuất vì nước, vì dân; đoàn kết, thống nhất.", "Tự phê bình, phê bình và quyết tâm sửa chữa khuyết điểm.", "Gắn bó với nhân dân, rèn luyện đạo đức, chủ nghĩa quốc tế trong sáng."]}], "questions": [{"id": "kl-q001", "section": "kl-s2", "prompt": "Nhóm thắng lợi vĩ đại đầu tiên được phần Kết luận của giáo trình nêu ra là gì?", "options": ["Cách mạng Tháng Tám 1945 và thành lập Nhà nước Việt Nam Dân chủ Cộng hòa", "Gia nhập WTO", "Công cuộc đổi mới từ 1986", "Thông qua Hiến pháp 1980"], "answer": 0, "explanation": "Kết luận nêu trước hết thắng lợi của Cách mạng Tháng Tám 1945, thành lập Nhà nước Việt Nam Dân chủ Cộng hòa.", "page": 413, "evidence": " thắng lợi vĩ đại của cách mạng Việt Nam: Một là, thắng lợi của cuộc Cách mạng Tháng Tám năm 1945, thành lập Nhà nước Việt Nam Dân chủ Cộng hòa. Thắng lợi đó đã đánh đổ chế độ thuộc địa của thực dân Pháp và phátxít Nhật, xóa bỏ chế độ phong kiến hàng nghìn năm, giành ", "type": "mcq"}, {"id": "kl-q002", "section": "kl-s2", "prompt": "Nhóm thắng lợi lớn thứ hai trong phần Kết luận gắn với nội dung nào?", "options": ["Chỉ các hoạt động thương mại quốc tế", "Chỉ các cuộc cải cách giáo dục", "Chỉ việc thay đổi cơ chế giá–lương–tiền", "Các cuộc kháng chiến giải phóng dân tộc, bảo vệ Tổ quốc, thống nhất đất nước"], "answer": 3, "explanation": "Nhóm thứ hai là thắng lợi của các cuộc kháng chiến, hoàn thành cách mạng dân tộc dân chủ nhân dân và thống nhất Tổ quốc.", "page": 415, "evidence": "hành công, đã nắm chính quyền toàn quốở”. Hai là, thắng lợi của các cuộc kháng chiến oanh hệt đế giải phóng dân tộc, bảo vệ Tổ quốc, đánh thắng chủ nghĩa thực dân cũ và mới, hoàn thành cách mạng dân tộc dân chủ nhân dân, thực hiện thống nhất Tổ quốc, đưa cả nước đ", "type": "mcq"}, {"id": "kl-q003", "section": "kl-s2", "prompt": "Nhóm thắng lợi lớn thứ ba trong phần Kết luận là gì?", "options": ["Chỉ việc thành lập các tổ chức cộng sản 1929", "Chỉ phong trào dân chủ 1936–1939", "Sự nghiệp đổi mới và từng bước đưa đất nước quá độ lên chủ nghĩa xã hội", "Chỉ chiến dịch Biên giới 1950"], "answer": 2, "explanation": "Phần Kết luận nêu thắng lợi của sự nghiệp đổi mới là nhóm thắng lợi lớn thứ ba.", "page": 418, "evidence": "hể đánh bại mọi thế lực đế quốc xâm lược”. Ba là, thắng lợi của sự nghiệp đổi mới và từng bước đưa đất nước quá độ lên chủ nghĩa xã hội. Sự nghiệp đổi mới là kế thừa những thành tựu và kinh nghiệm xây dựng chủ nghĩa xã hội ở miền Bắc khi còn chiến tranh và tron", "type": "mcq"}, {"id": "kl-q004", "section": "kl-s2", "prompt": "Phần Kết luận khái quát đường lối kháng chiến chống Pháp theo những nội dung nào?", "options": ["Chỉ đấu tranh ngoại giao", "Toàn dân, toàn diện, lâu dài, dựa vào sức mình là chính", "Chỉ dựa vào viện trợ bên ngoài", "Đánh nhanh kết thúc chiến tranh bằng một trận duy nhất"], "answer": 1, "explanation": "Giáo trình nêu đường lối kháng chiến toàn dân, toàn diện, lâu dài và dựa vào sức mình là chính.", "page": 416, "evidence": "n và sáng tạo của Đảng. Với đường lối kháng chiến toàn dân, toàn diện, lâu dài và đựa vào sức mình là chính, vận dụng lý luận chủ nghĩa Mác - Lênin về chiến tranh cách mạng, giải phóng và bảo vệ Tổ quốc, kế thừa truyền thống đánh giặc, giữ nước của dân tộc, ", "type": "mcq"}, {"id": "kl-q005", "section": "kl-s2", "prompt": "Ba mũi giáp công được phần Kết luận nêu trong kháng chiến chống Mỹ gồm những gì?", "options": ["Quân sự, chính trị, binh vận", "Kinh tế, văn hóa, giáo dục", "Giá, lương, tiền", "Công nghiệp, nông nghiệp, dịch vụ"], "answer": 0, "explanation": "Ba mũi giáp công là quân sự, chính trị và binh vận, kết hợp với nhiều hình thức và phương pháp đấu tranh.", "page": 417, "evidence": "ng và thành thị; đánh địch bằng ba mũi giáp công: quân sự, chính trị, binh vận; kết hợp ba thứ quân, kết hợp chiến tranh du kích với chiến tranh chính quy, kết hợp đánh lớn, đánh vừa, đánh nhỏ; thực hiện làm chủ để tiêu điệt địch, tiêu diệt địch để làm chủ. ", "type": "mcq"}, {"id": "kl-q006", "section": "kl-s3", "prompt": "Bài học lớn đầu tiên về sự lãnh đạo của Đảng là gì?", "options": ["Tách độc lập dân tộc khỏi phát triển đất nước", "Chỉ ưu tiên sức mạnh bên ngoài", "Chỉ chú trọng một thành phần kinh tế", "Nắm vững ngọn cờ độc lập dân tộc và chủ nghĩa xã hội"], "answer": 3, "explanation": "Năm bài học lớn mở đầu bằng việc nắm vững ngọn cờ độc lập dân tộc và chủ nghĩa xã hội.", "page": 423, "evidence": "Những bài học lớn về sự lãnh đạo của Đảng Một là, nắm vững ngọn cờ độc lập dân tộc và chủ nghĩa xã hội. Học thuyết cách mạng, khoa học Mác - Lênin soi sáng sự nghiệp đấu tranh giải phóng giai cấp công nhân, giải phồng các đân tộc, giải phóng con người thoát khỏi", "type": "mcq"}, {"id": "kl-q007", "section": "kl-s3", "prompt": "Quan hệ giữa độc lập dân tộc và chủ nghĩa xã hội được giáo trình khái quát như thế nào?", "options": ["Hai mục tiêu hoàn toàn không liên quan", "Chỉ cần một mục tiêu, có thể bỏ mục tiêu còn lại", "Độc lập là điều kiện tiên quyết; chủ nghĩa xã hội bảo đảm vững chắc độc lập dân tộc", "Độc lập chỉ là vấn đề đối ngoại"], "answer": 2, "explanation": "Độc lập dân tộc và chủ nghĩa xã hội gắn bó mật thiết, được giáo trình trình bày như quy luật phát triển của cách mạng Việt Nam.", "page": 424, "evidence": "ân giàu, nước mạnh, dân chủ, công bằng, văn mình. Độc lập đân tộc là điều kiện tiên quyết để thực hiện chủ nghĩa xã hội và chủ nghĩa xã hội là cơ sở bảo đảm vững chắc cho độc lập dân tộc. Xây dựng chủ nghĩa xã hội và bảo vệ Tổ quốc xã hội chủ nghĩa là hai nhiệm vụ chiế", "type": "mcq"}, {"id": "kl-q008", "section": "kl-s3", "prompt": "Bài học về chủ thể và mục đích của sự nghiệp cách mạng được diễn đạt thế nào?", "options": ["Chỉ của một nhóm cán bộ chuyên trách", "Của nhân dân, do nhân dân và vì nhân dân", "Chỉ vì lợi ích kinh tế trước mắt", "Chỉ do lực lượng bên ngoài tiến hành"], "answer": 1, "explanation": "Nhân dân là chủ thể của lịch sử; cách mạng phải dựa vào nhân dân và phục vụ lợi ích của nhân dân.", "page": 424, "evidence": " và xây dựng thành công chủ nghĩa xã hội. Hai là, sự nghiệp cách mạng là của nhân dân, do nhân dân và vì nhân dân. Cách mạng là sự nghiệp của quần chúng nhân dân, nhân dân là người làm nên lịch sử, là chủ thể của lịch sử, đó là quan điểm cơ bản trong lý luận Mác - ", "type": "mcq"}, {"id": "kl-q009", "section": "kl-s3", "prompt": "Theo phần Kết luận, sức mạnh của Đảng gắn với điều gì?", "options": ["Sự gắn bó mật thiết với nhân dân", "Việc tách khỏi đời sống nhân dân", "Việc chỉ dựa vào kinh nghiệm bên ngoài", "Việc không cần tự phê bình"], "answer": 0, "explanation": "Giáo trình nhấn mạnh mối liên hệ mật thiết với nhân dân là nguồn sức mạnh của Đảng.", "page": 425, "evidence": "ới nhân dân, từng trải đấu tranh mà trưởng thành. Sức mạnh của Đảng là ở sự gắn bó mật thiết với nhân dân. Nhân dân là người bảo vệ Đảng, giúp đỡ Đảng về mọi mặt trong sự nghiệp dấu tranh giải phóng dân tộc và chính 1. Hồ Chí Minh: Toàn tập, Sđd, t.9, tr.292, 3.", "type": "mcq"}, {"id": "kl-q010", "section": "kl-s3", "prompt": "Bài học lớn thứ ba nhấn mạnh những phạm vi đoàn kết nào?", "options": ["Chỉ đoàn kết trong một địa phương", "Chỉ đoàn kết trong một nghề nghiệp", "Chỉ đoàn kết ở cấp trung ương", "Toàn Đảng, toàn dân, dân tộc và quốc tế"], "answer": 3, "explanation": "Đoàn kết được đặt trên cả phạm vi trong Đảng, trong nhân dân, dân tộc và quốc tế.", "page": 426, "evidence": " Ba là, không ngừng củng cố. tăng cường đoàn kết, đoàn kết toàn Đảng, đoàn kết toàn dân, đoàn kết dân tộc, đoàn kết quốc tế. Đoàn kết là nguyên tắc của Đảng chân chính cách mạng. Trong Tuyên ngôn của Đảng Cộng sản (1848), 1. Hồ Chí Minh: Toàn tập, Sđd, t.6, tr.234. 4", "type": "mcq"}, {"id": "kl-q011", "section": "kl-s3", "prompt": "Bài học lớn thứ tư yêu cầu kết hợp những nguồn sức mạnh nào?", "options": ["Chỉ nguồn lực bên ngoài, bỏ nội lực", "Chỉ nguồn lực vật chất, bỏ con người", "Sức mạnh dân tộc với sức mạnh thời đại, trong nước với quốc tế", "Chỉ sức mạnh quân sự, bỏ chính trị"], "answer": 2, "explanation": "Giáo trình nhấn mạnh kết hợp nguồn lực và sức mạnh trong nước với quốc tế, đồng thời coi trọng tự lực, tự cường.", "page": 428, "evidence": "ư ở nước ngoài, tạo sự đồng thuận xã hội. Bốn là, kết hợp sức mạnh dân tộc với sức mạnh thời đại, sức mạnh trong nước với sức mạnh quốc tết Chủ nghĩa Mác - Lênin mang bản chất quốc tế, cách mạng của giai cấp vô sản, không chỉ giải phóng giai cấp lao động trong một nước mà", "type": "mcq"}, {"id": "kl-q012", "section": "kl-s3", "prompt": "Bài học lớn thứ năm xác định nhân tố hàng đầu quyết định thắng lợi của cách mạng Việt Nam là gì?", "options": ["Chỉ điều kiện địa lý thuận lợi", "Sự lãnh đạo đúng đắn của Đảng", "Chỉ sự viện trợ từ bên ngoài", "Chỉ sự phát triển tự phát của thị trường"], "answer": 1, "explanation": "Kết luận xác định sự lãnh đạo đúng đắn của Đảng là nhân tố hàng đầu quyết định thắng lợi.", "page": 429, "evidence": "chủ và con đường phát triển của đất nước. Năm là, sự lãnh đạo đúng đắn của Đảng là nhân tố hàng đầu quyết định thắng lợi của cách mạng Việt Nam. Các nhà kinh điển của chủ nghĩa Mác - Lênin đặc biệt chú trọng xây dựng Đảng Cộng sản - đội tiền phong của giai cấ", "type": "mcq"}, {"id": "kl-q013", "section": "kl-s3", "prompt": "Nguyên tắc tổ chức cơ bản của Đảng được phần Kết luận khẳng định là gì?", "options": ["Tập trung dân chủ", "Mỗi tổ chức tự đặt mọi nguyên tắc riêng", "Không cần kỷ luật tổ chức", "Chỉ tập trung, không có dân chủ"], "answer": 0, "explanation": "Giáo trình khẳng định tập trung dân chủ là nguyên tắc tổ chức cơ bản, cùng các nguyên tắc đoàn kết, tự phê bình và gắn bó với nhân dân.", "page": 430, "evidence": "tư tưởng và kim chỉ nam cho hành động. Khẳng định tập trung dân chủ là nguyên tắc tổ chức cơ bản của Đảng, đồng thời chú trọng các nguyên tắc đoàn kết, thống nhất trong Đảng; tự phê bình và phê bình; gắn bó mật thiết với nhân dân và nguyên tắc của chủ nghĩa quốc tế vô ", "type": "mcq"}, {"id": "kl-q014", "section": "kl-s4", "prompt": "Truyền thống tự phê bình và phê bình của Đảng gắn liền với yêu cầu nào?", "options": ["Chỉ nêu thành tích, tránh nêu thiếu sót", "Chỉ phê bình người khác, không tự phê bình", "Coi khuyết điểm là không thể sửa chữa", "Quyết tâm sửa chữa khuyết điểm, hạn chế, yếu kém"], "answer": 3, "explanation": "Phần Kết luận đặt tự phê bình, phê bình nghiêm túc đi liền quyết tâm sửa chữa khuyết điểm.", "page": 432, "evidence": " Truyền thống tự phê bình, phê bình nghiêm túc và quyết tâm sửa chữa những khuyết điểm, hạn chế, yếu kém. Truyền thống gắn bó mật thiết với giai cấp công nhân, nhân đân lao động và toàn dân tộc. Truyền thống rên luyện phẩm chất, đạo đức, nâng cao bản lĩnh tự vượt qu", "type": "mcq"}, {"id": "kl-q015", "section": "kl-s4", "prompt": "Truyền thống nào được phần Kết luận nêu cùng với đoàn kết và gắn bó với nhân dân?", "options": ["Bỏ qua công tác cán bộ", "Tách tổ chức khỏi quần chúng", "Rèn luyện phẩm chất, đạo đức, bản lĩnh vượt qua khó khăn", "Chỉ coi trọng số lượng tổ chức"], "answer": 2, "explanation": "Giáo trình nêu rèn luyện phẩm chất, đạo đức, nâng cao bản lĩnh vượt khó và chủ nghĩa quốc tế trong sáng là những truyền thống cần phát huy.", "page": 432, "evidence": "n tộc. Truyền thống rên luyện phẩm chất, đạo đức, nâng cao bản lĩnh tự vượt qua mọi khó khăn, thách thức. Truyền thống của chủ nghĩa quốc tế trong sáng. Lịch sử Đảng Cộng sản Việt Nam tôn vinh sự hy sinh anh dũng của các thế hệ cán bộ, đẳng viên trong toà", "type": "mcq"}], "timeline": [], "reviewPrompts": [], "mindmap": {"title": "Thắng lợi và bài học", "branches": [{"id": "kl-b1", "title": "Cách mạng Tháng Tám 1945", "page": 413, "summary": "Giành độc lập, lập Nhà nước Việt Nam Dân chủ Cộng hòa.", "children": [{"title": "Ý nghĩa", "page": 413, "note": "Mở kỷ nguyên độc lập, tự do và nhân dân làm chủ."}, {"title": "Thời cơ", "page": 415, "note": "Chủ động chuẩn bị thực lực, chớp thời cơ và đẩy lùi nguy cơ."}]}, {"id": "kl-b2", "title": "Các cuộc kháng chiến", "page": 415, "summary": "Giải phóng dân tộc, bảo vệ Tổ quốc, thống nhất đất nước.", "children": [{"title": "Đường lối", "page": 416, "note": "Toàn dân, toàn diện, lâu dài, tự lực là chính."}, {"title": "Phương pháp", "page": 417, "note": "Kết hợp quân sự, chính trị, ngoại giao và ba mũi giáp công."}]}, {"id": "kl-b3", "title": "Sự nghiệp đổi mới", "page": 418, "summary": "Từng bước đưa đất nước quá độ lên chủ nghĩa xã hội.", "children": [{"title": "Cơ sở thực tiễn", "page": 419, "note": "Sáng kiến, nguyện vọng và lợi ích của nhân dân."}, {"title": "Nhận thức lý luận", "page": 421, "note": "Làm rõ mô hình và con đường đi lên chủ nghĩa xã hội."}]}, {"id": "kl-b4", "title": "Độc lập dân tộc và chủ nghĩa xã hội", "page": 423, "summary": "Kiên định hai mục tiêu chiến lược gắn bó với nhau.", "children": [{"title": "Quan hệ", "page": 424, "note": "Độc lập là điều kiện tiên quyết; chủ nghĩa xã hội bảo đảm vững chắc độc lập."}, {"title": "Nhiệm vụ", "page": 424, "note": "Xây dựng chủ nghĩa xã hội gắn với bảo vệ Tổ quốc."}]}, {"id": "kl-b5", "title": "Của dân, do dân, vì dân", "page": 424, "summary": "Nhân dân là chủ thể, nguồn sức mạnh của cách mạng.", "children": [{"title": "Gắn bó mật thiết", "page": 425, "note": "Hoạt động của Đảng xuất phát từ lợi ích, nguyện vọng chính đáng."}, {"title": "Công tác dân vận", "page": 426, "note": "Hiểu dân, tin dân, gần dân, bàn bạc với dân, vì dân."}]}, {"id": "kl-b6", "title": "Đoàn kết", "page": 426, "summary": "Đoàn kết toàn Đảng, toàn dân, dân tộc và quốc tế.", "children": [{"title": "Điểm tương đồng", "page": 427, "note": "Lợi ích chung của quốc gia, dân tộc."}, {"title": "Mặt trận và đoàn thể", "page": 428, "note": "Tập hợp mọi giai cấp, tầng lớp, dân tộc, tôn giáo và kiều bào."}]}, {"id": "kl-b7", "title": "Sức mạnh dân tộc và thời đại", "page": 428, "summary": "Kết hợp nguồn lực trong nước với quốc tế.", "children": [{"title": "Tự lực, tự cường", "page": 429, "note": "Dựa vào sức mình là chính và tranh thủ sự giúp đỡ quốc tế."}, {"title": "Đối ngoại", "page": 429, "note": "Độc lập, tự chủ, hòa bình, hợp tác, phát triển, hội nhập."}]}, {"id": "kl-b8", "title": "Sự lãnh đạo của Đảng", "page": 429, "summary": "Nhân tố hàng đầu quyết định thắng lợi.", "children": [{"title": "Xây dựng Đảng", "page": 430, "note": "Lý luận, Cương lĩnh, tổ chức, cán bộ và đạo đức."}, {"title": "Đổi mới, chỉnh đốn", "page": 431, "note": "Phòng ngừa sai lầm, quan liêu, xa dân và suy thoái."}, {"title": "Truyền thống", "page": 432, "note": "Kiên cường, đoàn kết, tự phê bình, gắn bó nhân dân, quốc tế trong sáng."}]}]}, "sourceCorrections": [{"page": 432, "ocr": "rên luyện phẩm chất, đạo đức", "corrected": "rèn luyện phẩm chất, đạo đức"}]}]};
